const bioExpGen=code=>(r,o)=>sciExpQ(r,o,BIO_EXP.filter(e=>e.codes.includes(code)));
function sciExpQ(r,o,list){const e=o.pick(r,list||SCI_EXP),kind=o.pick(r,["iv","dv","const","concl"]);
 const tbl={h:[e.iv[0].toUpperCase()+e.iv.slice(1),`${e.dv[0].toUpperCase()+e.dv.slice(1)} (${e.unit})`],t:e.lv.map((l,i)=>[l,String(e.data[i])])};
 const it=kind==="iv"?{stem:`A class wants to find out ${e.q}. Which is the independent variable (the one the students change on purpose)?`,right:e.iv[0].toUpperCase()+e.iv.slice(1),w:[[e.dv[0].toUpperCase()+e.dv.slice(1),"That is what the students measure: the dependent variable."],[e.c[0][0].toUpperCase()+e.c[0].slice(1),"That stays the same in every trial: it is a constant."],["The number of students in the class","That has nothing to do with this test."]],steps:`The independent variable is the one thing the scientist changes on purpose.|Here the students change the ${e.iv}.`,x:{}}
  :kind==="dv"?{stem:`A class wants to find out ${e.q}. Which is the dependent variable (the one the students measure)?`,right:e.dv[0].toUpperCase()+e.dv.slice(1),w:[[e.iv[0].toUpperCase()+e.iv.slice(1),"That is what the students change on purpose: the independent variable."],[e.c[1][0].toUpperCase()+e.c[1].slice(1),"That is kept the same: a constant."],["The day of the week","That isn’t part of this investigation."]],steps:`The dependent variable is what you measure to see the effect.|Here the students measure the ${e.dv}.`,x:{}}
  :kind==="const"?{stem:`A class wants to find out ${e.q}. To make it a fair test, which should stay the SAME in every trial?`,right:e.c[0][0].toUpperCase()+e.c[0].slice(1),w:[[e.iv[0].toUpperCase()+e.iv.slice(1),"That is what is being tested, so it must change."],[e.dv[0].toUpperCase()+e.dv.slice(1),"That is the result being measured, so it can change."],["Nothing needs to stay the same","A fair test changes only one variable at a time."]],steps:"In a fair test, only one variable changes.|Everything else stays the same so the results can be compared.",x:{}}
  :e.flat?{stem:`Students tested ${e.q}. Their results are in the table.\nWhich conclusion is BEST supported by the data?`,right:`Changing the ${e.iv} did not change the ${e.dv}.`,w:[[`A larger ${e.iv} made the ${e.dv} longer.`,"Look at the numbers: they stay the same."],[`A larger ${e.iv} made the ${e.dv} shorter.`,"The data don’t change from trial to trial."],["The experiment needs no more trials.","Scientists repeat trials to be sure."]],steps:"Look at how the measured result changes down the table.|Every result is the same, so this variable had no effect.",x:tbl}
  :e.cat?(()=>{const mx=e.data.indexOf(Math.max(...e.data)),mn=e.data.indexOf(Math.min(...e.data));return {stem:`Students tested ${e.q}. Their results are in the table.\nWhich conclusion is BEST supported by the data?`,right:`The ${e.lv[mx]} trial had the greatest ${e.dv}.`,w:[[`The ${e.lv[mn]} trial had the greatest ${e.dv}.`,`The ${e.lv[mn]} trial had the smallest result, ${e.data[mn]}.`],["All the results were about the same.","The results are different from each other."],[`The ${e.iv} has no effect on the ${e.dv}.`,"The results changed when the "+e.iv+" changed."]],steps:`Find the largest number in the results column: ${Math.max(...e.data)}.|It goes with the ${e.lv[mx]}.`,x:tbl}})()
  :{stem:`Students tested ${e.q}. Their results are in the table.\nWhich conclusion is BEST supported by the data?`,right:e.dec?`With ${e.more}, the ${e.dv} went down.`:`With ${e.more}, the ${e.dv} went up.`,w:[[e.dec?`With ${e.more}, the ${e.dv} went up.`:`With ${e.more}, the ${e.dv} went down.`,"Read the table from top to bottom and watch which way the numbers go."],[`The ${e.iv} had no effect.`,"The results changed when the "+e.iv+" changed."],["The results were the same in every trial.","Compare the numbers: they are different."]],steps:"Read the table from top to bottom.|"+(e.dec?"As the first column increases, the results get smaller.":"As the first column increases, the results get larger."),x:tbl};
 return o.fromItem(it,r)}

/* ===== Science Grade 4 (original items) ===== */
SO("L.4.1.1","Organ systems working together","Use technology or other resources to research and discover general system function (e.g., machines, water cycle) as they relate to human organ systems and identify organs that work together to create organ systems.","Students will demonstrate an understanding of the organization, functions, and interconnections of the major human body systems.");
SI("L.4.1.1","Which organs work together in the DIGESTIVE system?","Stomach, intestines, and esophagus","Heart, arteries, and veins~Those are the circulatory system.","Lungs, trachea, and nose~Those are the respiratory system.","Brain, spinal cord, and nerves~Those are the nervous system.","The digestive system breaks down food.|Food moves from the esophagus to the stomach to the intestines.");
SI("L.4.1.1","A group of organs that work together to do a job is called —","an organ system","a cell~A cell is the smallest living unit.","a tissue~A tissue is a group of similar cells.","an organism~An organism is a whole living thing.","Cells → tissues → organs → organ systems → organism.");
SI("L.4.1.1","The heart pumps blood through tubes to every part of the body. Which machine works MOST like this?","A pump pushing water through pipes","A fan blowing air around a room~A fan moves air, not liquid through tubes.","A light switch on a wall~A switch turns power on and off.","A pair of sharp scissors~Scissors cut.","The heart is a pump.|Blood vessels are like pipes.");
SO("L.4.1.2","How body systems interact","Obtain and communicate data to describe patterns that indicate the nature of relationships between human organ systems, which interact with one another to control digestion, respiration, circulation, excretion, movement, coordination, and protection from disease.");
SI("L.4.1.2","When you run, your heart beats faster. How does this help your muscles?","It sends more oxygen to the muscles.","It makes the muscles smaller.~Muscles need oxygen to work.","It stops the muscles from moving.~Muscles keep moving.","It sends less blood to the muscles.~It sends MORE blood.","Muscles need more oxygen during exercise.|The heart and lungs work harder to deliver it.");
SI("L.4.1.2","Which two systems work together to get oxygen to the body’s cells?","Respiratory and circulatory","Digestive and skeletal~They don’t move oxygen.","Nervous and muscular~They control movement.","Skeletal and muscular~They help you move.","Lungs take in oxygen.|Blood carries it to every cell.");
SI("L.4.1.2","You touch a hot stove and pull your hand away fast. Which systems work together?","Nervous and muscular","Digestive and respiratory~They don’t control movement.","Circulatory and digestive~They don’t sense heat.","Skeletal and respiratory~They don’t sense heat.","Nerves sense the heat and send a signal.|Muscles move your hand.");
SO("L.4.1.3","Models of organ systems","Construct models of organ systems (e.g., circulatory, digestive, respiratory, muscular, skeletal, nervous) to demonstrate both the unique function of the system and how multiple organs and organ systems work together to accomplish specific tasks.");
SI("L.4.1.3","Which system supports the body and protects organs like the brain and heart?","Skeletal system","Digestive system~It breaks down food.","Respiratory system~It brings in air.","Circulatory system~It moves blood.","Bones support the body.|The skull protects the brain, and the ribs protect the heart and lungs.");
SI("L.4.1.3","A model uses a balloon inside a bottle that fills when air is pulled in. Which organ does the balloon stand for?","Lung","Heart~The heart pumps blood, not air.","Stomach~The stomach holds food.","Brain~The brain controls the body.","The balloon fills with air like a lung does when you breathe in.");
SI("L.4.1.3","What is the MAIN job of the nervous system?","To carry messages to and from the brain","To pump blood to the whole body~That is the heart.","To break food down into nutrients~That is digestion.","To hold the body up straight~That is the skeleton.","The brain, spinal cord, and nerves carry messages that control the body.");
SO("L.4.1.4","Diseases and body systems","Research and communicate how noninfectious diseases (e.g., diabetes, heart disease) and infectious diseases (e.g., cold, flu) serve to disrupt the function of the body system.");
SI("L.4.1.4","Which disease is INFECTIOUS, meaning it can spread from person to person?","The flu","Diabetes~Diabetes doesn’t spread between people.","Heart disease~Heart disease isn’t caught from others.","A broken bone~That is an injury.","Germs like viruses cause infectious diseases.|The flu spreads through coughs and sneezes.");
SI("L.4.1.4","Which habit BEST helps stop the spread of colds?","Washing hands with soap","Sharing water bottles~That can spread germs.","Coughing into your hand and touching doors~That spreads germs.","Skipping sleep~Rest helps the body fight germs.","Soap and water remove germs from your hands.");
SI("L.4.1.4","Heart disease MOSTLY affects which body system?","Circulatory system","Digestive system~Heart disease affects the heart and blood vessels.","Skeletal system~Bones aren’t the main target.","Nervous system~The heart is part of the circulatory system.","The heart and blood vessels make up the circulatory system.");
SO("L.4.1.5","Science and a healthy body","Using informational text, investigate how scientific fields, medical specialties, and research methods help us find new ways to maintain a healthy body and lifestyle (e.g., diet, exercise, vaccines, and mental health).");
SI("L.4.1.5","How do vaccines help keep people healthy?","They train the body to fight a germ.","They make people grow taller and stronger.~Vaccines protect against disease.","They replace healthy food.~You still need healthy food.","They cure every illness a person has.~Each vaccine protects against certain germs.","A vaccine helps the immune system learn to recognize a germ before you get sick.");
SI("L.4.1.5","Which daily choice does the MOST to keep the heart and lungs strong?","Getting regular exercise","Drinking soda every day~Sugary drinks aren’t healthy.","Staying up very late~The body needs sleep.","Skipping breakfast often~Healthy meals give energy.","Exercise makes the heart and lungs work and grow stronger.");
SI("L.4.1.5","A doctor who mainly treats children is called a —","pediatrician","dentist~A dentist cares for teeth.","veterinarian~A veterinarian treats animals.","pharmacist~A pharmacist prepares medicines.","Pediatricians are doctors for children.");
SO("L.4.2.1","Comparing life cycles","Compare and contrast life cycles of familiar plants and animals.","Students will demonstrate an understanding of life cycles, including familiar plants and animals (e.g., reptiles, amphibians, or birds).");
SI("L.4.2.1","How are the life cycles of a bean plant and a chicken ALIKE?","Both grow and make offspring.","Both start as seeds in the soil.~A chicken starts as an egg.","Both hatch from eggs in a nest.~A bean plant starts as a seed.","Both live only one day.~Both live much longer.","All living things are born or sprout, grow, reproduce, and die.");
SI("L.4.2.1","Which stage comes right after the egg in a frog’s life cycle?","Tadpole","Adult frog~The tadpole stage comes first.","Froglet~That comes after the tadpole.","Seed~Frogs don’t have seeds.","Egg → tadpole → froglet → adult frog.");
SI("L.4.2.1","Which animal’s young look very much like the adult?","A puppy","A caterpillar~A caterpillar changes into a butterfly.","A tadpole~A tadpole changes into a frog.","A larva~A larva changes a lot.","Mammals like dogs are born looking like small versions of their parents.");
SO("L.4.2.2","Models of life cycles","Develop and use models to explain the unique and diverse life cycles of organisms other than humans (e.g., flowering plants, frogs, or butterflies) including commonalities (e.g., birth, growth, reproduction, or death).");
SI("L.4.2.2","What is the correct order of a butterfly’s life cycle?","Egg, larva, pupa, adult","Egg, pupa, larva, adult~The larva (caterpillar) comes before the pupa.","Larva, egg, adult, pupa~It starts with an egg.","Adult, pupa, egg, larva~That is mixed up.","A butterfly goes through complete metamorphosis: egg → caterpillar → chrysalis → butterfly.");
SI("L.4.2.2","In a flowering plant’s life cycle, what forms after a flower is pollinated?","Seeds","Roots~Roots grow from a seed.","Leaves~Leaves grow as the plant grows.","Pollen~Pollen is needed for pollination.","After pollination, the flower makes seeds, often inside a fruit.");
SI("L.4.2.2","What do ALL life cycles have in common?","Growing and making new offspring","Changing from water to land~Only some animals do that.","Making a cocoon~Only some insects do that.","Laying eggs~Many animals give birth to live young.","Every life cycle includes growth and reproduction.");
SO("P.4.6A.1","Sources of heat","Obtain and communicate information to compare how different processes (including burning, friction, and electricity) serve as sources of heat energy.","Students will demonstrate an understanding of the common sources and uses of heat and electric energy and the materials used to transfer heat and electricity.");
SI("P.4.6A.1","You rub your hands together quickly and they feel warm. What makes the heat?","Friction","Electricity~No electricity is used.","Burning~Nothing is burning.","Sunlight~Rubbing makes the heat.","Rubbing surfaces together creates friction, which makes heat.");
SI("P.4.6A.1","Which is an example of electricity producing heat?","A toaster warming bread","A campfire~That is burning.","Sliding down a slide~That is friction.","Ice melting in the sun~That is heat from the Sun.","Electricity flows through the toaster’s wires and makes them hot.");
SI("P.4.6A.1","Which process gives off heat by BURNING fuel?","A gas stove cooking food","A fan cooling a room~A fan doesn’t burn fuel.","An ice pack on a knee~Ice packs remove heat.","A flashlight shining~Flashlights use batteries, not burning.","A gas stove burns natural gas, which releases heat.");
SO("P.4.6A.2","Conductors and insulators","Plan and conduct scientific investigations to classify different materials as either an insulator or conductor of electricity.");
SI("P.4.6A.2","Electric wires are made of copper covered in plastic. Why?","Copper conducts electricity and plastic insulates.","Copper insulates and plastic conducts.~It is the other way around.","Both copper and plastic conduct electricity.~Plastic is an insulator.","The plastic makes the copper heavier.~The plastic protects people.","Copper carries the current.|Plastic keeps it from flowing into your hand.");
SI("P.4.6A.2","Which material is an electrical INSULATOR?","Rubber","Copper~Copper is a conductor.","Aluminum~Aluminum is a conductor.","Steel~Steel is a conductor.","Insulators block the flow of electricity.|Rubber, plastic, glass, and wood are insulators.");
SO("P.4.6A.3","Energy changes form","Develop models demonstrating how heat and electrical energy can be transformed into other forms of energy (e.g., motion, sound, heat, or light).");
SI("P.4.6A.3","A battery-powered fan is turned on. Electrical energy changes MAINLY into —","motion energy","light energy~The fan’s job is to spin.","chemical energy~The battery already stores chemical energy.","sound energy only~The fan mostly moves.","The motor turns electrical energy into the spinning motion of the blades.");
SI("P.4.6A.3","A lamp changes electrical energy into —","light and heat","motion and sound~A lamp doesn’t move.","chemical energy~Lamps don’t store energy.","only sound~Lamps give light.","A bulb glows (light) and gets warm (heat).");
SI("P.4.6A.3","A doorbell rings when you press the button. What energy change happens?","Electrical energy becomes sound energy.","Sound energy becomes electrical energy.~That is backward.","Light energy becomes heat.~The doorbell makes sound.","Heat becomes motion.~Electricity powers the bell.","Pressing the button completes a circuit, and the bell turns electricity into sound.");
SO("P.4.6A.4","Simple circuits","Develop models that demonstrate the path of an electric current in a complete, simple circuit (e.g., lighting a light bulb or making a sound).");
SI("P.4.6A.4","A bulb, a battery, and wires are connected, but the bulb won’t light. What is the MOST likely problem?","There is a gap in the circuit.","The circuit is a complete loop.~A complete loop would light the bulb.","The wires are made of copper.~Copper is a good conductor.","The battery has too much energy.~That isn’t the problem.","Electricity needs a complete, closed path.|A gap stops the current.");
SI("P.4.6A.4","In a simple circuit, what does the switch do?","Opens or closes the path for current","Stores the electricity for later~A battery stores energy.","Makes the bulb shine brighter~The switch only turns it on or off.","Turns electricity into light~The bulb does that.","A closed switch completes the circuit.|An open switch breaks it.");
SI("P.4.6A.4","What is the energy source in a flashlight circuit?","The battery","The bulb~The bulb uses the energy.","The switch~The switch controls the flow.","The case~The case holds the parts.","Batteries store chemical energy that becomes electrical energy.");
SO("P.4.6A.5","Pioneers of electricity","Use informational text and technology resources to communicate technological breakthroughs made by historical figures in electricity (e.g., Alessandro Volta, Michael Faraday, Nicola Tesla, Thomas Edison, incandescent light bulbs, electric motors, and batteries).");
SI("P.4.6A.5","Alessandro Volta is famous for inventing the first —","battery","light bulb~Edison improved the light bulb.","telephone~Bell invented the telephone.","airplane~The Wright brothers flew the first airplane.","Volta stacked metals and wet cloth to make the first battery.");
SI("P.4.6A.5","Thomas Edison is best known for developing a long-lasting —","light bulb","battery~Volta made the first battery.","electric motor~Faraday’s work led to motors.","telescope~Galileo improved the telescope.","Edison’s team made a practical light bulb that glowed for many hours.");
SI("P.4.6A.5","Michael Faraday discovered that moving a magnet near a coil of wire makes —","electricity","heat only~He found it made electric current.","sound~Moving a magnet doesn’t mainly make sound.","light only~It makes current, which can then make light.","Faraday’s discovery is how generators make electricity today.");
SO("P.4.6A.6","Energy-converting devices (engineering)","Design a device that converts any form of energy from one form to another form (e.g., construct a musical instrument that will convert vibrations to sound by controlling varying pitches, a solar oven that will convert energy from the sun to heat food, or a circuit that will convert electrical energy to light).");
SI("P.4.6A.6","Students build a solar oven from a pizza box. Which choice would make it heat food BEST?","Black paper inside, foil flaps outside","White paper inside and the lid closed~White reflects light, and a closed lid blocks sunlight.","Putting it in the shade~It needs sunlight.","Leaving holes in the plastic window~Holes let heat escape.","Black absorbs heat.|Foil reflects more sunlight into the box.");
SI("P.4.6A.6","A team’s rubber-band guitar makes only one sound. What change would let it play DIFFERENT pitches?","Use rubber bands of different thickness","Paint the box a different color~Color doesn’t change pitch.","Use one longer box for the body~The bands still sound the same.","Pluck all the bands softer~That changes volume, not pitch.","Thinner or tighter bands vibrate faster and make higher pitches.");
SO("P.4.6B.1","White light is many colors","Construct scientific evidence to support the claim that white light is made up of different colors. Include the work of Sir Isaac Newton to communicate results.","Students will demonstrate an understanding of the properties of light as forms of energy.");
SI("P.4.6B.1","Isaac Newton passed sunlight through a prism. What did he discover?","White light is made of many colors.","Prisms create new colors.~The colors were already in the light.","Sunlight has only one color.~It has many colors.","Light can’t pass through glass.~It passed through the prism.","The prism spread white light into a rainbow of colors.");
SI("P.4.6B.1","A rainbow appears after rain when the sun comes out. What causes it?","Water drops split sunlight into colors.","Clouds paint the sky.~Clouds don’t make colors.","The rain turns into colored gas.~Water drops bend light.","The Sun changes color after rain.~The Sun stays the same.","Raindrops act like tiny prisms.");
SI("P.4.6B.1","Which list shows colors found in white light?","Red, orange, yellow, green, blue, violet","Black, white, and gray only~Those are not the colors of the spectrum.","Brown, tan, and gray only~Those don’t appear in a rainbow.","Only red and nothing else~White light has many colors.","White light contains all the colors of the rainbow.");
SO("P.4.6B.2","Seeing objects","Obtain and communicate information to explain how the visibility of an object is related to light.");
SI("P.4.6B.2","Why can’t you see objects in a completely dark room?","No light reflects off them to your eyes.","The objects disappear in the dark.~They are still there.","Your eyes stop working at night.~Eyes need light to see.","Darkness is made of black light.~Darkness is the absence of light.","We see an object when light bounces off it and enters our eyes.");
SI("P.4.6B.2","You can see the Moon at night. What lets you see it?","Sunlight reflecting off the Moon","Light the Moon makes itself~The Moon has no light of its own.","Light from your eyes~Eyes take in light; they don’t shine it.","Light from city streetlights~That is far too weak to light the Moon.","The Moon reflects sunlight to our eyes.");
SO("P.4.6B.3","How light behaves","Develop and use models to communicate how light travels and behaves when it strikes an object, including reflection, refraction, and absorption.");
SI("P.4.6B.3","Light bounces off a mirror. This is called —","reflection","refraction~Refraction is bending of light.","absorption~Absorption takes in light.","shadow~A shadow is where light is blocked.","Smooth, shiny surfaces reflect light.");
SI("P.4.6B.3","How does light travel until it hits something?","In straight lines","In circles~Light travels straight.","Only downward~Light travels in all directions.","In zigzags~It goes straight until it hits something.","Light travels in straight lines, which is why shadows have sharp edges.");
SI("P.4.6B.3","A black shirt gets hot in the sun because it —","absorbs most of the light","reflects all of the light~That would keep it cooler.","bends the light~Bending isn’t why it heats.","makes its own light~Shirts don’t make light.","Dark colors absorb light energy, which turns into heat.");
SO("P.4.6B.4","Transparent, translucent, opaque","Plan and conduct scientific investigations to explain how light behaves when it strikes transparent, translucent, and opaque materials.");
SI("P.4.6B.4","Which material is TRANSLUCENT, letting some light through?","Wax paper","Clear glass~Clear glass is transparent.","A wooden board~Wood is opaque.","A brick~Brick is opaque.","Translucent materials let some light pass, but you can’t see clearly through them.");
SI("P.4.6B.4","A student shines a flashlight at a book. No light passes through. The book is —","opaque","transparent~Transparent lets light through.","translucent~Translucent lets some light through.","reflective only~It blocks the light.","Opaque materials block light completely and make shadows.");
SI("P.4.6B.4","Which would make the darkest shadow?","An aluminum pan","A clear plastic cup~Most light passes through.","A sheet of tissue paper~Some light passes through.","A window~Windows are transparent.","Opaque objects block all the light and make the darkest shadows.");
SO("P.4.6C.1","Pitch and volume","Plan and conduct scientific investigations to test how different variables affect the properties of sound (i.e., pitch and volume).","Students will demonstrate an understanding of the properties of sound as a form of energy.");
SI("P.4.6C.1","A student taps glass bottles filled with different amounts of water. What property of sound is changing?","Pitch","Volume only~The pitch changes with the water level.","Speed of light~Sound, not light, is tested.","Color~Sound has no color.","Different amounts of water make the bottles vibrate at different speeds.|That changes the pitch.");
SI("P.4.6C.1","You hit a drum harder. What happens to the sound?","It gets louder.","It gets higher.~Hitting harder changes volume.","It gets softer.~More force makes it louder.","It stops.~It keeps making sound.","A harder hit makes bigger vibrations, which are louder.");
SO("P.4.6C.2","Vibrations and sound","In relation to how sound is perceived by humans, analyze and interpret data from observations and measurements to report how changes in vibration affect the pitch and volume of sound.");
SI("P.4.6C.2","What causes all sounds?","Vibrations","Light~Light doesn’t cause sound.","Heat~Heat isn’t the cause.","Magnets~Magnets don’t make sound by themselves.","Sound is made when something vibrates.");
SI("P.4.6C.2","A string vibrates very fast. What kind of sound does it make?","A high-pitched sound","A low-pitched sound~Slow vibrations make low pitches.","No sound~Vibrating strings make sound.","A silent sound~Fast vibrations make high pitches.","Faster vibrations → higher pitch.");
SI("P.4.6C.2","A sound is so loud it can hurt your ears. What is TRUE about its vibrations?","They are very large.","They are very slow.~Speed sets pitch, not volume.","They are very small.~Small vibrations are quiet.","There are none.~All sounds come from vibrations.","Big vibrations carry more energy and make loud sounds.");
SO("P.4.6C.3","Pioneers of sound","Obtain and communicate information about scientists who pioneered in the science of sound, (e.g., Alexander Graham Bell, Robert Boyle, Daniel Bernoulli, and Guglielmo Marconi).");
SI("P.4.6C.3","Alexander Graham Bell is known for inventing the —","telephone","light bulb~Edison developed the light bulb.","battery~Volta invented the battery.","telescope~Bell worked with sound.","Bell’s telephone changed sound into electrical signals and back.");
SI("P.4.6C.3","Robert Boyle showed that sound can’t travel through a jar with all the air pumped out. What did this prove?","Sound needs matter, like air, to travel.","Sound travels best with no air.~No air means no sound.","Light needs air to travel.~Light can travel without air.","Air makes bells louder only in jars.~It shows sound needs a medium.","With no air to vibrate, the bell couldn’t be heard.");
SI("P.4.6C.3","Guglielmo Marconi is known for sending messages using —","radio waves","telephone wires~He sent messages without wires.","light bulbs~He used radio waves.","drums~He used radio.","Marconi helped invent radio, which sends signals without wires.");
SO("E.4.9A.1","The water cycle","Develop and use models to explain how the sun’s energy drives the water cycle. (e.g., evaporation, condensation, precipitation, transpiration, runoff, and groundwater).","Students will demonstrate an understanding of how the water cycle is propelled by the sun’s energy.");
SI("E.4.9A.1","What provides the energy that drives the water cycle?","The Sun","The Moon~The Moon affects tides.","The wind~Wind moves clouds, but the Sun drives the cycle.","The ocean~The ocean holds water; the Sun heats it.","Sunlight heats water so it evaporates.");
SI("E.4.9A.1","Water vapor cools high in the sky and forms clouds. This is —","condensation","evaporation~Evaporation turns liquid into gas.","precipitation~Precipitation falls from clouds.","runoff~Runoff flows over land.","Cooling vapor turns into tiny water drops: condensation.");
SI("E.4.9A.1","Rain falls on a hill and flows into a stream. What is this water called?","Runoff","Groundwater~Groundwater soaks underground.","Water vapor~Vapor is a gas in the air.","Condensation~That forms clouds.","Water that flows over land into streams is runoff.");
SO("E.4.9B.1","Predicting weather","Analyze and interpret data (e.g., temperature, precipitation, wind speed/direction, relative humidity, or cloud types) to predict changes in weather over time.","Students will demonstrate an understanding of weather and climate patterns.");
SI("E.4.9B.1","The table shows weather data for three days.\nWhat is the BEST prediction for Thursday?","It will probably be cooler.","It will probably get much hotter.~Temperatures are dropping.","It will snow for a week.~The data don’t show that.","The weather will stay the same.~It is changing each day.","The temperature has gone down each day.|The pattern suggests cooler weather.",{h:["Day","High temp (°F)","Sky"],t:[["Monday","84","Sunny"],["Tuesday","78","Cloudy"],["Wednesday","70","Rain"]]});
SI("E.4.9B.1","Dark, tall clouds are building on a hot afternoon. What weather is MOST likely?","A thunderstorm","Clear skies all night~Tall dark clouds bring storms.","Snow~It is a hot afternoon.","Fog~Fog is a low cloud near the ground.","Tall, dark cumulonimbus clouds bring thunderstorms.");
SI("E.4.9B.1","Which tool measures how fast the wind blows?","An anemometer","A thermometer~It measures temperature.","A rain gauge~It measures rainfall.","A barometer~It measures air pressure.","An anemometer spins faster in stronger wind.");
SO("E.4.9B.2","Regional climates","Construct explanations about regional climate differences using maps and long- term data from various regions.");
SI("E.4.9B.2","Why are winters usually warmer in Biloxi than in Chicago?","Biloxi is farther south and near warm water.","Biloxi is closer to the North Pole.~Biloxi is farther south.","Chicago gets more sunlight in winter.~It gets less.","Biloxi has more tall buildings.~Buildings don’t set climate.","Places closer to the equator and near warm water have milder winters.");
SI("E.4.9B.2","What is the difference between weather and climate?","Weather is daily; climate is the long-term pattern.","They mean exactly the same thing.~They are different.","Climate changes every single hour.~Weather changes quickly.","Weather is the average over 30 years.~Climate is the long-term pattern.","Weather is what happens today.|Climate is the average over many years.");
SO("E.4.9B.3","Weather instruments (engineering)","Design weather instruments utilized to measure weather conditions (e.g., barometer, hygrometer, rain gauge, anemometer, or wind vane). Use an engineering design process to define the problem, design, construct, evaluate, and improve the instrument.");
SI("E.4.9B.3","Students build a rain gauge. Which feature is MOST important?","Straight sides with measuring marks","A bright color so it’s easy to see~Color doesn’t affect measurement.","A narrow bottom and wide top~That makes the depth hard to measure fairly.","A lid that stays closed~Rain must get in.","A rain gauge needs to collect rain and show how deep it is.");
SI("E.4.9B.3","A wind vane points in which direction?","Toward where the wind comes from","Always toward the north, like a compass~It moves with the wind.","Toward the Sun all day~It doesn’t follow the Sun.","Straight up into the sky~It turns sideways.","A wind vane shows the direction the wind blows from.");
SI("E.4.9B.3","A hygrometer measures —","humidity","air pressure~A barometer does that.","rainfall~A rain gauge does that.","wind speed~An anemometer does that.","Humidity is the amount of water vapor in the air.");
SO("E.4.9C.1","Natural processes shape Earth","Analyze and interpret data to describe (i.e., NASA, NOAA, USGS) and predict how natural processes (e.g., weathering, erosion, deposition, earthquakes, tsunamis, hurricanes, or storms) affect Earth’s surface.","Students will demonstrate an understanding of how natural processes and human activities affect the features of Earth’s landforms and oceans.");
SI("E.4.9C.1","A river carries sand and drops it where it meets the ocean. This is —","deposition","weathering~Weathering breaks rock apart.","erosion~Erosion carries material away.","evaporation~That is water becoming gas.","When moving water slows, it drops sediment: deposition.");
SI("E.4.9C.1","Wind and rain slowly break a rock into small pieces. This is —","weathering","deposition~Deposition drops material.","condensation~That is part of the water cycle.","an earthquake~That is sudden shaking.","Weathering breaks down rock.|Erosion then carries the pieces away.");
SI("E.4.9C.1","Which natural event changes Earth’s surface the FASTEST?","An earthquake","A river carving a canyon~That takes a very long time.","Wind wearing down a rock~That is slow.","A glacier moving~Glaciers move slowly.","Earthquakes can change land in seconds.");
SO("E.4.9C.2","Shorelines and moving water","Develop and use models of natural processes to explain the effect of the movement of water on the ocean shore zone, including beaches, barrier islands, estuaries, and inlets (e.g., marshes, bays, lagoons, fjords, or sound).");
SI("E.4.9C.2","Ocean waves hit a beach day after day. What happens to the sand over time?","Waves move sand and reshape the beach.","The sand turns into rock right away.~That takes millions of years.","The beach never changes.~Waves constantly move sand.","The sand floats away into space.~Sand stays on Earth.","Waves erode and deposit sand, reshaping beaches.");
SI("E.4.9C.2","Mississippi has barrier islands, like Ship Island, off its coast. How do they help the mainland?","They block some of the force of storm waves.","They make hurricanes stronger and bigger.~They reduce storm impact.","They stop all rain.~They don’t affect rainfall.","They pull the ocean farther away from land.~They don’t move the ocean.","Barrier islands take the first hit from waves and storms.");
SO("E.4.9C.3","Human effects on land and water","Construct scientific arguments from evidence to support claims that human activities, such as conservation efforts or pollution, affect the land, oceans, and atmosphere of Earth.");
SI("E.4.9C.3","Plastic bags thrown on the ground wash into the ocean. How can this harm sea animals?","Animals may eat it or get tangled.","Plastic gives sea animals more food.~Plastic isn’t food.","Plastic cleans the ocean water.~It pollutes the water.","Plastic has no effect on animals.~It can hurt them.","Turtles mistake bags for jellyfish.|Animals can choke or get trapped.");
SI("E.4.9C.3","Which action protects land from erosion?","Planting grass and trees","Cutting down forests~That exposes soil.","Removing plants from hills~Bare soil washes away.","Driving trucks on muddy hills~That loosens soil.","Plant roots hold soil in place.");
SO("E.4.9C.4","Earth’s spheres","Research and explain how systems (i.e., the atmosphere, geosphere, and/or hydrosphere) interact and support life in the biosphere.");
SI("E.4.9C.4","Which is part of the HYDROSPHERE?","The Gulf of Mexico","The air we breathe~That is the atmosphere.","The rocks in a mountain~That is the geosphere.","A deer in the forest~That is the biosphere.","The hydrosphere is all of Earth’s water.");
SI("E.4.9C.4","Rain (hydrosphere) falls on soil (geosphere) and helps a tree (biosphere) grow. What does this show?","Earth’s systems interact.","Earth’s systems never affect each other.~They are connected.","Only the atmosphere matters.~All the systems work together.","Trees are part of the hydrosphere.~Trees are in the biosphere.","Water, land, air, and living things affect one another.");
SO("E.4.9C.5","Severe weather safety","Obtain and communicate information about severe weather phenomena (e.g., thunderstorms, hurricanes, or tornadoes) to explain steps humans can take to reduce the impact of severe weather events.");
SI("E.4.9C.5","A tornado warning is issued for your town. Where is the SAFEST place to go?","An inside room on the lowest floor","Next to a large window to watch~Glass can break.","Outside to watch the storm~Flying objects are dangerous.","Into a car on the highway~Cars can be thrown by tornadoes.","Get low and away from windows, like an interior closet or hallway.");
SI("E.4.9C.5","Which is the BEST way to prepare for hurricane season?","Make a kit with water, food, and flashlights","Wait until the storm arrives to make a plan~Plan ahead.","Open all windows during the storm~That lets wind and rain in.","Ignore weather alerts on the radio~Alerts give time to prepare.","Planning ahead and having supplies keeps families safer.");
SI("E.4.9C.5","During a thunderstorm, why should you stay out of swimming pools?","Lightning can strike the water.","Rain makes the water too cold.~Lightning is the danger.","Pools fill up too fast.~That isn’t the main danger.","Thunder makes waves in the pool.~Lightning is the danger.","Water conducts electricity, so lightning is dangerous near pools.");
SO("E.4.10.1","Energy resources and pollution","Organize simple data sets to compare energy and pollution output of various traditional, non-renewable resources (e.g., coal, crude oil, wood).","Students will demonstrate an understanding of the various sources of energy used for human needs along with their effectiveness and possible impacts.");
SI("E.4.10.1","Which energy source is NONRENEWABLE?","Coal","Sunlight~The Sun keeps shining.","Wind~Wind keeps blowing.","Moving water~Rivers keep flowing.","Coal took millions of years to form and can be used up.");
SI("E.4.10.1","The table shows the smoke made by burning three fuels.\nWhich fuel made the MOST smoke?","Coal","Natural gas~It made the least smoke.","Wood~Wood made less than coal.","They made the same amount~The numbers are different.","Compare the numbers: coal 9, wood 6, natural gas 2.|Coal is the greatest.",{h:["Fuel","Smoke (units)"],t:[["Coal","9"],["Wood","6"],["Natural gas","2"]]});
SO("E.4.10.2","Clean energy","Use technology or informational text to investigate, evaluate, and communicate various forms of clean energy generation.");
SI("E.4.10.2","Which is a CLEAN, renewable way to make electricity?","Solar panels","Burning coal~Coal makes pollution.","Burning gasoline~Gasoline makes pollution.","Burning oil~Oil is nonrenewable.","Solar panels make electricity from sunlight without smoke.");
SI("E.4.10.2","A town has strong, steady winds. Which clean energy would work BEST there?","Wind turbines","Coal plants~Coal isn’t clean.","Oil wells~Oil isn’t clean energy.","Gas generators~Gas burns fuel.","Wind turbines turn moving air into electricity.");
SI("E.4.10.2","What is one reason people choose renewable energy?","It won’t run out and makes less pollution.","It is always free to build.~Building costs money.","It works the same in every weather.~Sun and wind vary.","It must be burned to work.~Most renewables don’t burn fuel.","Renewable sources are replaced naturally and are cleaner.");
SI("E.4.9B.2","Which place would MOST likely have a cold climate all year?","A town high in the mountains near the North Pole","A beach town right near the equator~It is warm all year.","A desert in the southern United States~Deserts there are hot.","A small town on the Gulf of Mexico coast~The Gulf coast is warm.","Being far from the equator and high in the mountains makes a place colder.");
SI("E.4.9C.2","An estuary forms where —","a river meets the ocean","a mountain meets a desert~That isn’t an estuary.","two glaciers meet~Glaciers are ice on land.","a lake dries up~That leaves a dry lake bed.","Estuaries mix fresh river water with salty ocean water.");
SI("E.4.9C.3","A community starts recycling and planting trees along a creek. What is the MOST likely result?","Less trash and less soil washing into the creek","More pollution flowing into the creek~These actions reduce pollution.","The creek dries up~Trees don’t dry up creeks.","More flooding in towns downstream~Trees help slow runoff.","Recycling reduces trash.|Tree roots hold soil and filter runoff.");
SI("E.4.9C.4","Which is part of the GEOSPHERE?","Rocks and soil","Clouds~Clouds are in the atmosphere.","Fish~Fish are in the biosphere.","Ocean water~That is the hydrosphere.","The geosphere is Earth’s solid land: rocks, soil, and the layers beneath.");
SI("E.4.10.1","Why do people still use coal even though it pollutes?","It makes a lot of energy and is available now.","It is renewable, like sunlight.~Coal is nonrenewable.","It makes no pollution.~Burning coal pollutes.","It is made fresh from sunlight each day.~It formed millions of years ago.","Coal produces lots of energy, but it is limited and causes pollution.");
SI("P.4.6A.6","After testing, a solar oven only warms food a little. What should the team do NEXT?","Change one part of the design and test again","Stop, because the design failed the test~Engineers improve designs after testing.","Report that the food got very hot~Report the real results.","Test it again at night instead~It needs sunlight.","The engineering design process repeats: test, improve, and test again.");
SI("P.4.6B.2","Why does a red apple look red to us?","It reflects red light to our eyes.","It makes its own red light inside.~Apples don’t give off light.","It absorbs only red light.~Absorbed light isn’t seen.","Our eyes paint it red when we look.~Our eyes detect reflected light.","We see the color of light an object reflects.");

/* ===== Science Grade 5 (original items) ===== */
SO("L.5.3A.1","How photosynthesis works","Research and communicate the basic process of photosynthesis that is used by plants to convert light energy into chemical energy that can be stored and released to fuel an organism’s activities.","Students will demonstrate an understanding of photosynthesis and the transfer of energy from the sun into chemical energy necessary for plant growth and survival.");
SI("L.5.3A.1","During photosynthesis, a plant changes light energy into which kind of energy?","Chemical energy in sugar","Sound energy in leaves~Plants don’t make sound from light.","Electrical energy in cells~Plants don’t store energy as electricity.","Heat energy only~Some energy is lost as heat, but the plant stores energy in sugar.","Photosynthesis uses light energy.|The plant stores that energy as chemical energy in sugar (food).");
SI("L.5.3A.1","Which list shows what a plant NEEDS to carry out photosynthesis?","Sunlight, water, and carbon dioxide","Sunlight, sugar, and oxygen~Sugar and oxygen are what the plant MAKES.","Soil, oxygen, and heat~Plants take in carbon dioxide, not oxygen, for photosynthesis.","Water, sugar, and soil~Sugar is made during photosynthesis, not used to start it.","Plants take in water through their roots and carbon dioxide through their leaves.|Sunlight gives the energy.|They make sugar and give off oxygen.");
SI("L.5.3A.1","Which gas do plants give off into the air during photosynthesis?","Oxygen","Carbon dioxide~Plants take carbon dioxide IN during photosynthesis.","Nitrogen~Nitrogen is in the air, but photosynthesis doesn’t make it.","Water vapor only~Plants do release water vapor, but the gas made by photosynthesis is oxygen.","Photosynthesis makes sugar and oxygen.|The oxygen goes out into the air through the leaves.");
SI("L.5.3A.1","A rabbit eats clover. Where did the energy stored in the clover first come from?","The sun","The soil~Soil gives minerals and water, not the energy.","The rabbit~The rabbit gets energy FROM the clover.","Rainwater~Water is used in photosynthesis, but the energy comes from sunlight.","The clover made food using sunlight.|The rabbit gets that stored energy when it eats the clover.|So the energy started with the sun.");
SI("L.5.3A.1","Which part of most plants does the MOST photosynthesis?","Leaves","Roots~Roots take in water and are underground, away from light.","Flowers~Flowers help plants reproduce.","Seeds~Seeds store food for a new plant.","Leaves are wide and flat to catch sunlight.|They have chlorophyll, the green substance that captures light.");
SO("L.5.3A.2","Photosynthesis without direct sun","Analyze environments that do not receive direct sunlight and devise explanations as to how photosynthesis occurs, either naturally or artificially.");
SI("L.5.3A.2","Plants on the floor of a rain forest get very little direct sunlight. Which adaptation BEST helps them carry out photosynthesis?","Large, broad leaves that catch more light","Small, needle-shaped leaves that save water~Small leaves catch LESS light.","Roots that grow above the ground~Roots don’t do photosynthesis.","Thick bark on the stem~Bark protects the plant but doesn’t collect light.","Photosynthesis needs light.|A bigger leaf surface catches more of the little light that reaches the forest floor.");
SI("L.5.3A.2","A farm grows lettuce inside a warehouse with no windows. What MOST likely lets the lettuce make its food?","Grow lights that shine on the plants","Fans that keep fresh air moving~Moving air doesn’t give the energy for photosynthesis.","Extra soil in each tray~Soil gives nutrients, not energy.","Keeping the room very cold~Cold slows plant growth.","Plants need light energy for photosynthesis.|Indoors, special lamps called grow lights can supply that light.");
SI("L.5.3A.2","A student puts one plant in a dark closet and one by a sunny window for two weeks. Both get the same water. What will MOST likely happen?","The closet plant will turn pale and weak.","Both plants will grow the same amount.~Light is needed for photosynthesis, so the plants won’t grow the same.","The plant in the closet will grow greener.~Without light, plants lose their green color.","The plant by the window will die from too much light.~Plants by a sunny window usually grow well.","The closet plant has no light, so it can’t make food.|It uses up stored food and becomes pale and weak.");
SI("L.5.3A.2","Seaweed lives in the ocean. Why does MOST seaweed grow in shallow water instead of in the deep ocean?","Sunlight can’t reach the deep ocean.","Deep ocean water is far too salty for it.~The salt level is about the same. Light is the problem.","There is no water pressure in shallow water.~Water pressure isn’t why seaweed grows there.","Fish eat all of the seaweed in deep water.~The main limit is light, not fish.","Seaweed makes food by photosynthesis.|Sunlight only reaches the top part of the ocean, so seaweed grows where light can reach.");
SO("L.5.3B.1","Ecosystems and their organisms","Obtain and evaluate scientific information regarding the characteristics of different ecosystems and the organisms they support (e.g., salt, and fresh water, deserts, grasslands, forests, rain forests, or polar tundra lands).","Students will demonstrate an understanding of a healthy ecosystem with a stable web of life and the roles of living things within a food chain and/or food web, including producers, primary and secondary consumers, and decomposers.");
SI("L.5.3B.1","Which ecosystem has very little rain, hot days, cold nights, and plants like cactuses that store water?","Desert","Rain forest~Rain forests get a LOT of rain.","Tundra~The tundra is cold all year and has no cactuses.","Grassland~Grasslands get more rain than deserts and are covered in grasses.","Very little rain plus water-storing plants describes a desert.");
SI("L.5.3B.1","An ecosystem is cold most of the year. The ground under the surface stays frozen, so trees can’t grow, but mosses and small plants grow in summer. Which ecosystem is this?","Tundra","Desert~Some deserts are cold, but frozen ground and mosses describe the tundra.","Rain forest~Rain forests are warm and full of tall trees.","Grassland~Grasslands aren’t frozen most of the year.","Frozen ground (permafrost), no trees, and short plants describe the tundra.");
SI("L.5.3B.1","The Mississippi Gulf Coast has marshes where river water mixes with salt water from the Gulf. What is this kind of ecosystem called?","An estuary","A desert~A desert is dry land with little rain.","A tundra~A tundra is a cold, treeless land.","A rain forest~A rain forest is a wet, warm forest.","An estuary is where fresh river water meets salt water.|Marshes along the coast are estuaries.");
SI("L.5.3B.1","Which animal is BEST suited to live in a freshwater pond?","A frog","A camel~Camels are suited to deserts.","A polar bear~Polar bears live in icy Arctic areas.","A shark~Most sharks live in salt water.","A frog lives in and near fresh water.|It can swim and lay eggs in the water.");
SI("L.5.3B.1","Why do rain forests have more kinds of living things than deserts?","Rain forests are warm and wet all year.","Rain forests have fewer predators to hunt.~Rain forests have many predators.","Deserts have too much sunlight for animals.~Desert animals are adapted to sunlight.","Rain forests are colder than deserts.~Rain forests are warm.","Water and warmth support lots of plants.|Lots of plants support lots of animals.");
SO("L.5.3B.2","Food chains and energy flow","Develop and use a food chain model to classify organisms as producers, consumers, or decomposers. Trace the energy flow to explain how each group of organisms obtains energy.");
SI("L.5.3B.2","Look at the food chain: grass → grasshopper → frog → snake. Which organism is the producer?","Grass","Grasshopper~A grasshopper eats grass, so it is a consumer.","Frog~A frog eats other animals, so it is a consumer.","Snake~A snake is a consumer at the top of this chain.","A producer makes its own food from sunlight.|Grass is the producer.");
SI("L.5.3B.2","In a food chain, what do the arrows show?","The direction energy moves","Which animal is bigger~Arrows show energy flow, not size.","Which animal is faster~Arrows don’t show speed.","Where each animal lives~Arrows show who eats whom.","An arrow points from the organism being eaten to the organism that eats it.|It shows energy moving through the chain.");
SI("L.5.3B.2","Mushrooms grow on a fallen log and break it down. What role do the mushrooms have?","Decomposer","Producer~Mushrooms can’t make food from sunlight.","Primary consumer~Primary consumers eat living plants.","Predator~Predators hunt other animals.","Decomposers break down dead things.|They return nutrients to the soil.");
SI("L.5.3B.2","Look at the food chain: algae → small fish → heron. The heron is a —","secondary consumer","producer~The algae are the producer.","primary consumer~The small fish eats the producer, so it is the primary consumer.","decomposer~Decomposers break down dead things.","The heron eats the small fish, which ate the producer.|An animal that eats a primary consumer is a secondary consumer.");
SI("L.5.3B.2","In the food chain corn → mouse → owl, which statement about energy is correct?","The owl’s energy first came from the sun.","The owl makes its own energy from sunlight.~Only producers like corn make food from sunlight.","The mouse gives energy to the corn.~Energy flows from the corn to the mouse.","The corn gets its energy from the owl.~Energy moves up the chain, not down.","Corn uses sunlight to make food.|The mouse eats the corn and the owl eats the mouse.|So energy from the sun reaches the owl.");
SO("L.5.3B.3","Food webs and changes in species","Design and interpret models of food webs to justify what effects the removal or the addition of a species (i.e., introduced, or invasive) would have on a specific population and/or the ecosystem as a whole.");
SI("L.5.3B.3","In a meadow, hawks eat rabbits and rabbits eat clover. If most of the hawks leave, what will MOST likely happen first?","More rabbits, and less clover","Fewer rabbits, and more clover~Fewer hawks means fewer rabbits get eaten.","More rabbits, and more clover~More rabbits will eat MORE clover.","No change to rabbits or clover~Removing a predator changes the food web.","Fewer hawks → more rabbits survive.|More rabbits eat more clover, so the clover decreases.");
SI("L.5.3B.3","Kudzu is an invasive vine in Mississippi. It grows very fast and covers trees and other plants. How does kudzu MOST likely harm native plants?","It blocks the sunlight the native plants need.","It gives the native plants extra food to grow.~Kudzu competes with native plants.","It makes the soil much colder.~The main harm is blocking light.","It eats the native plants.~Plants don’t eat other plants.","Kudzu grows over other plants and shades them.|Without sunlight, the plants under it can’t make enough food.");
SI("L.5.3B.3","Snakes and owls both eat mice in a field. If a disease kills most of the mice, which is MOST likely?","Snakes and owls may decrease.","Snakes and owls will increase.~They eat mice, and mice are now fewer.","The grass will disappear.~Fewer mice means MORE grass, not less.","Only the owls will decrease.~Both predators eat mice.","Mice are food for both snakes and owls.|With fewer mice, both predators have less food.");
SI("L.5.3B.3","Which BEST describes an invasive species?","A species brought to a new area that harms native species","A species that has always lived in the same area~That is a native species.","A species with so few members it may disappear~That is an endangered species.","A species that only eats plants~That is an herbivore.","An invasive species comes from somewhere else.|It spreads fast and harms the native living things.");
SO("L.5.3B.4","People in food webs","Communicate scientific or technical information that explains human positions in food webs and our potential impacts on these systems.");
SI("L.5.3B.4","A person eats a salad and a chicken sandwich. In a food web, the person is BEST described as —","a consumer of plants and animals","a producer of its own food~People can’t make their own food from sunlight.","a decomposer of dead matter~Decomposers break down dead things.","a consumer of plants only~The chicken is an animal, so the person eats animals too.","Lettuce is a producer and chicken is a consumer.|A person who eats both is an omnivore, a type of consumer.");
SI("L.5.3B.4","Which human action would MOST likely harm a river food web?","Letting fertilizer wash into the river","Planting trees along the riverbank~Trees help hold soil and keep the water clean.","Fishing only within catch limits~Limits help keep fish populations steady.","Picking up litter near the river~That helps the river.","Fertilizer can cause too much algae growth, which uses up oxygen fish need.|Trash can hurt or trap animals.");
SI("L.5.3B.4","Overfishing removes most of the large fish from a lake. What is MOST likely to happen to the small fish those large fish eat?","Their numbers will increase.","Their numbers will decrease.~Fewer predators means more small fish survive.","They will turn into large fish.~Small fish are a different species.","They will start making their own food.~Fish are consumers.","Large fish eat small fish.|With fewer large fish, more small fish survive and their numbers go up.");
SO("P.5.5A.1","Atoms and molecules","Obtain and evaluate scientific information to describe basic physical properties of atoms and molecules.","Students will demonstrate an understanding of the physical properties of matter.");
SI("P.5.5A.1","What are all objects made of?","Tiny particles called atoms","Drops of water~Many things contain no water.","Living cells~Only living things are made of cells.","Rays of light~Light is energy, not matter.","All matter is made of atoms.|Atoms are too small to see.");
SI("P.5.5A.1","A water molecule is made of two hydrogen atoms and one oxygen atom joined together. What is a molecule?","Two or more atoms joined","One single atom alone~A molecule has two or more atoms.","A kind of cell~Cells are much larger and are found in living things.","A type of energy~A molecule is matter, not energy.","Atoms join together to form molecules.|Water is H₂O: 2 hydrogen + 1 oxygen.");
SI("P.5.5A.1","Why can’t you see the atoms in a piece of paper with your eyes?","Atoms are far too small to see without special tools.","Paper has no atoms.~Everything that is matter is made of atoms.","Atoms are invisible because they are made of light.~Atoms are matter, not light.","Atoms only exist in metals.~All matter has atoms.","Atoms are extremely tiny.|Millions could fit across the width of a hair.");
SO("P.5.5A.2","Solids, liquids, and gases","Collect, analyze, and interpret data from measurements of the physical properties of solids, liquids, and gases (e.g., volume, shape, movement, and spacing of particles).");
SI("P.5.5A.2","Which state of matter has a definite volume but takes the shape of its container?","Liquid","Solid~A solid keeps its own shape.","Gas~A gas has no definite volume: it spreads to fill the container.","Plasma~Liquids are the state that keeps volume but changes shape.","A liquid keeps the same amount (volume).|It flows to take the shape of whatever holds it.");
SI("P.5.5A.2","In which state of matter are the particles farthest apart and moving the fastest?","Gas","Solid~Particles in a solid are packed tightly and vibrate in place.","Liquid~Liquid particles slide past each other but stay close.","All states are the same~The spacing and movement change with the state.","Gas particles spread out and move quickly in all directions.");
SI("P.5.5A.2","A student pours 200 mL of water from a tall glass into a wide bowl. How much water is in the bowl?","200 mL","Less than 200 mL~Pouring doesn’t change the amount of liquid.","More than 200 mL~The volume stays the same.","It can’t be measured~Volume can be measured with a measuring cup.","A liquid keeps its volume.|Only the shape changes.");
SI("P.5.5A.2","A balloon is filled with air. Which BEST describes the air inside?","It spreads out to fill the whole balloon.","It sinks to the bottom of the balloon.~Gas particles spread out evenly.","It has a fixed shape like a block.~Gases have no shape of their own.","It takes up no space.~Air is matter and takes up space.","A gas fills all the space in its container.");
SO("P.5.5A.3","Classifying materials by properties","Analyze matter through observations and measurements to classify materials (e.g., powders, metals, minerals, or liquids) based on their properties (e.g., color, hardness, reflectivity, electrical conductivity, thermal conductivity, response to magnetic forces, solubility, or density).");
SI("P.5.5A.3","A student tests four objects. Which object is MOST likely to be attracted to a magnet?","An iron nail","A plastic spoon~Plastic is not magnetic.","An aluminum can~Aluminum is a metal, but it isn’t attracted to magnets.","A wooden block~Wood is not magnetic.","Magnets attract objects that contain iron, nickel, or cobalt.|An iron nail is attracted.");
SI("P.5.5A.3","Which property describes how easily heat moves through a material?","Thermal conductivity","Solubility~Solubility is how well something dissolves.","Hardness~Hardness is how easily something is scratched.","Magnetism~Magnetism is being attracted to a magnet.","Thermal means heat.|Thermal conductivity tells how well heat moves through a material.");
SI("P.5.5A.3","A student tested four materials in a circuit to see which ones let electricity flow and light a bulb.\nWhich statement is supported by the results?","Copper and aluminum are conductors.","Plastic and rubber are conductors.~They did not light the bulb, so they are insulators.","All four materials are conductors.~Only the metals lit the bulb.","None of the materials are conductors.~Copper and aluminum lit the bulb.","A conductor lets electricity flow and lights the bulb.|Copper and aluminum lit the bulb.",{h:["Material","Did the bulb light?"],t:[["Copper wire","Yes"],["Plastic straw","No"],["Aluminum foil","Yes"],["Rubber band","No"]]});
SI("P.5.5A.3","A student stirs four powders into water. Which observation shows that a powder is soluble?","It disappears into the water.","The powder sinks and stays at the bottom.~If it sinks and stays, it did not dissolve.","The powder floats in a layer on top.~Floating is not dissolving.","The water turns cloudy and grains settle.~Settling grains mean it didn’t fully dissolve.","A soluble substance dissolves.|Its particles spread out evenly, so you can’t see it anymore.");
SO("P.5.5A.4","Density: sink or float","Make and test predictions about how the density of an object affects whether the object sinks or floats when placed in a liquid.");
SI("P.5.5A.4","Water has a density of 1 g/cm³. Which object will float in water?","A block with a density of 0.6 g/cm³","A block with a density of 2.7 g/cm³~It is denser than water, so it sinks.","A block with a density of 7.9 g/cm³~It is much denser than water, so it sinks.","A block with a density of 1.3 g/cm³~It is denser than water, so it sinks.","An object floats if it is less dense than the liquid.|0.6 is less than 1, so that block floats.");
SI("P.5.5A.4","A large log floats in a pond, but a small pebble sinks. Which statement explains this?","The log is less dense than water; the pebble is denser.","The log weighs less than the pebble does.~The log is much heavier. Density, not weight, decides.","Big objects always float, and small ones sink.~A large rock would sink.","Small objects always sink in water.~A small cork would float.","Floating depends on density: mass compared to volume.|Wood is less dense than water; stone is denser.");
SI("P.5.5A.4","A grape sinks in fresh water. A student stirs a lot of salt into the water, and the grape rises. Why?","The salt water is denser than the grape.","The salt made the grape lighter.~The grape didn’t change; the water did.","Salt water has less density than fresh water.~Adding salt makes water DENSER.","The grape absorbed the salt and became hollow.~The grape stays the same.","Adding salt increases the density of the water.|When the water is denser than the grape, the grape floats.");
SI("P.5.5A.4","Four liquids are poured into one jar. Which liquid will end up on the BOTTOM?","Honey, density 1.4 g/cm³","Oil, density 0.9 g/cm³~The least dense liquid floats on top.","Water, density 1.0 g/cm³~Honey is denser than water.","Rubbing alcohol, density 0.8 g/cm³~That is the least dense, so it stays on top.","Denser liquids sink below less dense ones.|Honey has the greatest density, 1.4 g/cm³.");
SO("P.5.5A.5","Designing a vessel (engineering)","Design a vessel that can safely transport a dense substance (e.g., syrup, coins, marbles) through water at various distances and under variable conditions. Use an engineering design process to define the problem, design, construct, evaluate, and improve the vessel.");
SI("P.5.5A.5","A team builds a foil boat to carry pennies. It sinks with 20 pennies. What is the BEST next step in the engineering design process?","Change the design and test it again","Give up because the first design failed~Engineers learn from tests and improve the design.","Use the same boat and add more pennies~It already sank with 20.","Write that the boat held 50 pennies~Record the real results.","Engineers test, find problems, and improve the design.|A wider boat pushes aside more water and can hold more.");
SI("P.5.5A.5","Why does a boat made of a flat sheet of foil float better when it is shaped with high sides?","It pushes aside more water, which pushes up on the boat.","High sides make the foil lighter.~The mass of the foil doesn’t change.","High sides make the water denser.~The water stays the same.","Foil floats better when it is crumpled into a ball.~A ball of foil pushes aside less water and sinks more easily.","A boat floats when the water it pushes aside weighs as much as the boat and its load.|High sides let it push aside more water before water spills in.");
SI("P.5.5A.5","Students must build a boat that carries marbles and costs less than $2 in materials. The $2 limit is an example of a —","constraint","criterion for success~A criterion is what the design must do, like carry 30 marbles.","hypothesis~A hypothesis is a testable prediction.","conclusion~A conclusion comes after testing.","Constraints are limits on a design, like cost, time, or materials.");
SO("P.5.5B.1","Mixtures and solutions","Obtain and evaluate scientific information to describe what happens to the properties of substances in mixtures and solutions (solvent and solute).","Students will demonstrate an understanding of mixtures and solutions.");
SI("P.5.5B.1","When sugar dissolves in water, what is the sugar called?","The solute","The solvent~Water is the solvent: it does the dissolving.","The mixture~The whole thing together is the solution.","The precipitate~Nothing settles out here.","The substance that dissolves is the solute.|The substance it dissolves in is the solvent.");
SI("P.5.5B.1","A student mixes sand and iron filings. What is TRUE about this mixture?","Each part keeps its own properties.","They form a brand-new substance.~Mixing doesn’t make a new substance.","The iron filings stop being magnetic.~The iron keeps its properties.","The sand dissolves in the iron.~Sand doesn’t dissolve in iron.","In a mixture, each part keeps its own properties.|A magnet could pull the iron filings out.");
SI("P.5.5B.1","Which of these is a solution?","Salt water","Trail mix~You can see and pick out each part, so it isn’t a solution.","A salad~The parts stay separate.","Sand and gravel~The parts can be seen and separated by hand.","In a solution, one substance dissolves evenly in another.|Salt dissolves evenly in water.");
SO("P.5.5B.2","Concentration of solutions","Analyze and interpret data to communicate that the concentration of a solution is determined by the relative amount of solute versus solvent in various mixtures.");
SI("P.5.5B.2","Four cups of lemonade were made with different amounts of powder and water.\nWhich cup is MOST concentrated?","Cup C","Cup A~Cup A has the least powder for its water.","Cup B~Cup B has 2 spoons for 200 mL; Cup C has 3 spoons for only 100 mL.","Cup D~Cup D has a lot of water for its powder.","Concentration compares solute to solvent.|Cup C has 3 spoons in only 100 mL: the most powder for the water.",{h:["Cup","Spoons of powder","Water (mL)"],t:[["A","1","200"],["B","2","200"],["C","3","100"],["D","3","300"]]});
SI("P.5.5B.2","A glass of juice tastes too strong. What could you do to make it LESS concentrated?","Add more water","Add more juice concentrate~That makes it MORE concentrated.","Put it in the freezer~Freezing doesn’t change how much solute is in the water.","Pour half of it out~The part left is just as concentrated.","Concentration is the amount of solute compared to solvent.|More water (solvent) means a weaker solution.");
SI("P.5.5B.2","Two students each make salt water. Jada uses 2 spoons of salt in 1 cup of water. Leo uses 2 spoons of salt in 3 cups of water. Which is TRUE?","Jada’s solution is more concentrated.","Leo’s solution is more concentrated.~Leo used more water for the same salt, so his is weaker.","Both solutions are equally concentrated.~They used different amounts of water.","Neither is a solution.~Salt dissolved in water is a solution.","Same solute, less solvent → more concentrated.|Jada used less water.");
SO("P.5.5B.3","What makes things dissolve faster","Investigate how different variables (e.g., temperature change, stirring, particle size, or surface area) affect the rate at which a solute will dissolve.");
SI("P.5.5B.3","Which change will make a sugar cube dissolve FASTEST in water?","Crush the cube into a powder and stir it into warm water","Drop the whole cube into cold water without stirring~That is the slowest way.","Put the cube in ice water~Cold water slows dissolving.","Add a second sugar cube~That adds more solute; it doesn’t speed things up.","Smaller pieces, stirring, and warmer water all speed up dissolving.");
SI("P.5.5B.3","Why does stirring help salt dissolve faster?","It brings fresh water to the salt.","It makes the salt crystals bigger.~Stirring doesn’t make the salt grow.","It cools the water down quickly.~Stirring doesn’t cool the water.","It removes some of the water.~The water stays in the cup.","Stirring moves the particles around.|More water touches the salt, so it dissolves faster.");
SI("P.5.5B.3","Why does powdered drink mix dissolve faster than a solid tablet of the same mix?","The powder has more surface area.","The powder is a different substance.~It is the same substance.","The tablet is lighter.~Both have the same mass.","Powder floats, so it dissolves on top.~Surface area is the reason.","Breaking a solid into small pieces exposes more surface.|More surface touching water means faster dissolving.");
SO("P.5.5B.4","Separating mixtures (engineering)","Design an effective system (e.g., sifting, filtration, evaporation, magnetic attraction, or floatation) for separating various mixtures. Use an engineering design process to define the problem, design, construct, evaluate, and improve the system.");
SI("P.5.5B.4","Which method is BEST for getting the salt back out of salt water?","Evaporation: let the water dry up","Using a magnet~Salt isn’t magnetic.","Pouring it through a coffee filter~Dissolved salt passes right through a filter.","Using a sieve~The salt is dissolved, so a sieve can’t catch it.","When the water evaporates, the salt is left behind in the dish.");
SI("P.5.5B.4","A mixture has sand, iron filings, and small cork pieces. Which plan separates all three?","Magnet for iron, then water: cork floats, sand sinks","Add water, then let all of it evaporate~That won’t separate the solids.","Pour it all through a filter first, then dry it~A filter alone keeps all three solids together.","Shake the mixture in a jar until it settles~Shaking mixes them more.","A magnet removes the iron.|Cork floats on water, and sand sinks.|Each step uses a different property.");
SI("P.5.5B.4","Which mixture can be separated with a filter?","Sand and water","Salt and water~Salt dissolves and passes through the filter.","Sugar and water~Sugar dissolves and passes through the filter.","Food coloring and water~The color dissolves and goes through.","A filter catches solid pieces that did not dissolve.|Sand doesn’t dissolve, so the filter catches it.");
SO("P.5.5C.1","Chemical changes","Analyze and communicate the results of chemical changes that result in the formation of new materials (e.g., decaying, burning, rusting, or cooking).","Students will demonstrate an understanding of the difference between physical and chemical changes.");
SI("P.5.5C.1","Which is an example of a chemical change?","An iron gate rusting","Ice melting~Melting is a physical change: it is still water.","Paper being cut~The paper is still paper.","Sugar dissolving in tea~The sugar is still sugar; it is a physical change.","A chemical change makes a new substance.|Rust is a new substance that forms from iron and oxygen.");
SI("P.5.5C.1","Which observation is a sign that a chemical change happened?","Bubbles of gas form when vinegar hits baking soda.","A rubber band stretches out long.~Stretching only changes shape.","Water freezes into ice cubes overnight.~Freezing is a physical change.","A glass breaks into many pieces.~The glass is still glass.","Signs of a chemical change include a new gas, a color change, light or heat, or a new solid forming.");
SI("P.5.5C.1","When a piece of wood burns, it turns into ash, smoke, and gases. Why is this a chemical change?","New substances form that can’t become wood again.","The wood only changes shape.~Burning makes new substances.","The wood melts into a liquid.~Wood burns; it doesn’t melt.","The wood gets smaller but is still wood.~Ash and smoke are not wood.","Burning makes new substances: ash, smoke, and gases.|You can’t turn them back into the log.");
SI("P.5.5C.1","Bread dough is baked in an oven and becomes bread. Which shows this is a chemical change?","It can’t turn back into dough.","The dough was put in a pan first.~Moving it doesn’t change it.","The dough gets warm.~Warming alone can be a physical change.","The bread can be cut into slices.~Cutting is a physical change.","Cooking makes new substances.|The change can’t be undone.");
SO("P.5.5C.2","Physical changes","Analyze and communicate the results of physical changes to a substance that results in a reversible change (e.g., changes in states of matter with the addition or removal of energy, changes in size or shape, or combining/separating mixtures or solutions).");
SI("P.5.5C.2","Which is a physical change?","Butter melting in a warm pan","An egg frying~Cooking an egg is a chemical change.","A banana rotting~Decay makes new substances.","A match burning~Burning is a chemical change.","Melting changes the state, not the substance.|Melted butter can become solid again when it cools.");
SI("P.5.5C.2","Water in a puddle evaporates on a sunny day. What happened to the water?","It gained heat and became a gas.","It changed into a new substance.~Water vapor is still water.","It lost heat and became a solid.~Gaining heat makes water evaporate.","It soaked up sunlight and disappeared forever.~The water is now in the air as water vapor.","Heat from the sun adds energy.|The liquid water becomes water vapor, a gas.");
SI("P.5.5C.2","A puddle freezes into ice on a cold night. Which statement is correct?","It lost heat; this is a physical change.","It gained heat; this is a physical change.~Freezing happens when energy is removed.","A chemical change made a new substance.~Ice is still water.","The ice can never become water again.~Ice melts back into water.","Removing heat makes a liquid freeze.|It is still water, so it is a physical change.");
SO("P.5.5C.3","Conservation of matter","Analyze and interpret data to support claims that when two substances are mixed, the total weight of matter is conserved.");
SI("P.5.5C.3","A student measures 50 g of water and 10 g of salt, then stirs the salt into the water. What is the mass of the salt water?","60 g","50 g~The salt didn’t disappear; it is still there, dissolved.","40 g~Mass doesn’t go down when things are mixed.","10 g~That is only the salt.","Matter is not lost when substances mix.|50 g + 10 g = 60 g.");
SI("P.5.5C.3","Students mixed two liquids in a sealed bag, and a gas formed. The table shows the results.\nWhat do the data show?","The total mass stayed the same.","Mass was lost because a gas formed.~The bag was sealed, so the gas stayed inside and was weighed.","Mass was gained.~The mass before and after are the same.","The liquids had no mass.~The table shows they had mass.","In a closed bag, nothing can escape.|The mass before and after is the same, so matter is conserved.",{h:["","Mass (g)"],t:[["Bag and liquids before mixing","185"],["Bag after mixing (gas inside)","185"]]});
SI("P.5.5C.3","In an OPEN cup, vinegar and baking soda fizz. Afterward, the cup has less mass. Why?","A gas escaped into the air.","Some matter was destroyed.~Matter can’t be destroyed.","The vinegar turned into nothing.~It changed into new substances.","The scale was broken.~The gas that left explains the change.","The reaction made a gas.|In an open cup, the gas left and wasn’t counted, so the mass seemed to drop.");
SO("P.5.6.1","Gravity","Obtain and communicate information describing gravity's effect on an object.","Students will demonstrate an understanding of the factors that affect the motion of an object through a study of Newton's Laws of Motion.");
SI("P.5.6.1","A student drops a ball. What force pulls the ball down toward the ground?","Gravity","Friction~Friction slows things that rub together.","Magnetism~The ball isn’t magnetic.","Air resistance~Air resistance pushes UP against falling objects.","Gravity pulls objects toward the center of Earth.");
SI("P.5.6.1","An astronaut weighs less on the Moon than on Earth. Why?","The Moon’s gravity is weaker than Earth’s.","The astronaut has less mass on the Moon.~Mass stays the same everywhere.","There is no gravity on the Moon.~The Moon has gravity, just less.","The Moon is closer to the Sun.~Distance from the Sun isn’t the reason.","Weight is the pull of gravity on mass.|The Moon’s gravity is about one-sixth of Earth’s.");
SI("P.5.6.1","Why do the planets keep moving around the Sun instead of flying off into space?","The Sun’s gravity pulls on them.","The planets are tied by magnetic lines.~Gravity, not magnetism, holds them.","Air pushes them around.~There is no air in space.","They are not moving.~Planets orbit the Sun.","The Sun’s gravity pulls each planet toward it.|That pull keeps the planets in orbit.");
SO("P.5.6.2","Predicting motion","Predict the future motion of various objects based on past observation and measurement of position, direction, and speed.");
SI("P.5.6.2","A toy car’s position was recorded every second.\nIf it keeps the same speed, where will it be at 5 seconds?","50 cm","40 cm~That is where it was at 4 seconds.","45 cm~It moves 10 cm each second.","60 cm~That would be at 6 seconds.","The car moves 10 cm every second.|At 5 seconds: 40 + 10 = 50 cm.",{h:["Time (s)","Position (cm)"],t:[["1","10"],["2","20"],["3","30"],["4","40"]]});
SI("P.5.6.2","A bicycle travels 6 meters every second in a straight line. How far will it go in 7 seconds?","42 meters","13 meters~Multiply speed by time; don’t add.","36 meters~That is 6 seconds.","6 meters~That is only 1 second.","Distance = speed × time.|6 × 7 = 42 meters.");
SI("P.5.6.2","A ball rolls across a table, slowing down each second. Which prediction is BEST?","It will keep slowing down and then stop.","It will speed up on its own.~Nothing is pushing it faster.","It will keep the same speed forever.~Friction is slowing it.","It will roll backward.~Nothing pushes it backward.","Friction keeps slowing the ball.|Without another push, it will stop.");
SO("P.5.6.3","Contact and non-contact forces","Develop and use models to explain how the amount or type of force, both contact and non-contact, affects the motion of an object.");
SI("P.5.6.3","Which is a NON-contact force?","A magnet pulling a paper clip from a distance","A hand pushing a heavy door open~The hand touches the door.","A foot kicking a soccer ball across the field~The foot touches the ball.","Friction on a sliding box~Friction needs surfaces to touch.","Non-contact forces act at a distance.|Magnetism and gravity are non-contact forces.");
SI("P.5.6.3","Two students push the same box. One pushes gently and one pushes hard. Which is TRUE?","The harder push makes the box speed up more.","The gentle push makes it move faster.~A bigger force causes a bigger change in motion.","Both pushes do the same thing.~The forces are different.","Pushing harder makes the box heavier.~Force doesn’t change mass.","A greater force on the same mass gives a greater change in speed.");
SI("P.5.6.3","A soccer player kicks a ball to the left. In which direction does the ball move?","To the left","To the right~A push moves an object the way the force acts.","Straight up~The kick is to the left.","It does not move~An unbalanced force makes it move.","An object moves in the direction of the force acting on it.");
SO("P.5.6.4","Balanced and unbalanced forces","Plan and conduct scientific investigations to test the effects of balanced and unbalanced forces on the speed and/or direction of objects in motion.");
SI("P.5.6.4","Two teams pull a rope in a tug-of-war. Each team pulls with 300 newtons. What happens?","The rope stays still; the forces are balanced.","The rope moves toward the stronger team.~Both pull with the same force.","The rope moves faster and faster.~Balanced forces don’t change motion.","The rope breaks.~Nothing in the problem says it breaks.","Equal forces in opposite directions are balanced.|Balanced forces don’t change an object’s motion.");
SI("P.5.6.4","A box is pushed right with 50 N and left with 20 N. What is the net force?","30 N to the right","70 N to the right~Opposite forces subtract.","30 N to the left~The bigger force is to the right.","0 N~The forces are not equal.","Forces in opposite directions subtract.|50 − 20 = 30 N, toward the bigger force: right.");
SI("P.5.6.4","Which situation shows an UNBALANCED force?","A sled speeding up as it slides down a hill","A book resting on a desk~The forces on it are balanced.","A lamp hanging still from the ceiling~It isn’t moving, so the forces are balanced.","A car parked on flat ground~Its motion isn’t changing.","Unbalanced forces change speed or direction.|The sled is speeding up.");
SO("P.5.6.5","Force, mass, friction, and energy","Predict how a change of force, mass, and/or friction affects the motion of an object to convert potential energy into kinetic energy.");
SI("P.5.6.5","A roller coaster car is at the top of a tall hill. Where does it have the MOST potential energy?","At the top of the hill","At the bottom of the hill~At the bottom, most energy has become kinetic energy.","Halfway down~It has less height there.","It is the same everywhere~Potential energy depends on height.","Potential energy is stored energy due to height.|The higher the car, the more it has.");
SI("P.5.6.5","As a sled slides DOWN a hill, what energy change happens?","Potential energy changes into kinetic energy.","Kinetic energy changes into potential energy.~That happens going UP a hill.","Energy is destroyed.~Energy changes form; it isn’t destroyed.","Light energy changes into sound energy.~Height and motion are the energies here.","Going down, height decreases and speed increases.|Stored energy becomes energy of motion.");
SI("P.5.6.5","The same push is given to an empty wagon and to a wagon full of bricks. Which is TRUE?","The empty wagon speeds up more.","The full wagon speeds up more.~More mass means less change in speed for the same push.","Both speed up the same.~Mass makes a difference.","Neither wagon moves.~A push makes them move.","Same force, less mass → faster change in motion.");
SI("P.5.6.5","A toy car rolls down the same ramp onto carpet and onto tile. On which surface will it roll farther, and why?","Tile, because it has less friction than carpet","Carpet, because carpet is softer than tile~Soft, rough surfaces add friction.","Carpet, because it has more friction~More friction slows the car sooner.","They will roll the same distance~Friction is different on each surface.","Friction slows moving objects.|Smooth tile has less friction, so the car goes farther.");
SO("P.5.6.6","Using friction (engineering)","Design a system to increase the effects of friction on the motion of an object (e.g., non-slip surfaces or vehicle braking systems or flaps on aircraft wings). Use an engineering design process to define the problem, design, construct, evaluate, and improve the system.");
SI("P.5.6.6","A school wants to keep students from slipping on a smooth ramp when it rains. Which design increases friction the MOST?","Add rough, gritty strips","Wax the ramp to make it shiny~Wax makes surfaces smoother and more slippery.","Paint the ramp a brighter color~Color doesn’t change friction.","Make the ramp steeper and shorter~That makes slipping more likely.","Rough surfaces create more friction.|Gritty strips help shoes grip.");
SI("P.5.6.6","Why do bicycle brakes slow the wheel?","Pads rub the wheel, creating friction.","They make the bike lighter to stop.~Brakes don’t change mass.","They push the bike forward.~Brakes slow the bike down.","They remove gravity.~Gravity is still there.","Brake pads press against the wheel.|The rubbing creates friction that slows the wheel.");
SI("P.5.6.6","Engineers test three shoe soles on a wet ramp to see which grips best. Which is the MOST important thing to keep the same in every test?","The angle of the ramp","The kind of sole~That is what they are testing, so it changes.","The color of the shoe~Color doesn’t affect grip.","The name of each tester~That doesn’t affect the results.","Only the sole should change.|Keeping the ramp angle the same makes it a fair test.");
SO("E.5.8A.1","The solar system","Develop and use scaled models of Earth’s solar system to demonstrate the size, composition (i.e., rock or gas), location, and order of the planets as they orbit the Sun.","Students will demonstrate an understanding of the locations of objects in the universe.");
SI("E.5.8A.1","Which list shows the four planets CLOSEST to the Sun, in order?","Mercury, Venus, Earth, Mars","Venus, Mercury, Mars, Earth~Mercury is closest, then Venus.","Mars, Earth, Venus, Mercury~That is backward.","Mercury, Venus, Jupiter, Saturn~Earth and Mars come before Jupiter.","Order from the Sun: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.");
SI("E.5.8A.1","Which describes the outer planets: Jupiter, Saturn, Uranus, and Neptune?","They are large and made mostly of gas.","They are small and rocky.~That describes the inner planets.","They are closer to the Sun than Earth.~They are farther from the Sun.","They have no moons.~The outer planets have many moons.","The outer planets are gas giants.|They are huge and far from the Sun.");
SI("E.5.8A.1","Which is the LARGEST planet in our solar system?","Jupiter","Earth~Earth is much smaller than Jupiter.","Mars~Mars is smaller than Earth.","Mercury~Mercury is the smallest planet.","Jupiter is the largest planet.|More than 1,000 Earths could fit inside it.");
SI("E.5.8A.1","In a scale model, the Sun is a basketball. Which object would BEST stand for Earth?","A small bead","A soccer ball~Earth is far smaller than the Sun.","A beach ball~That is bigger than the Sun model.","A bowling ball~Earth is tiny compared to the Sun.","The Sun is about 109 times wider than Earth.|Next to a basketball Sun, Earth would be a tiny bead.");
SO("E.5.8A.2","Why the Sun looks brightest","Use evidence to argue why the sun appears brighter than other stars.");
SI("E.5.8A.2","Why does the Sun look much brighter than other stars?","It is much closer to Earth than any other star.","It is the largest star in the universe.~Many stars are bigger than the Sun.","It is the only star that gives off light.~All stars give off light.","Other stars are turned off during the day.~Other stars are still there; sunlight outshines them.","The Sun is a star, but it is very close to us.|Closer light sources look brighter.");
SI("E.5.8A.2","Two flashlights are equally bright. One is 2 meters away and one is 50 meters away. Which looks brighter, and how does this model the Sun?","The closer one, like the nearby Sun","The farther one, like a distant star~Light looks dimmer the farther it travels.","They look the same, like all stars~Distance changes how bright a light looks.","Neither one, since light fades~Both can be seen.","The same light looks dimmer from farther away.|The Sun looks brightest because it is the closest star.");
SI("E.5.8A.2","Why can’t we see other stars during the day?","Bright sunlight hides the dimmer stars.","Stars move to the other side of the universe.~Stars are still there.","Stars only shine at night.~Stars shine all the time.","Clouds always cover the stars.~Even on clear days we can’t see them.","The stars are still in the sky.|The bright sunlight makes them too hard to see.");
SO("E.5.8A.3","Constellations through the seasons","Describe how constellations appear to move from Earth’s perspective throughout the seasons (e.g., Ursa Major, Ursa Minor, and Orion).");
SI("E.5.8A.3","Orion is easy to see on winter nights but is hard to see in summer. Why?","As Earth orbits, our night sky faces different stars.","Orion’s stars burn out each summer and relight.~The stars are still there.","Orion moves to the other side of Earth.~Earth’s orbit changes our view, not the stars.","Summer nights are too warm for stars.~Temperature doesn’t affect starlight.","As Earth orbits the Sun, the night side faces different directions in space.|So different constellations are visible in different seasons.");
SI("E.5.8A.3","During one night, the stars seem to move slowly across the sky. What causes this?","Earth rotating on its axis","The stars orbiting Earth~Stars don’t orbit Earth.","The Moon pulling on the stars~The Moon doesn’t move stars.","Earth orbiting the Sun~That takes a year, not one night.","Earth spins once every 24 hours.|That spin makes the stars appear to move across the sky.");
SI("E.5.8A.3","What is a constellation?","A group of stars that forms a pattern","A planet with many moons around it~That is a planet, not a constellation.","A cloud of dust in space~That is a nebula.","A star that is very close to Earth~The Sun is our closest star.","People named star patterns, like the Big Dipper in Ursa Major.");
SO("E.5.8A.4","Astronomy and navigation","Construct scientific arguments to support claims about the importance of astronomy in navigation and exploration, including the use of telescopes, compasses, and star charts.");
SI("E.5.8A.4","For hundreds of years, sailors used the North Star to find their way. Why was it useful?","It stays in nearly the same spot all night.","It is the brightest star in the sky.~It is not the brightest star.","It moves across the sky very quickly.~It barely moves at all.","It can be seen only during the day.~It is seen at night.","The North Star sits almost straight above the North Pole.|It stays in place, so it always shows which way is north.");
SI("E.5.8A.4","How did the telescope change astronomy?","It showed faint objects, like Jupiter’s moons.","It made the stars move closer to Earth.~It only makes them look closer.","It let people visit other planets.~Telescopes only help us see.","It replaced the need for maps and compasses.~Maps and charts are still used.","Telescopes gather light and magnify.|Galileo used one to discover moons orbiting Jupiter.");
SI("E.5.8A.4","A hiker has no phone signal. Which tool BEST helps the hiker know which direction is north?","A compass","A thermometer~A thermometer measures temperature.","A telescope~A telescope helps you see far-away objects.","A rain gauge~A rain gauge measures rainfall.","A compass needle lines up with Earth’s magnetic field and points north.");
SO("E.5.8B.1","The Moon’s patterns","Analyze and interpret data from observations and research (e.g., from NASA, NOAA, or the USGS) to explain patterns in the location, movement, and appearance of the moon throughout a month and over the course of a year.","Students will demonstrate an understanding of the principles that govern moon phases, day and night, appearance of objects in the sky, and seasonal changes.");
SI("E.5.8B.1","About how long does it take the Moon to go through all of its phases, from one full moon to the next?","About one month","About one day~One day is one Earth rotation.","About one week~One week is about a quarter of the cycle.","About one year~One year is one trip of Earth around the Sun.","The Moon’s phases repeat about every 29½ days, about a month.");
SI("E.5.8B.1","A student draws the Moon each night for a week. It looks larger and brighter each night. What is happening?","The Moon is waxing.","It is moving closer to Earth.~The Moon’s distance doesn’t change much.","It is making its own light.~The Moon reflects sunlight.","The Moon is waning.~Waning means the lit part gets SMALLER.","Waxing means the visible lit part grows each night.");
SI("E.5.8B.1","Why does the Moon shine in the night sky?","It reflects light from the Sun.","It makes its own light.~The Moon has no light of its own.","It reflects light from Earth’s cities.~City light is far too weak.","It is a star.~The Moon is not a star.","The Moon is like a mirror for sunlight.|We see the part the Sun lights up.");
SO("E.5.8B.2","Earth-Sun-Moon system","Develop and use a model of the Earth-Sun-Moon system to analyze the cyclic patterns of lunar phases, solar and lunar eclipses, and seasons.");
SI("E.5.8B.2","What causes a solar eclipse?","The Moon blocks the Sun from Earth.","Earth passes between the Sun and the Moon.~That causes a LUNAR eclipse.","Clouds cover the Sun.~That is just a cloudy day.","The Sun turns off for a short time.~The Sun keeps shining.","In a solar eclipse, the Moon blocks the Sun from our view.");
SI("E.5.8B.2","During a lunar eclipse, what blocks the sunlight from reaching the Moon?","Earth","The Sun~The Sun is the source of the light.","Mars~Mars isn’t in the way.","Clouds~Clouds don’t reach the Moon.","In a lunar eclipse, Earth is between the Sun and the Moon.|Earth’s shadow falls on the Moon.");
SI("E.5.8B.2","Why do we see different phases of the Moon?","We see different parts of its sunlit half.","Earth’s shadow covers part of the Moon each night.~That only happens during a lunar eclipse.","The Moon changes shape.~The Moon is always round.","Clouds block parts of the Moon.~Phases happen on clear nights too.","Half the Moon is always lit by the Sun.|As the Moon orbits, we see more or less of that lit half.");
SO("E.5.8B.3","Why we have seasons","Develop and use models to explain the factors (e.g., tilt, revolution, and angle of sunlight) that result in Earth’s seasonal changes.");
SI("E.5.8B.3","What is the MAIN cause of Earth’s seasons?","The tilt of Earth’s axis","Earth’s distance from the Sun~Earth is actually closest to the Sun in January.","The Moon’s phases~The Moon doesn’t cause seasons.","Earth spinning on its axis~Spinning causes day and night.","Earth is tilted.|As it orbits, each half gets more direct sunlight for part of the year.");
SI("E.5.8B.3","When it is summer in Mississippi, what is true about the Northern Hemisphere?","It is tilted toward the Sun.","It is tilted away from the Sun.~That causes winter.","It is farther from the Sun than in winter.~Distance isn’t the cause.","It gets fewer hours of daylight.~Summer days are longer.","Tilted toward the Sun → more direct light and longer days → summer.");
SI("E.5.8B.3","When it is summer in the Northern Hemisphere, what season is it in Australia (Southern Hemisphere)?","Winter","Summer~The hemispheres have opposite seasons.","Spring~When one hemisphere has summer, the other has winter.","There are no seasons in Australia~Australia has seasons.","When the north tilts toward the Sun, the south tilts away.|So the seasons are opposite.");
SO("E.5.8B.4","Models of the solar system over time","Obtain information and analyze how our understanding of the solar system has evolved over time (e.g., Earth-centered model of Aristotle and Ptolemy compared to the Sun-centered model of Copernicus and Galileo).");
SI("E.5.8B.4","Which scientist proposed that the planets, including Earth, orbit the Sun?","Copernicus","Ptolemy~Ptolemy taught that everything circled Earth.","Aristotle~Aristotle believed in an Earth-centered universe.","Newton~Newton explained gravity later.","Copernicus proposed a Sun-centered model in the 1500s.");
SI("E.5.8B.4","How did Galileo’s observations support the Sun-centered model?","He saw moons orbiting Jupiter.","He proved that Earth is flat.~People already knew Earth is round.","He saw that the Sun orbits Earth.~His observations supported the opposite.","He discovered gravity.~Newton described gravity.","Galileo used a telescope.|Moons circling Jupiter showed that Earth isn’t the center of everything.");
SI("E.5.8B.4","Why did scientists change from an Earth-centered model to a Sun-centered model?","New evidence fit it better.","A king ordered the change.~Science changes because of evidence.","The Sun moved closer to Earth.~The Sun didn’t move.","The old model was never taught.~It was taught for centuries.","Scientific models change when new evidence is found.");
SO("E.5.10.1","Conserving natural resources","Collect and organize scientific ideas that individuals and communities can use to conserve Earth’s natural resources and systems (e.g., implementing watershed management practices to conserve water resources, utilizing no-till farming to improve soil fertility, reducing emissions to abate air pollution, or recycling to reduce landfill waste).","Students will demonstrate an understanding of the effects of human interaction with Earth and how Earth’s natural resources can be protected and conserved.");
SI("E.5.10.1","A farmer leaves last year’s crop stalks on the field instead of plowing. How does this no-till farming help?","It protects the soil from erosion.","It makes the soil wash away faster.~Covering the soil protects it.","It uses more gasoline for plowing.~No-till uses LESS fuel.","It removes nutrients from the soil.~Old stalks add nutrients as they break down.","Leftover plant material covers and protects the soil.|Less soil washes away, and it stays healthier.");
SI("E.5.10.1","Which action BEST reduces the amount of trash in landfills?","Recycling paper, cans, and plastic","Using more paper plates~That creates more trash.","Burying trash in the backyard~That just moves the trash.","Throwing away old clothes~Donating or reusing clothes is better.","Recycling turns used materials into new products.|Less trash goes to the landfill.");
SI("E.5.10.1","Which is the BEST way for a family to conserve water?","Fix leaky faucets and take shorter showers","Water the lawn every afternoon~That uses more water.","Leave the water running while brushing teeth~That wastes water.","Wash small loads of laundry often~Full loads use water more efficiently.","Stopping leaks and using less water each day conserves water.");
SO("E.5.10.2","Preparing for disasters (engineering)","Design a process for better preparing communities to withstand human-caused or natural disasters (e.g., removing oil from water or soil, systems that reduce the impact of floods, structures that resist hurricane forces). Use an engineering design process to define the problem, design, construct, evaluate, and improve the disaster plan.");
SI("E.5.10.2","A town on the coast is often hit by hurricanes. Which design would BEST reduce damage to homes?","Raised homes with strapped-down roofs","Building homes with flat glass walls~Glass can break in strong winds.","Building homes closer to the beach~That increases flood risk.","Using lighter roofs that are not attached~Wind can blow those away.","Raising homes keeps them above floodwater.|Strong straps hold roofs on in high winds.");
SI("E.5.10.2","Students test materials to soak up an oil spill in a pan of water. Which result shows the BEST material?","It soaked up the most oil.","It sank to the bottom fast.~Sinking doesn’t remove oil from the surface.","It was the most colorful one.~Color doesn’t matter.","It spread the oil around.~That makes the spill worse.","The goal is to remove oil.|The best material soaks up the most oil and leaves the water.");
SI("E.5.10.2","Which is a way communities reduce flood damage along a river?","Building levees and saving wetlands","Paving over wetlands~Pavement makes more water run off.","Cutting down trees near the river~Roots help hold soil and slow water.","Building homes in the floodplain~That puts homes in danger.","Levees hold back high water.|Wetlands act like sponges and slow flooding.");

/* ===== Science Grade 7 (original items) ===== */
SO("L.7.3.1","Water, oxygen, carbon, and nitrogen cycles","Analyze diagrams to provide evidence of the importance of the cycling of water, oxygen, carbon, and nitrogen through ecosystems to organisms.","Students will demonstrate an understanding of the importance that matter cycles between living and non-living parts of the ecosystem to sustain life on Earth.");
SI("L.7.3.1","How do MOST plants get the nitrogen they need?","Absorbing nitrogen compounds from soil","Breathing nitrogen gas from the air~Plants can’t use nitrogen gas directly.","Making nitrogen during photosynthesis~Photosynthesis makes sugar and oxygen.","Eating insects that contain nitrogen~Only a few unusual plants do that.","Bacteria in soil change nitrogen gas into compounds.|Plant roots absorb those compounds.");
SI("L.7.3.1","Which process moves water from plant leaves into the air?","Transpiration","Condensation~Condensation turns vapor into liquid.","Precipitation~Precipitation falls from clouds.","Infiltration~Infiltration is water soaking into soil.","Plants release water vapor through tiny openings in their leaves.");
SI("L.7.3.1","Which process REMOVES carbon dioxide from the air?","Photosynthesis","Burning wood~Burning releases carbon dioxide.","Animal respiration~Respiration releases carbon dioxide.","Decomposition~Decomposers release carbon dioxide.","Plants take in carbon dioxide and store the carbon in sugar.");
SO("L.7.3.2","Photosynthesis and cellular respiration","Analyze and interpret data to explain how the processes of photosynthesis, and cellular respiration (aerobic and anaerobic) work together to meet the needs of plants and animals.");
SI("L.7.3.2","How are photosynthesis and cellular respiration related?","Each one uses what the other makes.","They both happen only in animals.~Plants do both processes.","They both make carbon dioxide.~Photosynthesis uses carbon dioxide.","They both need sunlight to happen.~Respiration happens day and night.","Photosynthesis makes sugar and oxygen.|Respiration uses sugar and oxygen and makes CO₂ and water, which photosynthesis uses.");
SI("L.7.3.2","Which process happens in the cells of BOTH plants and animals?","Cellular respiration","Photosynthesis~Animals can’t do photosynthesis.","Chlorophyll production~Only plants make chlorophyll.","Pollination~Pollination is plant reproduction.","All living cells need energy, so plants and animals both carry out cellular respiration.");
SI("L.7.3.2","Yeast in bread dough makes gas without using oxygen. This is —","anaerobic respiration","aerobic respiration~Aerobic respiration uses oxygen.","photosynthesis~Yeast can’t do photosynthesis.","condensation~Condensation is a change of state.","Anaerobic means without oxygen.|Yeast ferments sugar and releases carbon dioxide.");
SI("L.7.3.2","A sealed jar holds a plant and a snail in sunlight. Why can BOTH survive for a while?","Each uses gases the other gives off.","The snail makes food for the plant.~The plant makes its own food.","The plant doesn’t need any gases.~Plants use carbon dioxide.","The snail does photosynthesis.~Snails are animals.","The plant gives off oxygen the snail uses.|The snail gives off carbon dioxide the plant uses.");
SO("L.7.3.3","How cells use food molecules","Use models to describe how food molecules (carbohydrates, lipids, proteins) are processed through chemical reactions using oxygen (aerobic) to form new molecules.");
SI("L.7.3.3","Which type of food molecule is the body’s main quick source of energy?","Carbohydrates","Proteins~Proteins mostly build and repair the body.","Vitamins~Vitamins help reactions but give little energy.","Minerals~Minerals don’t provide energy.","Carbohydrates like sugars and starches are broken down first for energy.");
SI("L.7.3.3","During aerobic respiration, glucose reacts with oxygen. What are the products?","Carbon dioxide, water, and energy","Oxygen, sugar, and more energy~Those are the reactants of respiration.","Nitrogen, protein, and water~Respiration doesn’t make protein.","Only heat~Respiration makes CO₂, water, and usable energy.","Glucose + oxygen → carbon dioxide + water + energy.");
SI("L.7.3.3","Your body breaks down proteins from food into amino acids. What does it mostly do with them?","Builds new proteins for the body","Stores them as body fat only~Extra calories can be stored, but amino acids mostly build proteins.","Turns them into DNA~Amino acids build proteins, not DNA.","Releases them as oxygen~Amino acids don’t become oxygen.","Amino acids are building blocks.|The body links them into the proteins it needs.");
SO("L.7.3.4","When cycles are disrupted","Explain how disruptions in cycles (e.g., water, oxygen, carbon, and nitrogen) affect biodiversity and ecosystem services (e.g., water, food, and medications) which are needed to sustain human life on Earth.");
SI("L.7.3.4","Large areas of rain forest are cut down and burned. What happens to the carbon cycle?","More carbon dioxide goes into the air.","Less carbon dioxide goes into the air.~Burning and losing trees add CO₂.","The carbon cycle stops completely.~It changes but doesn’t stop.","Oxygen levels rise sharply.~Fewer trees means less oxygen made.","Burning releases stored carbon.|Fewer trees remain to take CO₂ out of the air.");
SI("L.7.3.4","Many medicines come from plants in rain forests. Why does losing biodiversity matter to people?","We lose possible sources of food and medicine.","It makes more new medicines available.~Fewer species means fewer sources.","It has no effect at all on humans.~People depend on ecosystems.","It improves air quality.~Losing forests harms air quality.","Ecosystems provide services like clean water, food, and medicines.|Losing species can mean losing those benefits.");
SI("L.7.3.4","Too much nitrogen fertilizer washes into the Gulf of Mexico. What problem can this cause?","A low-oxygen “dead zone” for fish","A sudden increase in sea turtle eggs~Fertilizer doesn’t help turtles.","Saltier water near the coast~Fertilizer adds nutrients, not salt.","Colder ocean water~Fertilizer doesn’t cool water.","Extra nitrogen causes algae blooms.|When algae decay, oxygen is used up.");
SO("L.7.3.5","Keeping ecosystems healthy (engineering)","Design solutions for sustaining the health of ecosystems to maintain biodiversity and the resources needed by humans for survival (e.g., water purification, nutrient recycling, prevention of soil erosion, and prevention or management of invasive species).");
SI("L.7.3.5","Which solution BEST prevents soil erosion on a hillside farm?","Planting cover crops and building terraces","Removing all of the plants from the hill~Bare soil erodes faster.","Plowing straight down the slope~That helps water carry soil away.","Paving the hillside with concrete~That ends farming there.","Plant roots hold soil.|Terraces slow water running downhill.");
SI("L.7.3.5","Wetlands are called “nature’s water filters.” Why?","Wetland plants and soils trap pollutants.","Wetlands add salt to water.~That isn’t filtering.","Wetlands speed up floodwater.~They slow it down.","Wetlands make water evaporate instantly.~That isn’t how they filter.","Plants and soil in wetlands catch sediment and absorb extra nutrients.");
SI("L.7.3.5","Which plan BEST manages an invasive fish in a lake?","Remove it and stop its spread","Add more of the invasive fish~That makes the problem worse.","Remove the native fish~Native fish need protection.","Do nothing, since it will leave~Invasive species usually spread.","Removing invaders and preventing their spread protects native species.");
SO("P.7.5A.1","Physical properties","Collect and evaluate qualitative data to describe substances using physical properties (state, boiling/melting point, density, heat/electrical conductivity, color, and magnetic properties).","Students will demonstrate an understanding of the physical and chemical properties of matter.");
SI("P.7.5A.1","Which is a PHYSICAL property?","Melting point","Flammability~That is a chemical property.","Ability to rust~That is a chemical property.","Reacting with acid~That is a chemical property.","A physical property can be observed without changing the substance.");
SI("P.7.5A.1","A metal has a density of 2.7 g/cm³ and is not magnetic. Which is it MOST likely?","Aluminum","Iron~Iron is magnetic and denser.","Gold~Gold is far denser.","Lead~Lead is far denser.","Aluminum is light (2.7 g/cm³) and not magnetic.");
SI("P.7.5A.1","Which observation describes a physical property of copper?","It conducts electricity well.","It turns green when it reacts with air.~That is a chemical change.","It reacts with nitric acid.~That is a chemical property.","It forms a new compound when heated with sulfur.~That is a chemical reaction.","Conductivity can be tested without changing copper into something new.");
SO("P.7.5A.2","Chemical properties","Analyze and interpret qualitative data to describe substances using chemical properties (the ability to burn or rust).");
SI("P.7.5A.2","Which is a CHEMICAL property of wood?","It can burn.","It floats on water.~That is about density, a physical property.","It is brown.~Color is a physical property.","It can be cut.~Cutting doesn’t change what it is.","A chemical property describes how a substance can change into new substances.");
SI("P.7.5A.2","An iron nail left outside turns reddish-brown and flaky. Which property of iron does this show?","Its ability to rust","Its high density~Density doesn’t make it flaky.","Its magnetism~Magnetism doesn’t change its color.","Its melting point~It didn’t melt.","Iron reacts with oxygen and water to form rust: a chemical property.");
SI("P.7.5A.2","How can you test a chemical property of a substance?","Try to make it react","Measure its mass on a scale~That is physical.","Look at its color~That is physical.","Find its boiling point~That is physical.","Chemical properties show up only when a substance reacts and changes.");
SO("P.7.5A.3","Comparing physical and chemical properties","Compare and contrast chemical and physical properties (e.g., combustion, oxidation, pH, solubility, reaction with water).");
SI("P.7.5A.3","Which pair lists a physical property and then a chemical property?","Solubility; combustion","Combustion; oxidation~Both are chemical.","Density; color~Both are physical.","Oxidation; boiling point~That order is chemical, then physical.","Solubility is physical.|Combustion (burning) is chemical.");
SI("P.7.5A.3","Sodium metal reacts violently with water. This is an example of a —","chemical property","physical property~A new substance forms.","state of matter~It’s about reacting, not state.","mixture~It forms new substances.","Reacting with water makes new substances, so it is chemical.");
SI("P.7.5A.3","Sugar dissolves in water. Is this a physical or chemical property, and why?","Physical; it is still sugar","Chemical; a new substance forms~No new substance forms.","Chemical; the sugar disappears~It is still there, dissolved.","Physical; the water turns into sugar~The water stays water.","Dissolving can be reversed by evaporating the water.|The sugar is still sugar.");
SO("P.7.5B.1","Temperature, pressure, and particle motion","Make predictions about the effect of temperature and pressure on the relative motion of atoms and molecules (speed, expansion, and condensation) relative to recent breakthroughs in polymer and materials science (e.g., self-healing protective films, silicone computer processors, previous/porous concrete).","Students will demonstrate an understanding about the effects of temperature and pressure on physical state, molecular motion, and molecular interactions.");
SI("P.7.5B.1","When a substance is heated, what happens to its particles?","They move faster and spread out.","They move slower and pack closer.~That happens when it cools.","They stop moving.~Particles move faster when heated.","They get bigger.~The particles themselves don’t grow.","More heat = more kinetic energy.|Particles move faster and usually spread apart.");
SI("P.7.5B.1","Why do bridges have small gaps called expansion joints?","So the bridge can expand in the heat","So rain can drain through the gaps~That isn’t their main purpose.","So the bridge is lighter~Gaps don’t mainly reduce weight.","So cars slow down~That isn’t their purpose.","Materials expand when heated.|Gaps give the bridge room to expand.");
SI("P.7.5B.1","Water vapor touches a cold glass and forms drops. Why?","Cooled vapor condenses into liquid.","The glass makes brand-new water.~The water came from the air.","The vapor particles speed up and spread.~They slow down when cooled.","The glass is leaking.~The water came from the air.","Cooling slows particles.|They come together into a liquid: condensation.");
SO("P.7.5B.2","Gas laws","Use evidence from multiple scientific investigations to communicate the relationships between pressure, volume, density, and temperature of a gas.");
SI("P.7.5B.2","A balloon is taken from a warm room outside into freezing air. What happens to it?","It shrinks because the gas contracts.","It grows because cold gas expands.~Cold gas contracts.","It stays the same size.~Temperature affects gas volume.","It pops right away.~It shrinks; it doesn’t pop.","Cooler gas particles move slower and take up less space.");
SI("P.7.5B.2","You push a syringe plunger in while blocking the tip. What happens to the air inside?","Volume decreases and pressure increases.","Volume increases and pressure increases.~Pushing in decreases volume.","Volume decreases and pressure decreases.~Squeezing raises pressure.","Nothing changes.~Both change.","Same gas in less space → particles hit the walls more often → higher pressure.");
SI("P.7.5B.2","Air in a closed container is heated. The volume can’t change. What happens to the pressure?","It increases.","It decreases.~Hotter particles hit harder and more often.","It stays the same.~Temperature affects pressure.","It drops to zero.~The gas is still there.","Hotter gas particles move faster and hit the walls harder.");
SO("P.7.5B.3","Density, heat, and pressure","Ask questions to explain how density of matter (observable in various objects) is affected by a change in heat and/or pressure.");
SI("P.7.5B.3","Why does a hot-air balloon rise?","The heated air inside is less dense.","Hot air is heavier than cold air.~Hot air is LESS dense.","The balloon has no mass.~The balloon has mass.","Fire pushes the balloon up.~The burner heats the air.","Heating makes air expand.|The same mass in more space means lower density, so it rises.");
SI("P.7.5B.3","Why does ice float on liquid water?","Ice is less dense than liquid water.","Ice is denser than liquid water.~Then it would sink.","Ice has no mass.~Ice has mass.","Air bubbles hold it up.~Even clear ice floats.","Water expands when it freezes.|So ice is less dense and floats.");
SI("P.7.5B.3","A gas is squeezed into a smaller space at the same temperature. What happens to its density?","It increases.","It decreases.~Same mass, less volume → denser.","It stays the same.~Volume changed.","It becomes zero.~The gas is still there.","Density = mass ÷ volume.|Smaller volume with the same mass means greater density.");
SO("P.7.5C.1","Structure of an atom","Develop and use models that explain the structure of an atom.","Students will demonstrate an understanding of the proper use of the periodic table to predict and identify elemental properties and how elements interact.");
SI("P.7.5C.1","Which particles are found in the nucleus of an atom?","Protons and neutrons","Electrons and protons~Electrons are outside the nucleus.","Electrons only~Electrons move around the nucleus.","Neutrons and electrons~Electrons are outside the nucleus.","The nucleus holds protons (+) and neutrons (no charge).");
SI("P.7.5C.1","An atom has 6 protons. What element is it?","Carbon","Oxygen~Oxygen has 8 protons.","Nitrogen~Nitrogen has 7 protons.","Helium~Helium has 2 protons.","The number of protons (atomic number) identifies the element.|6 protons = carbon.");
SI("P.7.5C.1","What is the charge of an electron?","Negative","Positive~Protons are positive.","Neutral~Neutrons are neutral.","It changes every second~The charge doesn’t change.","Electrons are negative.|Protons are positive.|Neutrons have no charge.");
SO("P.7.5C.2","History of the atomic model","Use informational text to sequence the major discoveries leading to the current atomic model.");
SI("P.7.5C.2","Rutherford shot particles at thin gold foil. Most went straight through, but a few bounced back. What did he conclude?","Atoms are mostly empty space.","Atoms are solid all the way through.~Then nothing would pass through.","Electrons are in the nucleus.~He found a tiny positive nucleus.","Gold has no atoms.~Gold is made of atoms.","Most particles passed through empty space.|A few hit a small, dense center: the nucleus.");
SI("P.7.5C.2","Which scientist proposed that electrons travel in specific energy levels around the nucleus?","Niels Bohr","John Dalton~Dalton described atoms as solid spheres.","J.J. Thomson~Thomson discovered the electron.","Isaac Newton~Newton studied motion and gravity.","Bohr’s model placed electrons in fixed energy levels.");
SI("P.7.5C.2","Why has the model of the atom changed many times?","New experiments gave new evidence.","Atoms have changed over time.~Atoms stayed the same; our evidence grew.","Scientists voted on a new model.~Models change from evidence.","The old models were never tested.~They were tested and improved.","Scientific models are revised as new evidence is found.");
SO("P.7.5C.3","Elements, compounds, and mixtures","Collect, organize, and interpret data from investigations to identify and analyze the relationships between the physical and chemical properties of elements, atoms, molecules, compounds, solutions, and mixtures.");
SI("P.7.5C.3","Which is a COMPOUND?","Water (H₂O)","Oxygen gas (O₂)~O₂ contains only one element.","Gold (Au)~Gold is an element.","Salt water~Salt water is a mixture.","A compound has two or more different elements chemically bonded.");
SI("P.7.5C.3","How is a compound different from a mixture?","A compound’s elements are chemically bonded.","A mixture always contains only one element.~Mixtures have two or more substances.","A compound can be separated with a filter.~Compounds need chemical changes to separate.","A mixture has a fixed formula.~Compounds have fixed formulas.","Compounds are bonded in fixed ratios.|Mixtures are physically combined and can be separated physically.");
SI("P.7.5C.3","Sodium is a soft, reactive metal and chlorine is a toxic gas. Together they form table salt. What does this show?","A compound has its own new properties.","Compounds keep the properties of their elements.~Salt is neither metal nor toxic gas.","Table salt is a mixture.~It is a compound.","Elements never combine.~They combined to make salt.","When elements bond, the new compound has its own properties.");
SO("P.7.5C.4","Using the periodic table","Predict the properties and interactions of elements using the periodic table (metals, non-metals, reactivity, and conductors).");
SI("P.7.5C.4","Elements in the same column (group) of the periodic table have —","similar chemical properties","the same number of protons~Each element has its own number.","the same atomic mass~Masses differ.","nothing in common~Groups share properties.","Elements in a group have the same number of outer electrons, so they react in similar ways.");
SI("P.7.5C.4","Where are most METALS found on the periodic table?","On the left side and in the middle","On the far right side of the table~Nonmetals are mostly on the right.","Only in the top row of the table~The top row has hydrogen and helium.","Only in the bottom row~Metals are in many rows.","Most elements are metals, on the left and center of the table.");
SI("P.7.5C.4","Which element would be the BEST conductor of electricity?","Copper (Cu)","Sulfur (S)~Sulfur is a nonmetal.","Neon (Ne)~Neon is a noble gas.","Carbon (C) as charcoal~Charcoal conducts poorly.","Metals like copper are good conductors.");
SO("P.7.5C.5","Chemical formulas","Describe concepts used to construct chemical formulas (e.g., CH4, H2O) to determine the number of atoms in a chemical formula.");
SI("P.7.5C.5","In the formula H₂O, what does the small 2 mean?","There are 2 hydrogen atoms.","There are 2 oxygen atoms.~The 2 follows H.","There are 2 water molecules.~A coefficient in front would show that.","Hydrogen has a charge of 2.~Subscripts count atoms.","A subscript tells how many atoms of the element right before it.");
SO("P.7.5C.6","Ionic and covalent bonds","Using the periodic table, make predictions to explain how bonds (ionic and covalent) form between groups of elements (e.g., oxygen gas, ozone, water, table salt, and methane).");
SI("P.7.5C.6","Table salt (NaCl) forms when sodium gives an electron to chlorine. What kind of bond is this?","Ionic","Covalent~Covalent bonds share electrons.","Metallic~That is between metal atoms.","Hydrogen~That is a weak attraction between molecules.","Transferring electrons makes ions that attract: an ionic bond.");
SI("P.7.5C.6","In a water molecule, oxygen and hydrogen share electrons. This is a —","covalent bond","ionic bond~Ionic bonds transfer electrons.","metallic bond~Water has no metals.","magnetic bond~Bonds are about electrons, not magnets.","Sharing electrons between nonmetals forms covalent bonds.");
SI("P.7.5C.6","Which pair of elements is MOST likely to form an ionic bond?","A metal and a nonmetal","Two nonmetals~They usually share electrons (covalent).","Two noble gases~Noble gases rarely bond.","Two identical nonmetals~They share electrons.","Metals tend to give up electrons; nonmetals tend to gain them.");
SO("P.7.5D.1","Predicting reactions","Analyze evidence from scientific investigations to predict likely outcomes of chemical reactions.","Students will demonstrate an understanding of chemical formulas and common chemical substances to predict the types of reactions and possible outcomes of the reactions.");
SI("P.7.5D.1","Vinegar (an acid) is poured on baking soda (a base). What will MOST likely happen?","Bubbles of carbon dioxide gas form.","The mixture freezes solid.~This reaction doesn’t freeze.","Nothing happens.~Acids and baking soda react.","The baking soda turns into metal.~No metal forms.","Acid + baking soda → carbon dioxide gas, water, and a salt.");
SI("P.7.5D.1","A student places steel wool in a jar of moist air for a week. What will MOST likely happen?","It will rust.","It will melt.~Rust forms at room temperature.","It will dissolve completely.~It changes to rust.","It will turn into gold.~That can’t happen.","Iron + oxygen + water → rust.");
SI("P.7.5D.1","Heating sugar in a pan turns it black and gives off smoke. What does this predict about the result?","A new substance has formed.","It is still pure sugar.~Color and smoke show a change.","It will turn back into white sugar when cooled.~Burnt sugar doesn’t turn back.","Only a physical change happened.~New substances formed.","Color change and smoke are evidence of a chemical reaction.");
SO("P.7.5D.2","Evidence of chemical reactions","Design and conduct scientific investigations to support evidence that chemical reactions (e.g., cooking, combustion, rusting, decomposition, photosynthesis, and cellular respiration) have occurred.");
SI("P.7.5D.2","Which is evidence that a chemical reaction has occurred?","A new gas forms without heating.","Water boils into steam on a stove.~Boiling is physical.","A stick is broken into two pieces.~Breaking is physical.","Ice melts in a cup.~Melting is physical.","Signs of reactions: new gas, new solid (precipitate), color change, light, or temperature change.");
SI("P.7.5D.2","Two clear liquids are mixed, and a cloudy solid forms. What is the solid called?","A precipitate","A solvent~A solvent is a dissolving liquid.","A solute~A solute dissolves.","An element~A precipitate is usually a compound.","A solid that forms from mixing two solutions is a precipitate.");
SI("P.7.5D.2","A glow stick is bent and starts to give off light. What does this show?","A reaction is giving off light energy.","The stick is melting from the inside.~Nothing melts.","Light energy is being stored inside.~It is released.","It is a physical change only.~New substances form.","Giving off light is evidence of a chemical reaction.");
SO("P.7.5D.3","Acids, bases, and neutralization","Collect, organize, and interpret data using various tools (e.g., litmus paper, pH paper, cabbage juice) regarding neutralization of acids and bases using common substances.");
SI("P.7.5D.3","A substance has a pH of 2. It is —","a strong acid","a strong base~Bases have pH above 7.","neutral~Neutral is pH 7.","a weak base~Bases are above 7.","pH below 7 is acidic.|The lower the number, the stronger the acid.");
SI("P.7.5D.3","Which pH is neutral, like pure water?","7","0~That is a very strong acid.","14~That is a very strong base.","10~That is a base.","On the pH scale, 7 is neutral.");
SI("P.7.5D.3","People take an antacid for heartburn caused by stomach acid. How does it work?","It is a base that neutralizes the acid.","It is an acid that adds more acid.~That would make it worse.","It is neutral and does nothing.~It reacts with the acid.","It turns the acid into gas only.~It neutralizes it.","Base + acid → water and a salt, bringing pH closer to 7.");
SO("P.7.5D.4","Energy in chemical reactions","Build a model to explain that chemical reactions can store (formation of bonds) or release energy (breaking of bonds).");
SI("P.7.5D.4","A cold pack gets cold when the chemicals inside mix. What kind of reaction is this?","Endothermic: it absorbs heat.","Exothermic: it releases heat.~Releasing heat makes things warm.","No reaction occurs.~It changes temperature.","Nuclear~This is an ordinary chemical reaction.","Endothermic reactions take in energy, so the pack feels cold.");
SI("P.7.5D.4","Burning wood gives off heat and light. What kind of reaction is this?","Exothermic","Endothermic~Endothermic reactions absorb heat.","A physical change~Burning makes new substances.","Neutralization~That is acid + base.","Exothermic reactions release energy.");
SI("P.7.5D.4","In photosynthesis, plants store energy from sunlight. Where is the energy stored?","In the chemical bonds of sugar","In the soil around the roots~Energy is stored in the plant’s sugar.","In the oxygen the plant gives off~Oxygen isn’t the energy store.","In the leaf’s color~Color doesn’t store energy.","Light energy becomes chemical energy in the bonds of glucose.");
SO("P.7.5E.1","Conservation of mass in closed systems","Conduct simple scientific investigations to show that total mass is not altered during a chemical reaction in a closed system. Compare results of investigations to Antoine-Laurent Lavoisier’s discovery of the law of conservation of mass.","Students will demonstrate an understanding of the law of conservation of mass.");
SI("P.7.5E.1","In a sealed flask, 20 g of reactants react completely. What is the mass of the products?","20 g","Less than 20 g~Nothing could escape the sealed flask.","More than 20 g~Mass isn’t created.","It depends on the color~Color doesn’t change mass.","In a closed system, mass is conserved.");
SI("P.7.5E.1","Which scientist is known for showing that mass is conserved in chemical reactions?","Antoine Lavoisier","Charles Darwin~Darwin studied natural selection.","Gregor Mendel~Mendel studied heredity.","Galileo Galilei~Galileo studied motion and astronomy.","Lavoisier carefully weighed reactions in sealed containers.");
SI("P.7.5E.1","Why must the container be sealed to show conservation of mass?","So no gas can escape or enter","So the reaction is faster~Sealing doesn’t mainly change speed.","So the light stays inside~Light doesn’t affect mass here.","So the reaction stops~It still reacts.","If gas escapes, it isn’t weighed and mass seems to change.");
SO("P.7.5E.2","Mass in open systems","Analyze data from investigations to explain why the total mass of the product in an open system appears to be less than the mass of reactants.");
SI("P.7.5E.2","A candle burns in an open room and gets lighter. Where did the mass go?","Into gases that went into the air","It was destroyed by the flame.~Matter isn’t destroyed.","Into the candle holder~The holder doesn’t gain the mass.","Into light energy only~The mass left as gases.","Burning wax forms carbon dioxide and water vapor, which escape into the air.");
SI("P.7.5E.2","An open beaker of reactants had a mass of 150 g. After the reaction, it was 142 g. What is the BEST explanation?","8 g of gas escaped.","8 g of matter was destroyed.~Matter can’t be destroyed.","The scale got heavier.~The scale isn’t the cause.","The products have no mass.~The products have mass.","150 − 142 = 8 g.|A gas product escaped the open container.");
SI("P.7.5E.2","A student mixes baking soda and vinegar in an open beaker. The mass afterward is lower, because some gas escaped into the air.\nHow could the student show that mass is really conserved?","Repeat it in a sealed container","Use a bigger open beaker~Gas still escapes.","Weigh it before mixing only~Both before and after are needed.","Stir faster~Stirring doesn’t trap gas.","A sealed container keeps the gas in so it gets weighed.");
SO("P.7.5E.3","Balanced equations","Compare and contrast balanced and unbalanced chemical equations to demonstrate the number of atoms does not change in the reaction.");
SI("P.7.5E.3","Which equation is BALANCED?","2H₂ + O₂ → 2H₂O","H₂ + O₂ → H₂O~2 oxygen atoms on the left, but only 1 on the right.","H₂ + O₂ → 2H₂O~4 hydrogen atoms on the right, but only 2 on the left.","2H₂ + 2O₂ → 2H₂O~4 oxygen on the left, 2 on the right.","A balanced equation has the same number of each atom on both sides.|2H₂ + O₂ → 2H₂O: 4 H and 2 O on each side.");
SI("P.7.5E.3","Why must chemical equations be balanced?","Atoms are never created or destroyed.","Reactions always make brand-new atoms.~Atoms are only rearranged.","It makes the equation shorter to write.~Balancing is about atoms.","It changes the products.~It shows the same products correctly.","Balancing shows conservation of mass.");
SO("E.7.9A.1","Weather vs. climate","Analyze and interpret weather patterns from various regions to differentiate between weather and climate.","Students will demonstrate an understanding of how complex changes in the movement and patterns of air and water molecules caused by the sun, winds, landforms, ocean temperatures, and currents in the atmosphere are major determinants of local and global weather patterns.");
SI("E.7.9A.1","Which statement describes CLIMATE, not weather?","Jackson has hot, humid summers most years.","It is raining in Jackson right now.~That is today’s weather.","Tomorrow will be windy in Tupelo.~That is a forecast of weather.","A storm hit Biloxi last night.~That is a weather event.","Weather is day to day.|Climate is the average pattern over many years.");
SI("E.7.9A.1","A city had a cold, snowy week in March. Does this prove its climate is cold?","No; one week is weather, not climate.","Yes; one week sets the climate.~Climate uses decades of data.","Yes; snow always means a cold climate.~Many warm places get rare snow.","No; snow is not weather.~Snow is weather.","Climate is based on long-term averages, usually 30 years or more.");
SO("E.7.9A.2","Air masses and fronts","Analyze evidence to explain the weather conditions that result from the relationship between the movement of water and air masses.");
SI("E.7.9A.2","An air mass forms over the warm Gulf of Mexico. What is it like?","Warm and humid","Cold and dry~That forms over cold land.","Cold and humid~That forms over cold oceans.","Warm and dry~That forms over deserts.","Air takes on the traits of where it forms.|Warm water → warm, moist air.");
SI("E.7.9A.2","A cold front pushes into warm, moist air. What weather often results?","Thunderstorms, then cooler air","Days of light drizzle only~That is more typical of warm fronts.","No change at all~Fronts change the weather.","A long heat wave~Cold fronts bring cooler air.","Cold air pushes warm air up fast.|Rising moist air forms storm clouds.");
SO("E.7.9A.3","Reading weather data","Interpret atmospheric data from satellites, radar, and weather maps to predict weather patterns and conditions.");
SI("E.7.9A.3","On a weather map, a large “L” marks a low-pressure area. What weather usually comes with it?","Clouds and rain","Clear, sunny skies~That is high pressure.","Extreme cold with no clouds~Low pressure usually brings clouds.","No wind at all~Lows often bring wind.","Air rises in a low.|Rising air cools and forms clouds and rain.");
SI("E.7.9A.3","The barometer reading drops quickly over a few hours. What should you predict?","A storm is likely coming.","Clear weather is coming.~Rising pressure brings clear weather.","The temperature will freeze.~Pressure doesn’t directly show that.","Nothing will change.~Falling pressure signals change.","Falling air pressure often means stormy weather is approaching.");
SO("E.7.9A.4","What determines climate","Construct an explanation for how climate is determined in an area using global and surface features (e.g., latitude, elevation, shape of the land, distance from water, global winds, and ocean currents).");
SI("E.7.9A.4","Two cities are at the same latitude. One is on the coast and one is far inland. Which is MOST likely true?","The coastal city has milder temperatures.","The inland city has milder temperatures.~Water helps keep coasts milder.","They have exactly the same climate.~Distance from water changes climate.","The coastal city is always colder.~Water keeps winters milder too.","Large bodies of water heat and cool slowly.|They keep coastal temperatures more even.");
SI("E.7.9A.4","Why is it colder at the top of a tall mountain than at its base?","Air is thinner and cooler at higher elevations.","The top is closer to the Sun, so it’s colder.~Being slightly closer to the Sun doesn’t cool it.","Mountains make their own snow.~Snow is a result, not the cause.","Wind blows heat downhill.~Elevation is the main reason.","Temperature generally drops as elevation increases.");
SI("E.7.9A.4","Why are places near the equator usually warmer than places near the poles?","Sunlight hits the equator more directly.","The equator is much closer to the Sun.~The difference in distance is tiny.","The poles never get any sunlight.~The poles get sunlight part of the year.","The equator has more volcanoes.~Volcanoes don’t set climate.","Direct sunlight concentrates energy on a smaller area.");
SO("E.7.9A.5","Solar energy and convection","Analyze models to explain the cause-and-effect relationship between solar energy and convection and the resulting weather patterns and climate conditions.");
SI("E.7.9A.5","On a sunny day at the beach, the breeze blows from the ocean toward the land. Why?","Warm air rises over land; sea air replaces it.","Air over the ocean is warmer and rises.~Land heats faster during the day.","The ocean pushes the air.~Temperature differences cause the breeze.","Wind always blows toward land.~It reverses at night.","Uneven heating makes convection.|Cool air moves in to replace the rising warm air.");
SI("E.7.9A.5","What MAINLY drives Earth’s winds?","Uneven heating of Earth by the Sun","The pull of the Moon’s gravity~That mainly causes tides.","Earth’s strong magnetic field~It doesn’t move air.","Volcanoes~They are not the main cause.","Uneven heating makes pressure differences.|Air moves from high to low pressure: wind.");
SO("E.7.9A.6","Storms: thunderstorms, hurricanes, tornadoes","Research and use models to explain what type of weather (thunderstorms, hurricanes, and tornadoes) results from the movement and interactions of air masses, high- and low-pressure systems, and frontal boundaries.");
SI("E.7.9A.6","Hurricanes form over —","warm ocean water","cold ocean water~Hurricanes need warm water for energy.","dry desert land~They need moisture.","snowy mountains~They need warm, moist air.","Warm ocean water gives hurricanes heat and moisture.");
SI("E.7.9A.6","Why do hurricanes weaken after they move over land?","They lose their warm-water energy.","Land gives them more energy.~Land cuts off their energy.","They speed up too much over land.~Speed isn’t the main reason.","Trees absorb all of the wind.~Losing warm water is the main reason.","Hurricanes are powered by warm ocean water.|Over land, that energy source is gone.");
SI("E.7.9A.6","Tornadoes MOST often form from —","strong thunderstorms with rotating winds","calm, clear days with high pressure~Tornadoes need storms.","light snow showers in winter~Tornadoes come from severe storms.","fog over a lake~Fog doesn’t form tornadoes.","Severe thunderstorms with rotating updrafts can produce tornadoes.");
SO("E.7.9A.7","Topography and weather","Interpret topographic maps to predict how local and regional geography affect weather patterns and make them difficult to predict.");
SI("E.7.9A.7","Moist air blows up the side of a mountain. Which side MOST likely gets the most rain?","The side facing the wind","The side away from the wind~That side is in a “rain shadow.”","Both sides equally~The windward side gets more.","Neither side~Rising air makes rain.","Air rises, cools, and drops rain on the windward side.");
SI("E.7.9A.7","On a topographic map, contour lines are very close together. What does this show?","A steep slope","Flat land~Flat land has lines far apart.","A lake~Lakes are shown with symbols and colors.","A road~Roads are shown with symbols.","Close contour lines mean the elevation changes quickly: steep land.");
SO("E.7.9B.1","Evaluating climate information","Read and evaluate scientific or technical information assessing the evidence and bias of each source to explain the causes and effects of climate change.","Students will demonstrate an understanding of the relationship between natural phenomena, human activity, and global climate change.");
SI("E.7.9B.1","Which source is MOST reliable for climate data?","A peer-reviewed science journal","An anonymous social media post~No author or evidence.","An ad for an air conditioner~It is trying to sell something.","A friend’s guess~Guesses aren’t data.","Peer-reviewed research is checked by other scientists.");
SI("E.7.9B.1","A website about climate is paid for by a company that sells oil. What should a reader do?","Compare its claims with other sources","Trust it completely~It may be biased.","Ignore all climate information online~Reliable sources exist.","Assume it has no bias at all~Funding can cause bias.","Look for bias and compare with independent, evidence-based sources.");
SO("E.7.9B.2","Carbon dioxide and greenhouse gases","Interpret data about the relationship between the release of carbon dioxide from burning fossil fuels into the atmosphere and the presence of greenhouse gases.");
SI("E.7.9B.2","The table shows carbon dioxide (CO₂) in the air over time.\nWhich statement is supported by the data?","CO₂ in the air has been increasing.","CO₂ in the air has been decreasing.~The numbers go up.","CO₂ stayed the same.~The numbers change.","CO₂ was highest in 1960.~1960 has the lowest value.","Read down the column: 317, 339, 369, 389, 414.|Each value is higher than the one before.",{h:["Year","CO₂ (parts per million)"],t:[["1960","317"],["1980","339"],["2000","369"],["2010","389"],["2020","414"]]});
SI("E.7.9B.2","Which human activity releases the MOST carbon dioxide into the air?","Burning fossil fuels for energy","Planting trees in cities~Trees remove carbon dioxide.","Recycling cans and bottles~Recycling saves energy.","Using solar panels~Solar panels don’t burn fuel.","Coal, oil, and gas release CO₂ when burned.");
SO("E.7.9B.3","Natural and human causes of climate change","Engage in scientific argument based on current evidence to determine whether climate change happens naturally or is being accelerated through the influence of man.");
SI("E.7.9B.3","Earth’s climate has changed naturally in the past. What makes recent warming different?","It is much faster and matches rising CO₂.","It is caused only by the Moon.~The Moon doesn’t drive climate change.","It is happening more slowly than ever.~It is happening faster.","There has been no warming.~Measurements show warming.","Ice cores show past changes were slower.|Recent warming matches the rise in CO₂ from burning fossil fuels.");
SI("E.7.9B.3","Which is a NATURAL factor that can change climate?","Large volcanic eruptions","Burning coal~That is human-caused.","Cutting down forests~That is human-caused.","Driving cars~That is human-caused.","Volcanoes, changes in Earth’s orbit, and the Sun’s output are natural factors.");
SO("E.7.9C.1","Earth’s tilt and sunlight","Construct models and diagrams to illustrate how the tilt of Earth’s axis results in differences in intensity of sunlight on the Earth’s hemispheres throughout the course of one full revolution around the Sun.","Students will demonstrate an understanding that the seasons are the direct result of the Earth’s tilt and the intensity of sunlight on the Earth’s hemispheres.");
SI("E.7.9C.1","Earth’s axis is tilted about how many degrees?","23.5°","0°~Then there would be no seasons.","45°~The tilt is about half that.","90°~That would put a pole facing the Sun.","Earth is tilted about 23.5°.");
SI("E.7.9C.1","In June, the Northern Hemisphere is tilted toward the Sun. Which is TRUE?","Sunlight hits it more directly.","Sunlight hits it at a low angle.~That is winter.","It is farther from the Sun.~Distance isn’t the cause.","It gets fewer daylight hours.~It gets more.","Tilting toward the Sun → more direct, more intense sunlight.");
SO("E.7.9C.2","Sunlight intensity and the seasons","Investigate how variations of sunlight intensity experienced by each hemisphere (to include the equator and poles) create the four seasons.");
SI("E.7.9C.2","A flashlight shines straight down on a table, then at a slant. How does the slanted light compare?","It spreads out, so each spot gets less.","It is brighter in each spot it hits.~The same light is spread out.","It covers less area on the table.~Slanted light covers more area.","It has no light at all.~It still lights the table.","Slanted light spreads out.|This models winter sunlight.");
SI("E.7.9C.2","Why does the equator have small seasonal changes in temperature?","It gets fairly direct sunlight all year.","It is tilted away from the Sun all year.~That isn’t true.","It gets no sunlight in winter.~It gets sunlight all year.","It is the closest place to the Moon.~The Moon doesn’t set seasons.","The Sun stays high over the equator year-round, so temperatures stay warm.");
SI("E.7.9C.2","Near the North Pole in winter, the Sun may not rise for weeks. Why?","The pole is tilted away from the Sun.","The Sun stops shining that far north.~The Sun keeps shining.","The Moon blocks the Sun.~That would be an eclipse.","Clouds cover the pole.~It happens even with clear skies.","Tilted away, the pole stays in darkness through Earth’s daily spin.");
/* counting atoms in formulas: generated */
(SCI_GEN["P.7.5C.5"]=SCI_GEN["P.7.5C.5"]||[]).push((r,o)=>{
 const F=o.pick(r,[["CH₄","methane",{C:1,H:4}],["CO₂","carbon dioxide",{C:1,O:2}],["NH₃","ammonia",{N:1,H:3}],["C₆H₁₂O₆","glucose",{C:6,H:12,O:6}],["H₂SO₄","sulfuric acid",{H:2,S:1,O:4}],["NaHCO₃","baking soda",{Na:1,H:1,C:1,O:3}],["CaCO₃","calcium carbonate (chalk)",{Ca:1,C:1,O:3}],["C₂H₆O","ethanol",{C:2,H:6,O:1}],["H₂O₂","hydrogen peroxide",{H:2,O:2}],["Fe₂O₃","rust (iron oxide)",{Fe:2,O:3}]]);
 const [f,nm,at]=F,tot=Object.values(at).reduce((a,b)=>a+b,0),kind=o.pick(r,["tot","one"]),els=Object.keys(at),e=o.pick(r,els);
 const ans=kind==="tot"?tot:at[e],pool=[...new Set([tot,tot-1,tot+1,els.length,at[e],at[e]+1,Math.max(1,at[e]-1),tot+2])].filter(v=>v!==ans&&v>0);const w=o.shuf(r,pool).slice(0,3);
 return o.fromItem({stem:kind==="tot"?`The formula for ${nm} is ${f}. How many atoms in all are in one molecule?`:`The formula for ${nm} is ${f}. How many ${{C:"carbon",H:"hydrogen",O:"oxygen",N:"nitrogen",S:"sulfur",Na:"sodium",Ca:"calcium",Fe:"iron"}[e]} (${e}) atoms are in one unit?`,right:String(ans),
  w:w.map(v=>[String(v),v===els.length?"That counts the kinds of elements, not the atoms.":"Add the subscripts. An element with no subscript counts as 1."]),steps:`Read each element and its subscript: ${els.map(x=>`${x} = ${at[x]}`).join(", ")}.|${kind==="tot"?`Add them: ${els.map(x=>at[x]).join(" + ")} = ${tot}.`:`So there ${at[e]===1?"is":"are"} ${at[e]} ${e} atom${at[e]===1?"":"s"}.`}`,x:{k:"atoms formula"}},r)});
SI("P.7.5E.3","How many oxygen atoms are on EACH side of the balanced equation CH₄ + 2O₂ → CO₂ + 2H₂O?","4","2~The coefficient 2 in front of O₂ doubles it: 2 × 2 = 4.","3~Count both products: CO₂ has 2 and 2H₂O has 2.","6~Count carefully: 2 in CO₂ and 2 in 2H₂O.","Left: 2O₂ = 4 oxygen atoms.|Right: CO₂ has 2 and 2H₂O has 2, so 4.|The equation is balanced.");
SI("E.7.9A.1","Which data would a scientist use to describe a region’s CLIMATE?","Average rainfall over 30 years","Today’s high temperature~That is one day of weather.","This week’s forecast~That predicts weather.","Last night’s storm report~That is one weather event.","Climate is described with long-term averages.");
SI("E.7.9A.2","Warm, moist air rises over a mass of cold air. What weather is MOST likely?","Clouds and steady rain","Clear, dry skies~Rising moist air makes clouds.","A sudden heat wave~Cold air stays below.","No change in weather~Air masses meeting changes weather.","Rising warm air cools.|Its water vapor condenses into clouds and rain.");
SI("E.7.9A.3","Weather radar shows a band of heavy rain moving east toward your town. What should you predict?","Heavy rain will reach your town soon.","Your town will stay dry for a week.~The rain is moving toward you.","Snow will fall in summer.~Radar shows rain, not snow.","The rain will move west.~It is moving east.","Radar shows where precipitation is and which way it moves.");
SI("E.7.9A.5","At night, land cools faster than the ocean. Which way does the breeze blow at the beach?","From the land toward the sea","From the sea toward the land~That happens during the day.","Straight up~Air moves sideways as wind.","There is never a breeze at night~Land breezes happen at night.","At night, air over the warmer sea rises.|Cooler air from land moves out to replace it.");
SI("E.7.9A.7","A town sits on the side of a mountain away from the wind. What is its weather MOST likely like?","Drier than the other side","Rainier than the other side~The windward side gets more rain.","Always snowy~Elevation and season matter.","The same as the other side~Mountains change rainfall.","Air drops its moisture going up the windward side.|The far side is in a rain shadow.");
SI("E.7.9B.1","A claim says “the climate is not changing” but gives no data or author. How should it be judged?","As unreliable until checked against evidence","As true, because it is posted online~Online posts need evidence.","As proven science~No evidence is given.","As the best source, since it is short~It has no author or data.","Reliable claims give evidence and can be checked.");
SI("E.7.9B.2","Why do greenhouse gases warm Earth?","They trap heat that Earth gives off.","They block all sunlight.~They let sunlight in.","They make the Sun itself hotter.~They don’t affect the Sun.","They cool the oceans.~They warm the planet.","Sunlight warms Earth.|Greenhouse gases absorb heat Earth gives off and keep it in the atmosphere.");
SI("E.7.9B.3","Which evidence BEST supports that humans are speeding up climate change?","Rising CO₂ matches the rise in fossil fuel use.","There were several ice ages long ago.~That shows natural change, not human impact.","The Sun rises every day.~That isn’t climate evidence.","Weather changes from one day to the next.~That is weather, not climate.","The timing of rising CO₂ and temperatures matches human fuel burning.");
SI("E.7.9C.1","Which would happen if Earth’s axis were NOT tilted?","There would be almost no seasons.","Every day would be summer everywhere.~The poles would still be cold.","Days would last a whole year.~Rotation sets day length.","Earth would stop orbiting the Sun.~Tilt doesn’t cause the orbit.","Seasons come from tilt.|With no tilt, sunlight angles wouldn’t change during the year.");

/* ===== Science Grade 8 (original items) ===== */
SO("L.8.2A.1","Genes, chromosomes, and DNA","Use a model to show the relationship of genes, chromosomes, and DNA, and construct explanations comparing their relationship to inherited characteristics.","Students will demonstrate an understanding of how sexual reproduction results in offspring with genetic variation while asexual reproduction results in offspring with identical genetic information.");
SI("L.8.2A.1","Which list goes from LARGEST to SMALLEST?","Chromosome, gene, DNA base","Gene, chromosome, DNA base~A gene is a section of a chromosome, so the chromosome is larger.","DNA base, gene, chromosome~That goes from smallest to largest.","Gene, DNA base, chromosome~The chromosome holds many genes.","A chromosome is a long strand of DNA.|A gene is one section of that DNA.|Each gene is made of many bases.");
SI("L.8.2A.1","What is a gene?","A section of DNA that codes for a trait","A whole cell that carries traits~A cell contains many genes.","A type of protein found in the blood~Genes hold instructions for proteins.","A tiny organ found inside the nucleus~Genes are parts of DNA, not organs.","Genes are segments of DNA on a chromosome.|Each one holds instructions that affect a trait.");
SI("L.8.2A.1","Where is most of the DNA found in a plant or animal cell?","In the nucleus","In the cell wall~The cell wall supports plant cells.","In the cell membrane~The membrane controls what enters and leaves.","In the vacuole~The vacuole stores water and materials.","The nucleus holds the chromosomes, which are made of DNA.");
SI("L.8.2A.1","Why do children often look similar to their parents?","They inherit genes from each parent.","They eat the same foods as their parents.~Diet doesn’t pass on traits like eye color.","They copy their parents’ behavior.~Learned behavior doesn’t change physical traits.","They live in the same home.~Where you live doesn’t pass on traits.","Each parent passes half of their chromosomes to a child.|The genes on them shape inherited traits.");
SO("L.8.2A.2","Mitosis and asexual reproduction","Create a diagram of mitosis and explain its role in asexual reproduction, which results in offspring with identical genetic information.");
SI("L.8.2A.2","A body cell with 46 chromosomes divides by mitosis. How many chromosomes are in EACH new cell?","46","23~Halving happens in meiosis, not mitosis.","92~The chromosomes are copied, then split evenly.","12~Mitosis keeps the full number.","Mitosis makes two cells identical to the parent cell.|Each gets the same 46 chromosomes.");
SI("L.8.2A.2","A bacterium splits into two cells. How does the DNA of the new cells compare to the original?","It is identical.","It is half as much.~Each new cell gets a full copy.","It is a mix of two parents.~There is only one parent.","It is completely new DNA.~The DNA is copied, not made new.","Asexual reproduction copies the DNA.|The offspring are genetically identical to the parent.");
SI("L.8.2A.2","Which is a main purpose of mitosis in humans?","Growth and repair of the body","Making egg and sperm cells~That is meiosis.","Mixing genes from two parents~That happens in sexual reproduction.","Changing a cell’s DNA~Mitosis copies DNA exactly.","Mitosis makes new identical body cells.|That is how we grow and heal cuts.");
SO("L.8.2A.3","Meiosis: crossing over and independent assortment","Construct explanations of how genetic information is transferred during meiosis through crossing over and independent assortment.");
SI("L.8.2A.3","During meiosis, matching chromosomes swap pieces. What is this called?","Crossing over","Mutation~A mutation is a change in the DNA code.","Mitosis~Mitosis doesn’t swap pieces.","Fertilization~Fertilization joins an egg and sperm.","Crossing over trades sections between paired chromosomes.|It makes new combinations of genes.");
SI("L.8.2A.3","Why do brothers and sisters with the same parents look different from each other?","Each sex cell gets a different gene mix.","Each child gets all of one parent’s genes.~Each child gets half from each parent.","Their DNA changes after they are born.~Their inherited DNA stays the same.","Only the first child inherits genes.~Every child inherits genes.","In meiosis, chromosomes sort randomly and cross over.|So every egg and sperm carries a unique mix.");
SI("L.8.2A.3","In meiosis, each pair of chromosomes lines up and separates randomly. This is called —","independent assortment","crossing over~Crossing over is swapping pieces between chromosomes.","asexual reproduction~Meiosis is part of sexual reproduction.","natural selection~That is how populations change over time.","Each chromosome pair separates on its own, without depending on the others.|That random sorting is independent assortment.");
SO("L.8.2A.4","Meiosis and sexual reproduction","Construct a model of meiosis to explain its role in sexual reproduction, which results in offspring that have a new combination of genetic information different from either parent.");
SI("L.8.2A.4","A human sperm cell has how many chromosomes?","23","46~Body cells have 46; sex cells have half.","92~That is double a body cell.","12~Sex cells have exactly half of 46.","Meiosis cuts the chromosome number in half.|46 ÷ 2 = 23.");
SI("L.8.2A.4","Why is it important that meiosis halves the number of chromosomes?","So the baby ends up with 46, not 92","So the baby has twice as many chromosomes~That would cause serious problems.","So the cells can grow larger~Meiosis isn’t about cell size.","So the cells divide faster~Halving keeps the number correct.","23 from the egg + 23 from the sperm = 46.|Without halving, each generation would double.");
SI("L.8.2A.4","How many genetically different cells are made from ONE cell going through meiosis?","Four","Two~Mitosis makes two cells.","One~Meiosis has two divisions.","Eight~Meiosis makes four cells.","Meiosis has two rounds of division.|One cell becomes four sex cells, each different.");
SO("L.8.2A.5","Asexual vs. sexual reproduction","Compare and contrast advantages and disadvantages of asexual and sexual reproduction.");
SI("L.8.2A.5","What is an ADVANTAGE of asexual reproduction?","One parent can make many offspring quickly.","Offspring have lots of genetic variation.~That is an advantage of sexual reproduction.","It needs two parents to reproduce.~Asexual reproduction needs only one.","Offspring resist every disease.~Identical offspring can all catch the same disease.","Asexual reproduction is fast and needs only one parent.");
SI("L.8.2A.5","A disease attacks a field of identical banana plants grown from cuttings. Why might ALL the plants die?","They have the same genes, so none can resist it.","They grew too fast to fight off disease.~Speed of growth isn’t the problem.","They have far too much genetic variety.~They have NO genetic variety.","They were planted in rows.~Planting in rows isn’t the cause.","Cuttings are clones with identical DNA.|If one can’t resist the disease, none can.");
SI("L.8.2A.5","Why does sexual reproduction help a species survive when the environment changes?","Offspring vary, so some may survive the change.","Offspring are identical to their parents.~Identical offspring would all respond the same.","It always makes more offspring.~It usually makes fewer offspring.","It needs only one parent.~It needs two parents.","Variation means some individuals may have traits suited to the new conditions.");
SO("L.8.2B.1","Genes and environment","Construct an argument based on evidence for how environmental and genetic factors influence the growth of organisms.","Students will demonstrate an understanding of the differences in inherited and acquired characteristics and how environmental factors (natural selection) and the use of technologies (selective breeding, genetic engineering) influence the transfer of genetic information.");
SI("L.8.2B.1","Two identical twins are raised apart. One eats a much healthier diet and grows taller. What does this show?","Environment affects how genes show up.","Their genes became different over time.~Identical twins keep the same DNA.","Height is not affected by genes at all.~Genes set a range for height.","Diet changes the DNA in a person’s cells.~Diet doesn’t change DNA.","Genes set the possible range.|Environment, like nutrition, affects where in that range a person grows.");
SI("L.8.2B.1","Which is an ACQUIRED trait, not an inherited one?","A scar from a bike accident","Natural hair color~That is inherited.","Blood type~That is inherited.","Attached earlobes~That is inherited.","Acquired traits come from experiences, not genes.|A scar can’t be passed to children.");
SI("L.8.2B.1","Hydrangea flowers can be blue or pink depending on the soil. What does this show?","An environmental factor affects a trait.","The flowers have no genes for color.~Genes control the ability to make color.","The soil changes the plant’s DNA.~The soil changes how the color shows, not the DNA.","All hydrangeas are identical.~They show different colors.","Soil acidity changes the flower color.|The environment affects how a trait appears.");
SO("L.8.2B.2","Mendel and heredity","Use various scientific resources to research and support the historical findings of Gregor Mendel to explain the basic principles of heredity.");
SI("L.8.2B.2","Mendel crossed purebred tall pea plants with purebred short ones. All the offspring were tall. What did this show?","Tall was dominant over short.","Short was dominant over tall.~Short didn’t show up at all.","The traits blended together.~Blending would give medium plants.","The short gene was destroyed.~It reappeared in the next generation.","A dominant trait hides a recessive trait.|Tall showed in every offspring, so tall is dominant.");
SI("L.8.2B.2","Why did Mendel use pea plants for his experiments?","They grow fast with clear traits.","They have no genes to study.~All living things have genes.","They only reproduce asexually.~Pea plants reproduce sexually.","They never vary.~They have clear variations, like tall and short.","Pea plants grow quickly, make many offspring, and have traits with two clear forms.");
SI("L.8.2B.2","In Mendel’s second generation, short plants appeared again from tall parents. What explains this?","The tall parents carried a hidden short allele.","The short trait was a brand-new mutation.~It came from the parents’ hidden alleles.","The plants were not watered.~Water doesn’t create a new trait.","Tall plants always make some short plants.~Purebred tall plants don’t.","Each tall parent carried one short (recessive) allele.|Offspring that got two recessive alleles were short.");
SO("L.8.2B.3","Punnett squares","Use mathematical and computational thinking to analyze data and make predictions about the outcome of specific genetic crosses (monohybrid Punnett Squares) involving simple dominant/recessive traits.");
SI("L.8.2B.3","An organism has the genotype Tt. What does this mean?","It has one dominant and one recessive allele.","It has two dominant alleles for the trait.~That would be TT.","It has two recessive alleles for the trait.~That would be tt.","It has no alleles for this trait.~Tt shows two alleles.","Capital letter = dominant allele.|Lowercase = recessive allele.|Tt is heterozygous.");
SI("L.8.2B.3","Brown fur (B) is dominant over white fur (b). A bb mouse has what color fur?","White","Brown~Brown needs at least one B.","Half brown and half white~Simple dominance doesn’t blend.","Gray~Simple dominance doesn’t blend.","bb has no dominant allele.|So the recessive trait, white, shows.");
SO("L.8.2B.4","Selective breeding and genetic engineering","Debate the ethics of artificial selection (selective breeding, genetic engineering) and the societal impacts of humans changing the inheritance of desired traits in organisms.");
SI("L.8.2B.4","Farmers breed only the cows that make the most milk. Over many generations, the herd makes more milk. This is an example of —","selective breeding","natural selection~Here, people choose which animals breed.","asexual reproduction~Cows reproduce sexually.","mutation~The traits were chosen, not caused by DNA errors.","When people choose parents with desired traits, it is selective breeding (artificial selection).");
SI("L.8.2B.4","Scientists put a gene into corn that helps it resist insects. What is this called?","Genetic engineering","Selective breeding~Selective breeding chooses parents; it doesn’t insert genes.","Natural selection~Nature didn’t choose this trait.","Cloning~Cloning copies a whole organism.","Genetic engineering changes an organism’s DNA directly, often by adding a gene.");
SI("L.8.2B.4","What is one possible DISADVANTAGE of breeding crops that are all genetically very similar?","One disease could wipe out the whole crop.","The crops will grow too much food.~That isn’t a disadvantage.","The crops will have more variety.~They have LESS variety.","The crops can no longer be planted.~They can still be planted.","Low genetic variety means the plants share the same weaknesses.");
SO("L.8.2C.1","Genes, proteins, and traits","Communicate through diagrams that chromosomes contain many distinct genes and that each gene holds the instructions for the production of specific proteins, which in turn affects the traits of the individual (not to include transcription or translation).","Students will demonstrate an understanding that chromosomes contain many distinct genes and that each gene holds the instructions for the production of a specific protein, which in turn affects the traits of an individual.");
SI("L.8.2C.1","How does a gene affect a trait such as eye color?","It codes for a protein that makes the color.","It is the eye color itself.~The gene is DNA; the color comes from proteins it codes for.","It changes the eye’s shape each year.~Genes don’t change yearly.","It stores light in the eye.~Genes hold instructions; they don’t store light.","Gene → protein → trait.|The protein made from the gene helps produce the pigment.");
SI("L.8.2C.1","A single chromosome contains —","many different genes","only one gene~Each chromosome carries hundreds to thousands of genes.","no DNA~Chromosomes are made of DNA.","a whole organism~A chromosome is a small part of a cell.","A chromosome is a long DNA molecule with many genes along it.");
SI("L.8.2C.1","What is the job of most proteins made from genes?","To build and run the body’s cells","To store the body’s DNA safely~DNA stores instructions; proteins do the work.","To make new chromosomes for cells~Proteins don’t make chromosomes.","To decide the weather~Proteins work inside living things.","Proteins build structures and carry out jobs in cells.|That is how genes shape traits.");
SO("L.8.2C.2","Mutations","Construct scientific arguments from evidence to support claims about the potentially harmful, beneficial, or neutral effects of genetic mutations on organisms.");
SI("L.8.2C.2","A mutation in some bacteria lets them survive an antibiotic. For the bacteria, this mutation is —","beneficial","harmful~It helps the bacteria survive.","neutral~It changes whether they survive.","impossible~Mutations like this really happen.","A mutation that helps an organism survive in its environment is beneficial to it.");
SI("L.8.2C.2","What is a mutation?","A change in an organism’s DNA","A trait learned during life~Learned traits aren’t mutations.","A new organ that grows in one day~Mutations change DNA, not whole organs overnight.","A type of cell division~Mitosis and meiosis are cell division.","A mutation is any change in the DNA sequence.");
SI("L.8.2C.2","A mutation changes one DNA base but the protein made is exactly the same. This mutation is MOST likely —","neutral","harmful~The protein didn’t change.","beneficial~Nothing about the organism changed.","inherited only by plants~Mutations happen in all living things.","If the protein and trait don’t change, the mutation has no effect: it is neutral.");
SO("L.8.4A.1","Darwin and natural selection","Use various scientific resources to analyze the historical findings of Charles Darwin to explain basic principles of natural selection.","Students will demonstrate an understanding of the process of natural selection, in which variations in a population increase some individuals’ likelihood of surviving and reproducing in a changing environment.");
SI("L.8.4A.1","Darwin saw that finches on different Galápagos islands had different beak shapes. What did he conclude?","Beaks were suited to the food on each island.","The finches changed beaks on purpose.~Individuals can’t choose their traits.","All the finches were the same species with the same beaks.~The beaks were different.","Beak shape has no effect on survival.~Beak shape affects what food a bird can eat.","Birds whose beaks fit the local food survived and reproduced.|Over time, beaks became suited to each island.");
SI("L.8.4A.1","Which statement is a key idea of natural selection?","Individuals with helpful traits survive and reproduce more.","Organisms change their traits because they need to.~Traits come from genes, not need.","All offspring survive to adulthood.~Many offspring don’t survive.","Every individual in a population is identical.~Populations have variation.","Variation + competition → organisms with helpful traits leave more offspring.");
SI("L.8.4A.1","Which book did Charles Darwin publish to explain natural selection?","On the Origin of Species","The Principles of Heredity~Mendel studied heredity, but this wasn’t Darwin’s book.","The Theory of Gravity~Gravity was explained by Newton.","The Structure of the Atom~That is a chemistry topic.","Darwin published On the Origin of Species in 1859.");
SO("L.8.4A.2","Survival and reproduction","Construct explanations about how genetic factors and environmental factors (e.g., food intake, interactions with other organisms, etc.) lead to the growth, survival, and reproduction of organisms in natural selection.");
SI("L.8.4A.2","In a forest with dark tree bark, which moths are MOST likely to survive bird attacks?","Dark-colored moths","Light-colored moths~They stand out on dark bark.","Moths of every color equally~Color affects how easily birds spot them.","The largest moths~Size isn’t the trait helping them hide here.","Dark moths blend in on dark bark.|Birds catch fewer of them, so more survive to reproduce.");
SI("L.8.4A.2","A drought kills many plants with shallow roots. Plants with deep roots survive. What will MOST likely happen over many generations?","More of the population will have deep roots.","All plants will grow shallow roots.~Shallow-rooted plants died.","The plants will decide to grow deeper roots.~Plants can’t choose traits.","The population will stay the same.~The drought changed who survives.","Deep-rooted plants survive and reproduce.|Their offspring inherit deep roots, so the trait becomes more common.");
SI("L.8.4A.2","Which is an environmental factor that affects which organisms survive?","The amount of food available","The color of its own DNA~DNA isn’t an environmental factor.","The organism’s genes~Genes are genetic, not environmental.","The number of chromosomes~That is genetic.","Environmental factors come from the surroundings: food, predators, climate, disease.");
SO("L.8.4B.1","Traits changing over time","Analyze and interpret data (e.g., pictures, graphs) to explain how natural selection may lead to increases and decreases in specific traits in populations over time.","Students will demonstrate an understanding of how similarities and differences among living and extinct species provide evidence that changes have occurred in organisms over time and that similarity of characteristics provides evidence of common ancestry.");
SI("L.8.4B.1","The table shows the percent of dark moths in a city over time as factories made the trees darker with soot.\nWhat BEST explains the data?","Dark moths were harder for birds to see.","The light moths changed color on purpose.~Moths can’t choose their color.","Soot made the moths’ DNA darker.~Soot doesn’t change DNA.","Birds preferred to eat dark moths.~Then dark moths would decrease.","On darker trees, dark moths were harder for birds to see.|They survived and passed on the dark trait.",{h:["Year","Dark moths (%)"],t:[["1850","2"],["1875","30"],["1900","75"],["1925","90"]]});
SI("L.8.4B.1","When an antibiotic is used again and again, the number of resistant bacteria goes up. Why?","Resistant bacteria survive and multiply.","The antibiotic creates resistance in all bacteria.~It kills the ones that aren’t resistant.","Bacteria learn to resist.~Bacteria don’t learn; resistance is in their genes.","Resistant bacteria die first.~They survive the antibiotic.","Bacteria that happen to be resistant survive.|They reproduce, so the resistant trait spreads.");
SI("L.8.4B.1","A population of rabbits lives where snow covers the ground most of the year. Over time, which trait would likely INCREASE?","White fur","Brown fur~Brown stands out against snow.","Black fur~Black stands out against snow.","Spotted fur~Spots would be easier for predators to see.","White fur hides rabbits from predators in snow.|White rabbits survive and reproduce more.");
SO("L.8.4B.2","Variation and survival","Construct written and verbal explanations to describe how genetic variations of traits in a population increase some organisms’ probability of surviving and reproducing in a specific environment.");
SI("L.8.4B.2","Why is genetic variation in a population important?","Some may have traits that help in new conditions.","It makes every individual in it the same.~Variation means differences.","It prevents all mutations.~Mutations cause variation.","It stops natural selection.~Natural selection acts on variation.","With variation, some organisms are likely to survive a change.|They keep the population going.");
SI("L.8.4B.2","Giraffes with longer necks can reach more leaves during dry seasons. Which is TRUE?","Long-necked giraffes survive more often.","Short-necked giraffes stretch their necks longer.~Stretching doesn’t change genes.","All giraffes have the same neck length.~There is variation in neck length.","Neck length has nothing to do with food.~It affects reaching leaves.","Longer necks reach more food when food is scarce.|Those giraffes are more likely to pass on the trait.");
SI("L.8.4B.2","Which trait would MOST help a desert plant survive?","A waxy coating on its leaves","Large, thin leaves for shade~They lose more water.","Very shallow roots only~Deep or wide roots help collect scarce water.","Needing lots of rain~Deserts get little rain.","In a dry place, saving water is key.|A waxy coating keeps water in.");
SO("L.8.4B.3","Speciation","Obtain and evaluate scientific information to explain that separated populations, which remain separated, can evolve through mutations to become a new species (speciation).");
SI("L.8.4B.3","A river changes course and splits a squirrel population in two. After many generations, the two groups can no longer interbreed. What happened?","Speciation: a new species formed.","Extinction: both groups died out.~Both groups survived.","Mutation stopped happening.~Mutations kept happening in both groups.","They became one larger population.~They were separated.","Separated groups collect different mutations and adapt differently.|When they can’t interbreed, they are separate species.");
SI("L.8.4B.3","Why are separated populations more likely to become different species?","They can’t share genes with each other.","They live in the same environment.~Separated groups often face different environments.","They interbreed more often.~Separated groups can’t interbreed.","They stop having mutations.~Mutations still happen.","No gene flow between groups.|Different mutations and selection pressures build up over time.");
SI("L.8.4B.3","Two populations of frogs look alike but sing different mating calls and no longer mate with each other. This shows they —","may now be separate species","are the exact same population~They no longer interbreed.","have identical DNA~Their differences show different DNA.","are going extinct~Not mating with each other doesn’t mean extinction.","If groups no longer interbreed, they are on the way to being, or already are, different species.");
SO("L.8.4B.4","Evidence of common ancestry","Analyze displays of pictorial data to compare and contrast embryological and homologous/analogous structures across multiple species to identify evolutionary relationships.");
SI("L.8.4B.4","A human arm, a whale flipper, and a bat wing have the same bones arranged in the same way. These are —","homologous structures","analogous structures~Analogous structures do the same job but have different origins.","vestigial structures~Vestigial structures have little or no use.","identical organs~They have different shapes and jobs.","Same bone pattern, different jobs → homologous structures.|They suggest a common ancestor.");
SI("L.8.4B.4","A butterfly wing and a bird wing both help with flying but are built very differently. These are —","analogous structures","homologous structures~Homologous structures share the same basic parts.","vestigial structures~Both wings are used.","identical structures~They are built differently.","Same job, different structure and origin → analogous.");
SI("L.8.4B.4","Early embryos of fish, chickens, and humans look very similar. What does this suggest?","They share a common ancestor.","They will grow into the same animal.~They grow into very different animals.","They live in the same environment.~They live in different places.","They have no genes in common.~Similar embryos suggest shared genes.","Similar early development is evidence of shared ancestry.");
SO("P.8.6.1","Sound and light waves","Interpret the characteristics and behaviors of sound and light waves to determine the relationship between matter and energy; determine the medium for transmission for each wave","Students will demonstrate an understanding of the properties, behaviors, and application of waves.");
SI("P.8.6.1","Astronauts on the Moon must use radios to talk. Why can’t they just shout?","Sound needs matter, and space has none.","Sound travels too fast to hear in space.~Sound can’t travel in space at all.","Their voices freeze in the cold.~Sound doesn’t freeze.","Light blocks all sound in space.~Light doesn’t block sound.","Sound waves are vibrations of matter.|With no air, there is nothing to carry the sound.|Radio uses light-type waves that can cross space.");
SI("P.8.6.1","Which wave can travel through empty space?","Light","Sound~Sound needs a medium.","An ocean wave~Ocean waves need water.","A wave in a rope~That wave needs the rope.","Light is an electromagnetic wave.|It doesn’t need matter, so it can cross space.");
SI("P.8.6.1","During a storm, you see lightning before you hear thunder. Why?","Light travels much faster than sound.","Sound travels faster than light.~Light is far faster.","Thunder happens later than lightning.~They happen at the same time.","Your ears work slower than your eyes.~The delay is in the waves’ speeds.","Light reaches you almost instantly.|Sound travels about 340 m each second, so it arrives later.");
SI("P.8.6.1","What does a wave carry from one place to another?","Energy","Matter~The medium moves back and forth but stays in place.","Water only~Many waves aren’t in water.","Air only~Light waves don’t need air.","Waves transfer energy.|The particles of the medium vibrate but don’t travel with the wave.");
SO("P.8.6.2","Wave energy to electricity","Investigate research-based mechanisms for capturing and converting wave energy (frequency, amplitude, wavelength, and speed) into electrical energy.");
SI("P.8.6.2","Which ocean waves carry the MOST energy to a wave-power device?","Waves with the largest amplitude","Waves with the smallest amplitude~Small waves carry less energy.","Waves that are completely still~Still water has no wave energy.","Waves of any size, equally~Amplitude affects energy.","Taller waves (larger amplitude) carry more energy.");
SI("P.8.6.2","Solar panels change light energy into —","electrical energy","sound energy~Solar panels don’t make sound.","chemical energy in food~That is what plants do.","nuclear energy~Panels don’t make nuclear energy.","Solar cells turn the energy of light waves into electricity.");
SI("P.8.6.2","The distance from one wave crest to the next crest is the —","wavelength","amplitude~Amplitude is the height of the wave.","frequency~Frequency is how many waves pass per second.","speed~Speed is how fast the wave moves.","Wavelength is crest-to-crest (or trough-to-trough) distance.");
SO("P.8.6.3","Reflection, refraction, and absorption","Conduct simple investigations about the performance of waves to describe their behavior (e.g., refraction, reflection, transmission, and absorption) as they interact with various materials (e.g., lenses, mirrors, and prisms).");
SI("P.8.6.3","A pencil in a glass of water looks bent at the surface. What causes this?","Refraction: light bends as it slows down","Reflection: light bounces off the water.~Reflection doesn’t make it look bent.","Absorption: the water soaks up light~Absorption makes things darker, not bent.","The pencil really bends in water.~The pencil is still straight.","Light slows down in water.|The change in speed bends the light, so the pencil looks bent.");
SI("P.8.6.3","Which material is BEST for reflecting light?","A smooth mirror","Clear glass~Clear glass mostly lets light pass through.","Black cloth~Black cloth absorbs most light.","A rough rock~Rough surfaces scatter light.","Smooth, shiny surfaces reflect light well.");
SI("P.8.6.3","White light passes through a prism and makes a rainbow. Why?","Each color bends a different amount.","The prism adds color to the light.~White light already contains all colors.","The prism reflects only red light.~We see every color.","Light stops inside the prism.~Light comes out the other side.","White light is a mix of colors.|Each color refracts by a different amount and spreads out.");
SO("P.8.6.4","Sound: amplitude and frequency","Use scientific processes to plan and conduct controlled investigations to conclude sound is a wave phenomenon that is characterized by amplitude and frequency.");
SI("P.8.6.4","A student plucks a guitar string harder without changing anything else. What changes?","The sound gets louder.","The pitch gets higher.~Pitch depends on frequency.","The sound gets softer.~A harder pluck gives more energy.","Nothing changes.~The amplitude changes.","Plucking harder increases amplitude.|Larger amplitude = louder sound.");
SI("P.8.6.4","Which property of a sound wave determines its PITCH?","Frequency","Amplitude~Amplitude affects loudness.","Wavelength alone~Pitch is described by frequency.","Medium~The medium affects speed.","More vibrations per second (higher frequency) → higher pitch.");
SI("P.8.6.4","A whistle makes a high-pitched sound. Compared to a low-pitched sound, its waves have —","a higher frequency","a lower frequency~Low frequency makes a low pitch.","a larger amplitude~Amplitude affects loudness, not pitch.","no wavelength~Every wave has a wavelength.","High pitch comes from high frequency.");
SO("P.8.6.5","Resonance and instruments","Conduct scientific investigations that describe the behavior of sound when resonance changes (e.g., waves in a stretched string and design of musical instruments).");
SI("P.8.6.5","A guitarist presses a string to make the vibrating part SHORTER. What happens to the pitch?","It gets higher.","It gets lower.~Shorter strings vibrate faster.","It stays the same.~Length affects pitch.","The sound stops.~The string still vibrates.","Shorter strings vibrate faster.|Faster vibration = higher pitch.");
SI("P.8.6.5","A singer holds a note and a nearby glass begins to vibrate. What is this called?","Resonance","Refraction~Refraction is bending of waves.","Absorption~Absorption takes in energy without vibrating to match.","Reflection~Reflection is bouncing back.","When a sound matches an object’s natural frequency, the object vibrates strongly: resonance.");
SI("P.8.6.5","Why does a guitar have a hollow wooden body?","It resonates to make the sound louder.","It makes the strings a lot longer.~The body doesn’t change string length.","It keeps the strings cold.~Temperature isn’t its purpose.","It blocks most of the sound.~It amplifies the sound.","The hollow body vibrates along with the strings.|That resonance makes the sound louder.");
SO("P.8.6.6","Light and color","Obtain and evaluate scientific information to explain the relationship between seeing color and the transmission, absorption, or reflection of light waves by various materials.");
SI("P.8.6.6","Why does a green leaf look green?","It reflects green and absorbs other colors.","It absorbs green and reflects others.~Absorbed light isn’t seen.","It makes its own green light.~Leaves don’t give off light.","It reflects every color equally.~That would look white.","We see the color of light an object reflects.|The leaf reflects green.");
SI("P.8.6.6","Why is a black shirt warmer in the sun than a white shirt?","Black absorbs more light than white.","Black reflects all of the light.~Black absorbs most light.","White absorbs all of the light.~White reflects most light.","Black shirts are thicker.~Color, not thickness, is the reason.","Absorbed light energy turns into heat.|Black absorbs more, so it gets warmer.");
SI("P.8.6.6","Red light shines on a blue shirt. The shirt looks almost black. Why?","It absorbs red and has no blue to reflect.","Red and blue make black.~Mixing light doesn’t work that way here.","The shirt reflects all of the red light.~Then it would look red.","Blue shirts never reflect light.~They reflect blue light.","A blue object reflects blue light.|Under only red light, it absorbs the red and reflects almost nothing.");
SO("E.8.7.1","Rock layers and Earth’s history","Use scientific evidence to create a timeline of Earth’s history that depicts relative dates from index fossil records and layers of rock (strata).","Students will demonstrate an understanding of geological evidence to analyze patterns in Earth’s major events, processes, and evolution in history.");
SI("E.8.7.1","In undisturbed rock layers, where are the OLDEST layers found?","At the bottom","At the top~The top layers formed last.","In the middle~The bottom formed first.","They are all the same age~Layers form one after another.","Layers stack up over time.|In undisturbed layers, the bottom formed first (law of superposition).");
SI("E.8.7.1","What makes a fossil a good INDEX fossil?","It lived for a short time but in many places.","It lived for a very long time in one place.~That can’t pinpoint a time.","It is very large.~Size doesn’t matter.","It is still alive today.~Index fossils mark a past time period.","Index fossils were widespread but existed briefly.|Finding one tells the approximate age of the layer.");
SI("E.8.7.1","A layer of volcanic ash is found between two rock layers. What does it help scientists do?","Match the same time period in different places","Find out what the ancient animals ate~Ash doesn’t show diets.","Measure the temperature of the distant past~Ash isn’t a thermometer.","Prove the rocks are all the same age~The layers above and below differ in age.","An ash layer falls over a wide area at one time.|It marks the same moment in many rock sequences.");
SO("E.8.7.2","The rock cycle and fossils","Create a model of the processes involved in the rock cycle and relate it to the fossil record.");
SI("E.8.7.2","In which type of rock are fossils MOST often found?","Sedimentary","Igneous~Melted rock destroys remains.","Metamorphic~Heat and pressure usually destroy fossils.","Lava~Lava is melted rock; it destroys remains.","Sediment buries organisms gently.|Over time it hardens into sedimentary rock with fossils inside.");
SI("E.8.7.2","Which process turns sedimentary rock into metamorphic rock?","Heat and pressure deep underground","Weathering and erosion at the surface~Those break rock into sediment.","Lava cooling on the surface~That makes igneous rock.","Dissolving in water~That isn’t how metamorphic rock forms.","Great heat and pressure change rock without melting it.|That makes metamorphic rock.");
SI("E.8.7.2","Igneous rock forms when —","melted rock cools and hardens","sediments are pressed together~That forms sedimentary rock.","rock is heated without melting~That forms metamorphic rock.","fossils are buried~Fossils are found in sedimentary rock.","Magma or lava cools into solid igneous rock.");
SO("E.8.7.3","Fossils and the diversity of life","Construct and analyze scientific arguments to support claims that most fossil evidence is an indication of the diversity of life that was present on Earth and that relationships exist between past and current life forms.");
SI("E.8.7.3","Fossils of sea shells are found high on a mountain. What is the BEST explanation?","The area was once under the sea.","Birds carried the shells up the mountain.~That wouldn’t explain whole layers of shells.","Sea animals once lived on mountains.~These animals lived in water.","The shells grew there from the rock.~Shells come from living animals.","Rock that formed under the sea was pushed up by Earth’s forces.");
SI("E.8.7.3","Fossils show that horses long ago were smaller and had several toes. Modern horses are larger with one hoof. This is evidence that —","species change over time","fossils are not accurate~Fossils give real evidence.","horses never existed long ago~The fossils show they did.","all animals stay the same~The horse changed.","Comparing fossils to living species shows changes over time.");
SI("E.8.7.3","Most species that ever lived on Earth are now extinct. What evidence supports this?","The fossil record","Living animals in zoos~Zoos show living species.","Modern weather maps~Weather doesn’t show extinct species.","Rock colors~Colors alone don’t show species.","Fossils preserve many organisms that no longer exist today.");
SO("E.8.7.4","Mass extinctions and change","Use research and evidence to document how evolution has been shaped both gradually and through mass extinction by Earth’s varying geological conditions (e.g., climate change, meteor impacts, and volcanic eruptions).");
SI("E.8.7.4","Many scientists think a huge asteroid impact helped cause the dinosaurs’ extinction. What evidence supports this?","An iridium layer and a crater","Dinosaur bones found in many museums~Bones show dinosaurs lived, not why they died.","Modern birds flying south~That relates to ancestry, not the asteroid.","Fossils of ancient fish in lakes~That isn’t evidence of an impact.","A thin layer rich in iridium appears worldwide.|A huge crater in Mexico dates to the same time.");
SI("E.8.7.4","After a mass extinction, what usually happens to the surviving species over time?","They spread out and form new species.","They all go extinct too.~Survivors often thrive.","They stop changing forever.~Evolution continues.","They turn into the extinct species.~Extinct species don’t return.","Fewer competitors leave open roles.|Survivors diversify into new species.");
SI("E.8.7.4","Which event could cause rapid climate change and mass extinction?","Huge volcanic eruptions lasting years","A single strong thunderstorm in summer~Storms are short and local.","A bright full moon~The Moon’s phases don’t cause extinctions.","A rainy spring season~Normal seasons don’t cause mass extinctions.","Giant eruptions can block sunlight and change climate worldwide.");
SO("E.8.9A.1","Convection and plate movement","Investigate and explain how the flow of Earth’s internal energy drives the cycling of matter through convection currents between Earth’s surface and the deep interior causing plate movements.","Students will demonstrate an understanding that physical processes and major geological events (e.g., plate movement, volcanic activity, mountain building, weathering, erosion) are powered by the sun and the Earth’s internal heat and have occurred over millions of years.");
SI("E.8.9A.1","What MAINLY causes Earth’s tectonic plates to move?","Convection currents in the mantle","Ocean tides along the coasts~Tides don’t move plates.","Strong winds on the surface~Wind is far too weak.","The Moon’s phases~Phases don’t move plates.","Heat from deep inside Earth makes the mantle slowly circulate.|These convection currents drag the plates.");
SI("E.8.9A.1","In a convection current in the mantle, hot material —","rises, cools, and sinks again","sinks to the core and stays there~Hot material rises.","stays in one place~Convection is circulation.","freezes into ice~The mantle is extremely hot.","Hot, less dense rock rises; cooler, denser rock sinks.|This makes a loop.");
SI("E.8.9A.1","Where does the energy that drives plate tectonics come from?","Heat from Earth’s interior","Sunlight hitting the ground~The Sun drives weather, not plates.","Wind blowing over land~Wind is powered by the Sun.","Ocean waves hitting shore~Waves are surface movements.","Earth’s inner heat comes from its formation and from radioactive decay.");
SO("E.8.9A.2","Plate tectonics theory","Explore and debate theories of plate tectonics to form conclusions about past and current movements of rocks at Earth’s surface throughout history.");
SI("E.8.9A.2","Alfred Wegener noticed that the coasts of South America and Africa fit like puzzle pieces. What idea did he propose?","Continental drift","The rock cycle~The rock cycle describes rock changes.","Natural selection~That is from biology.","Superposition~That is about rock layer ages.","Wegener proposed that continents were once joined and drifted apart.");
SI("E.8.9A.2","Why was Wegener’s idea not accepted at first?","He couldn’t explain what moved them.","He had no evidence at all.~He had fossil and rock evidence.","The continents don’t fit together.~They do fit.","Scientists had already found the cause.~The cause was found later.","He couldn’t explain the force.|Later, seafloor spreading and mantle convection provided it.");
SI("E.8.9A.2","Rock samples show the seafloor is YOUNGEST near mid-ocean ridges. What does this show?","New crust forms at the ridges.","The ridges are the oldest places.~They have the youngest rock.","The seafloor never changes.~New crust keeps forming.","Rocks sink at ridges.~Crust forms there.","At ridges, magma rises and makes new crust.|Older crust is pushed away from the ridge.");
SO("E.8.9A.3","Evidence of moving plates","Map land and water patterns from various time periods and use rocks and fossils to report evidence of how Earth’s plates have moved great distances, collided, and spread apart.");
SI("E.8.9A.3","Fossils of the same land reptile are found in both South America and Africa. What is the BEST explanation?","The continents were once joined.","The reptile swam across the ocean.~It was a land reptile.","Two different reptiles evolved exactly the same.~That is very unlikely.","People carried the fossils.~The fossils are in the rock layers.","A land animal couldn’t cross an ocean.|The continents must have been connected.");
SI("E.8.9A.3","Fossils of tropical plants are found in Antarctica. What does this suggest?","Antarctica was once in a warmer place.","Tropical plants can grow in ice.~They need warm climates.","The fossils fell from space.~That isn’t supported.","Antarctica has always been this cold.~Then the plants couldn’t have grown.","Plates move over time.|Antarctica was once closer to the equator.");
SI("E.8.9A.3","Matching rock layers and mountain ranges are found on opposite sides of the Atlantic Ocean. This supports the idea that —","the continents were once connected","the Atlantic Ocean is shrinking fast~It is slowly widening.","mountains form only on islands~The ranges are on continents.","rocks move by themselves~Plates carry rocks.","Matching rocks across an ocean suggest the land was once joined.");
SO("E.8.9A.4","Constructive and destructive forces","Research and assess the credibility of scientific ideas to debate and discuss how Earth’s constructive and destructive processes have changed Earth’s surface at varying time and spatial scales.");
SI("E.8.9A.4","Which is a CONSTRUCTIVE force that builds up land?","Lava cooling to form a new island","A river wearing away a canyon~That is erosion: destructive.","Wind wearing down rocks~That is weathering: destructive.","A landslide~A landslide removes land.","Constructive forces build land.|Volcanoes add new rock.");
SI("E.8.9A.4","The Grand Canyon was carved mostly by —","a river eroding rock for ages","one huge, sudden earthquake~The canyon formed slowly.","a meteor impact~That would make a round crater.","glaciers in one year~Glaciers didn’t carve it, and it took far longer.","Water slowly eroded the rock over a very long time.");
SI("E.8.9A.4","Which change happens over the SHORTEST time?","A landslide","Mountains forming~That takes millions of years.","A canyon being carved~That takes millions of years.","Continents drifting~That takes millions of years.","Some changes are sudden, like landslides and earthquakes.|Others, like mountain building, are very slow.");
SO("E.8.9A.5","Plate boundaries and landforms","Use models that demonstrate convergent and divergent plate movements that are responsible for most landforms and the distribution of most rocks and minerals within Earth’s crust.");
SI("E.8.9A.5","Two continental plates collide. Which landform MOST likely forms?","A mountain range","A mid-ocean ridge~Ridges form where plates pull apart.","A rift valley~Rift valleys form where plates pull apart.","A flat plain~Collisions push land up.","At a convergent boundary, crust crumples and pushes up into mountains.");
SI("E.8.9A.5","At a divergent boundary, plates —","move apart and new crust forms","push together and make mountains~That is convergent.","slide past each other~That is a transform boundary.","stop moving forever~Plates keep moving.","Diverge means move apart.|Magma rises to fill the gap.");
SI("E.8.9A.5","An ocean plate collides with a continental plate and sinks beneath it. What often forms on the continent?","A chain of volcanoes","A mid-ocean ridge~Ridges are underwater divergent zones.","A sand dune~Sand dunes form by wind.","A coral reef~Reefs form in warm shallow seas.","The sinking plate melts, and magma rises.|Volcanoes form on the land above.");
SO("E.8.9A.6","How soil forms","Design and conduct investigations to evaluate the chemical and physical processes involved in the formation of soils.");
SI("E.8.9A.6","Water freezes in a crack in a rock, expands, and splits the rock. This is —","physical weathering","chemical weathering~The rock’s chemicals didn’t change.","deposition~Deposition drops sediment.","erosion~Erosion moves pieces away.","Ice wedging breaks rock into smaller pieces without changing what it’s made of.");
SI("E.8.9A.6","Rain that is slightly acidic slowly dissolves limestone. This is an example of —","chemical weathering","physical weathering~The rock’s substances changed.","deposition~Nothing was dropped off.","compaction~Compaction presses sediments together.","Acid reacts with the rock and changes its chemistry.");
SI("E.8.9A.6","Besides weathered rock, what else makes soil rich for plants?","Decayed plant and animal matter","Small pieces of plastic~Plastic doesn’t add nutrients.","Pure sand with nothing else~Sand alone holds few nutrients.","Melted rock from volcanoes~Melted rock isn’t soil.","Soil = weathered rock + water + air + humus.|Humus adds nutrients.");
SO("E.8.9A.7","Surface water and groundwater","Explain the interconnected relationship between surface water and groundwater.");
SI("E.8.9A.7","Rain soaks into the ground and fills spaces in rock underground. This water is called —","groundwater","surface water~Surface water is in rivers and lakes.","water vapor~Vapor is in the air.","runoff~Runoff flows over the surface.","Water that soaks into the ground becomes groundwater.");
SI("E.8.9A.7","An underground layer of rock that holds and lets water flow through it is an —","aquifer","atmosphere~That is the layer of air.","estuary~An estuary is where rivers meet the sea.","glacier~A glacier is ice on land.","Aquifers store groundwater that wells can pump.");
SI("E.8.9A.7","A factory spills chemicals onto the ground. How could this harm a nearby river?","They seep into groundwater that feeds the river.","Groundwater and rivers are never connected.~They often feed each other.","The chemicals would stay in place forever.~Water carries them.","Soil always removes every chemical.~Soil can’t filter everything.","Groundwater and surface water are connected.|Pollution in one can reach the other.");
SO("E.8.9B.1","Natural hazards","Research and map various types of natural hazards to determine their impact on society.","Students will demonstrate an understanding of natural hazards (volcanic eruptions, severe weather, earthquakes) and construct explanations for why some hazards are predictable and others are not.");
SI("E.8.9B.1","Most earthquakes and volcanoes happen —","along plate boundaries","in the centers of plates~Most activity is at the edges.","only near the equator~They happen at many latitudes.","only in the ocean~Many are on land.","Plates grind, collide, and separate at boundaries.|That is where most quakes and volcanoes occur.");
SI("E.8.9B.1","Mississippi is far from a plate boundary. Which natural hazard affects Mississippi the MOST often?","Hurricanes and tornadoes","Volcanic eruptions~Mississippi has no active volcanoes.","Tsunamis from earthquakes~They are very rare here.","Avalanches~Mississippi has no tall snowy mountains.","Mississippi’s warm, humid weather and Gulf location bring hurricanes and tornadoes.");
SI("E.8.9B.1","Why can hurricanes cause flooding far inland?","They bring very heavy rain over large areas.","They melt snow high in the mountains.~Hurricanes are warm-weather storms.","They cause volcanoes to erupt.~They don’t trigger eruptions.","They only affect the beach and the shore.~Their rain spreads inland.","Hurricanes dump huge amounts of rain as they move over land.");
SO("E.8.9B.2","Predicting hazards","Compare and contrast technologies that predict natural hazards to identify which types of technologies are most effective.");
SI("E.8.9B.2","Which natural hazard can scientists predict days ahead of time?","A hurricane","An earthquake~Exact earthquake timing can’t be predicted.","A sinkhole~Sinkholes usually form suddenly.","A lightning strike in one spot~Exact strike locations can’t be predicted days ahead.","Satellites and weather models track hurricanes as they form and move.");
SI("E.8.9B.2","Which tool measures the shaking of the ground during an earthquake?","A seismometer","A barometer~A barometer measures air pressure.","An anemometer~An anemometer measures wind speed.","A thermometer~A thermometer measures temperature.","Seismometers record ground vibrations from earthquakes.");
SI("E.8.9B.2","Doppler radar is MOST useful for —","spotting rotation inside storms","measuring earthquake shaking~Seismometers do that.","finding underground water~Radar doesn’t map aquifers.","measuring ocean salt~That isn’t radar’s job.","Doppler radar shows wind movement inside storms, which helps warn about tornadoes.");
SO("E.8.9B.3","Community resilience (engineering)","Using an engineering design process, create mechanisms to improve community resilience, which safeguard against natural hazards (e.g., building restrictions in flood or tidal zones, regional watershed management, Firewise construction).");
SI("E.8.9B.3","A town keeps flooding. Which plan BEST reduces future damage?","Limit floodplain building; restore wetlands","Pave more parking lots near the river~Pavement increases runoff.","Build new homes closer to the river~That increases flood risk.","Cut down trees along the banks~Trees help hold soil.","Keeping homes out of flood zones and restoring wetlands lowers flood damage.");
SI("E.8.9B.3","Engineers test model buildings on a shake table. What are they MOST likely testing?","How well the designs survive earthquakes","How well the buildings keep heat in~That needs a different test.","How tall the buildings look~Looks aren’t being tested.","How fast the buildings can be painted~That isn’t a hazard test.","A shake table copies earthquake shaking.");
SI("E.8.9B.3","Which building feature helps homes survive hurricane winds?","Hurricane straps that tie the roof to the walls","Larger windows with no storm shutters~Windows can break.","A flat sheet-metal roof left loose~Loose roofs blow away.","Building right on sand with no foundation~That is unstable.","Straps keep strong winds from lifting the roof off.");
SO("E.8.10.1","Renewable and nonrenewable resources","Read and evaluate scientific information about advancements in renewable and nonrenewable resources. Propose and defend ways to decrease national and global dependency on nonrenewable resources.","Students will demonstrate an understanding that a decrease in natural resources is directly related to the increase in human population on Earth and must be conserved.");
SI("E.8.10.1","Which is a NONRENEWABLE resource?","Natural gas","Wind~Wind keeps blowing.","Sunlight~The Sun keeps shining.","Moving water~Rivers keep flowing.","Natural gas took millions of years to form and is used up much faster than it forms.");
SI("E.8.10.1","Which plan would reduce a country’s use of fossil fuels the MOST?","Building more wind and solar power plants","Building more coal power plants~Coal is a fossil fuel.","Using more cars that run on gasoline~Gasoline comes from oil.","Leaving lights on all day and night~That wastes energy.","Wind and solar replace electricity that would come from coal or gas.");
SI("E.8.10.1","Why is the demand for natural resources increasing?","The human population is growing.","Resources are being made faster.~Most resources form slowly.","Fewer people use electricity.~More people use more electricity.","Factories are closing everywhere.~Demand comes from more people.","More people need more food, water, energy, and materials.");
SO("E.8.10.2","Reducing human impact","Create and defend a proposal for reducing the environmental effects humans have on Earth (e.g., population increases, consumer demands, chemical pollution, deforestation, and change in average annual temperature).");
SI("E.8.10.2","Which action would MOST reduce deforestation?","Recycling paper and planting trees","Using more paper towels~That increases demand for trees.","Clearing forests for parking lots~That is deforestation.","Burning trash in the woods~That harms forests.","Recycling lowers the need to cut trees.|Planting replaces lost trees.");
SI("E.8.10.2","Burning fossil fuels adds carbon dioxide to the air. What effect does this have?","It traps heat and warms the planet.","It cools the planet quickly.~More CO₂ traps more heat.","It makes the ozone layer thicker.~CO₂ doesn’t build ozone.","It has no effect on climate.~CO₂ is a greenhouse gas.","Carbon dioxide is a greenhouse gas.|More of it traps more heat.");
SI("E.8.10.2","A farm’s fertilizer runs into a lake and causes huge algae growth. Fish begin to die. Why?","Decaying algae use up oxygen the fish need.","Algae make the water too cold.~Temperature isn’t the main problem.","Fertilizer gives fish too much food.~Fish die from low oxygen.","The algae eat the fish.~Algae don’t eat fish.","Extra nutrients feed algae.|When algae die, decomposers use up the oxygen.");
SO("E.8.10.3","Renewable energy trade-offs","Using scientific data, debate the societal advantages and disadvantages of technological advancements in renewable energy sources.");
SI("E.8.10.3","What is a DISADVANTAGE of solar power?","It makes less power at night.","It pollutes the air badly.~Solar panels don’t burn fuel.","It will run out soon.~The Sun won’t run out for billions of years.","It needs coal to run.~Solar uses sunlight.","Solar panels need sunlight, so output drops at night or in clouds.");
SI("E.8.10.3","What is an ADVANTAGE of wind power?","It makes electricity without burning fuel.","It works the same even with no wind.~It needs wind.","It is nonrenewable.~Wind is renewable.","It never affects birds or other wildlife.~Turbines can affect birds and bats.","Wind turbines turn wind into electricity with no air pollution.");
SI("E.8.10.3","Which is a disadvantage of building a large dam for hydroelectric power?","It floods land and blocks fish.","It makes a lot of air pollution.~Hydropower doesn’t burn fuel.","It can never make any electricity.~Dams do make electricity.","It uses up all the water forever.~Water keeps flowing.","Dams change rivers, flood habitats, and block fish like salmon.");
SO("E.8.10.4","Capturing thermal energy (engineering)","Using an engineering design process, develop a system to capture and distribute thermal energy that makes renewable energy more readily available and reduces human impact on the environment (e.g., building solar water heaters, conserving home energy).");
SI("E.8.10.4","Students build a solar water heater. Which design choice would heat the water the MOST?","Black pipes under a clear cover","White pipes set in the shade~White reflects light, and shade blocks it.","Shiny silver pipes in the open~Shiny surfaces reflect light.","Pipes with holes in them~Water would leak out.","Black absorbs more sunlight.|A clear cover traps the heat.");
SI("E.8.10.4","Which home improvement saves the MOST heating energy in winter?","Adding insulation","Opening the windows every night~That lets heat escape.","Painting the walls a new color~Paint doesn’t insulate.","Using more lamps in each room~Lamps add little useful heat.","Insulation slows heat from leaving the house.");
SI("E.8.10.4","Two solar heater designs were tested for 1 hour. Which result shows the BETTER design?","The one that heated the water more","The design that was the most colorful~Color alone isn’t the measured result.","The design that used more materials~More material isn’t better by itself.","The design that took longer to build~Build time isn’t the goal.","The goal is to heat water.|Compare the temperature change.");
/* Punnett squares: generated crosses */
(SCI_GEN["L.8.2B.3"]=SCI_GEN["L.8.2B.3"]||[]).push((r,o)=>{
 const T=o.pick(r,[["P","purple flowers","white flowers","pea plants"],["T","tall stems","short stems","pea plants"],["B","black fur","brown fur","guinea pigs"],["R","round seeds","wrinkled seeds","pea plants"],["G","green pods","yellow pods","pea plants"],["F","free earlobes","attached earlobes","people"]]);
 const [L,dom,rec,org]=T,l=L.toLowerCase(),G=[L+L,L+l,l+l],p1=o.pick(r,G),p2=o.pick(r,[L+l,l+l,L+l]);
 const kids=[];for(const a of p1)for(const b of p2)kids.push(a===a.toUpperCase()?a+b:b+a);
 const norm=g=>g[0]===g[0].toUpperCase()?g:g.split("").sort().join(""),ks=kids.map(k=>k.split("").sort((x,y)=>x===L?-1:y===L?1:0).join(""));
 const nRec=ks.filter(k=>k===l+l).length,nHet=ks.filter(k=>k===L+l).length;
 const kind=o.pick(r,["rec","het","dom"]);const pct=n=>`${n*25}%`;
 const ans=kind==="rec"?nRec:kind==="het"?nHet:4-nRec;
 const choices=["0%","25%","50%","75%","100%"].filter(x=>x!==pct(ans));const w=o.shuf(r,choices).slice(0,3);
 const what=kind==="rec"?`have ${rec}`:kind==="het"?`be heterozygous (${L}${l})`:`have ${dom}`;
 const why=v=>{const n=+v.replace("%","")/25;return `Fill in the Punnett square: ${ks.join(", ")}. ${kind==="rec"?`Only ${l}${l} shows ${rec}`:kind==="het"?`Count the ${L}${l} boxes`:`Any box with a ${L} shows ${dom}`}: ${ans} of 4, not ${n}.`};
 return o.fromItem({stem:`In ${org}, ${dom} (${L}) is dominant over ${rec} (${l}). One parent is ${p1}, and the other parent is ${p2}.\nWhat percent of the offspring are expected to ${what}?`,right:pct(ans),w:w.map(v=>[v,why(v)]),
  steps:`Put one parent’s alleles across the top (${p1[0]}, ${p1[1]}) and the other’s down the side (${p2[0]}, ${p2[1]}).|The four boxes are ${ks.join(", ")}.|${kind==="rec"?`${nRec} of 4 boxes are ${l}${l}`:kind==="het"?`${nHet} of 4 boxes are ${L}${l}`:`${4-nRec} of 4 boxes have at least one ${L}`}, so the answer is ${pct(ans)}.`,
  x:{h:["",p1[0],p1[1]],t:[[p2[0],...[p1[0],p1[1]].map(a=>norm(a+p2[0]).split("").sort((x,y)=>x===L?-1:y===L?1:0).join(""))],[p2[1],...[p1[0],p1[1]].map(a=>(a+p2[1]).split("").sort((x,y)=>x===L?-1:y===L?1:0).join(""))]].map(row=>[row[0],"?","?"]),k:"dominant percent offspring"}},r)});

/* ===== Biology (original items) ===== */
SO("BIO.1A.1","Living vs. non-living","Develop criteria to differentiate between living and non-living things.","Students will demonstrate an understanding of the characteristics of life and biological organization.");
SI("BIO.1A.1","Which is a characteristic shared by ALL living things?","They are made of one or more cells.","They can move from place to place.~Plants and many fungi don’t move around.","They breathe air with lungs.~Many organisms have no lungs.","They eat other organisms.~Producers make their own food.","All living things are made of cells, use energy, grow, respond, reproduce, and maintain homeostasis.");
SI("BIO.1A.1","A crystal grows larger in a solution. Why is it NOT considered alive?","It has no cells and no metabolism.","It grows, so it must be alive.~Growth alone doesn’t make something alive.","It is too small to be alive.~Size isn’t a rule for life.","It is clear in color.~Color doesn’t matter.","Crystals grow by adding particles, not by cellular processes.");
SI("BIO.1A.1","Your body sweats to cool down when you are hot. This is an example of —","maintaining homeostasis","reproduction~Reproduction makes offspring.","evolution~Evolution happens over generations.","photosynthesis~Humans don’t photosynthesize.","Homeostasis keeps internal conditions stable.");
SO("BIO.1A.2","Cell theory","Describe the tenets of cell theory and the contributions of Schwann, Hooke, Schleiden, and Virchow.");
SI("BIO.1A.2","Which is one of the three parts of cell theory?","All cells come from existing cells.","All cells have a cell wall.~Animal cells don’t have walls.","All cells have a nucleus.~Bacteria have no nucleus.","Cells can form from nonliving matter.~Cells come only from cells.","Cell theory: all living things are made of cells; cells are the basic unit of life; all cells come from pre-existing cells.");
SI("BIO.1A.2","Robert Hooke looked at cork under a microscope and named the small boxes he saw —","cells","atoms~Atoms are far too small to see that way.","tissues~Tissues are groups of cells.","organs~Organs are made of tissues.","Hooke named cells in 1665 after the small rooms they reminded him of.");
SI("BIO.1A.2","Which scientist concluded that all animals are made of cells?","Theodor Schwann","Matthias Schleiden~Schleiden studied plants.","Rudolf Virchow~Virchow said cells come from cells.","Gregor Mendel~Mendel studied heredity.","Schleiden (plants) and Schwann (animals) helped show all living things are made of cells.");
SO("BIO.1A.3","Levels of organization","Using specific examples, explain how cells can be organized into complex tissues, organs, and organ systems in multicellular organisms.");
SI("BIO.1A.3","Which list goes from SIMPLEST to most complex?","Cell, tissue, organ, organ system","Tissue, cell, organ, organ system~Cells make up tissues.","Organ, tissue, cell, organ system~Cells are simplest.","Cell, organ, tissue, organ system~Tissues come before organs.","Cells form tissues; tissues form organs; organs form systems.");
SI("BIO.1A.3","Cardiac muscle cells work together in the heart wall. Cardiac muscle is an example of —","a tissue","an organ~The heart is the organ.","an organ system~The circulatory system is the system.","an organism~An organism is the whole living thing.","A tissue is a group of similar cells doing the same job.");
SO("BIO.1A.4","Are viruses alive?","Use evidence from current scientific literature to support whether a virus is living or non-living");
SI("BIO.1A.4","Which evidence BEST supports that viruses are NOT living?","They can’t reproduce outside a host cell.","They contain DNA or RNA as genetic material.~Living things also have genetic material.","They can change and evolve over time.~Living things also change.","They are very small.~Size doesn’t decide life.","Viruses have no cells and no metabolism.|They need a host cell to copy themselves.");
SI("BIO.1A.4","Which trait do viruses share with living things?","They contain DNA or RNA.","They are made of cells.~Viruses are not cells.","They carry out metabolism.~Viruses don’t.","They grow by dividing.~Viruses don’t divide.","Viruses carry genetic material that can mutate.");
SO("BIO.1B.1","Macromolecules","Develop and use models to compare and contrast the structure and function of carbohydrates, lipids, proteins, and nucleic acids (DNA and RNA) in organisms.","Students will analyze the structure and function of the macromolecules that make up cells.");
SI("BIO.1B.1","Which macromolecule is made of amino acids?","Protein","Carbohydrate~Carbohydrates are made of sugars.","Lipid~Lipids are mostly fatty acids and glycerol.","Nucleic acid~Nucleic acids are made of nucleotides.","Amino acids link to form proteins.");
SI("BIO.1B.1","Which macromolecule stores genetic information?","Nucleic acids","Lipids~Lipids store energy and form membranes.","Carbohydrates~Carbohydrates give quick energy.","Proteins~Proteins do jobs; DNA stores the code.","DNA and RNA are nucleic acids that carry genetic information.");
SI("BIO.1B.1","The cell membrane is made mostly of —","lipids","nucleic acids~Nucleic acids carry genes.","starches~Starches store energy in plants.","amino acids~Some proteins are in the membrane, but lipids form it.","A phospholipid bilayer forms the cell membrane.");
SI("BIO.1B.1","Which macromolecule is the body’s main source of QUICK energy?","Carbohydrates","Nucleic acids~They store information.","Proteins~They are used mostly for structure and function.","Lipids~Lipids are long-term energy storage.","Sugars and starches are broken down quickly for energy.");
SO("BIO.1B.2","Enzymes","Design and conduct an experiment to determine how enzymes react given various environmental conditions (i.e., pH, temperature, and concentration). Analyze, interpret, graph, and present data to explain how those changing conditions affect the enzyme activity and the rate of the reactions that take place in biological organisms.");
SI("BIO.1B.2","An enzyme was tested at different temperatures.\nWhat is the BEST explanation for the drop in activity above 37 °C?","High heat changes the enzyme’s shape.","Enzymes work best when very hot.~Activity dropped at high heat.","The enzyme gained more active sites.~Then activity would rise.","Cold made the enzyme stop.~The drop is at high heat.","Most human enzymes work best near 37 °C.|Too much heat denatures them, changing their shape.",{h:["Temperature (°C)","Reaction rate"],t:[["20","12"],["30","25"],["37","40"],["50","15"],["60","3"]]});
SI("BIO.1B.2","What does an enzyme do?","Speeds up a chemical reaction","Stores genetic information~DNA does that.","Makes up the cell wall~Cellulose does that.","Is used up in the reaction~Enzymes can be reused.","Enzymes are catalysts: they lower the energy needed for reactions.");
SI("BIO.1B.2","A stomach enzyme works best at pH 2. What happens if it is placed in a solution with pH 8?","Its activity drops sharply.","It works much faster.~Its best pH is 2.","It turns into a carbohydrate.~It stays a protein.","Nothing changes.~pH affects enzymes.","Each enzyme has an ideal pH.|Far from that pH, it loses its shape and works poorly.");
SO("BIO.1C.1","Organelles","Develop and use models to explore how specialized structures within cells (e.g., nucleus, cytoskeleton, endoplasmic reticulum, ribosomes, Golgi apparatus, lysosomes, mitochondria, chloroplast, centrosomes, and vacuoles) interact to carry out the functions necessary for organism survival.","Students will relate the diversity of organelles to a variety of specialized cellular functions.");
SI("BIO.1C.1","Which organelle releases energy from food through cellular respiration?","Mitochondrion","Chloroplast~Chloroplasts capture light energy.","Ribosome~Ribosomes make proteins.","Golgi apparatus~The Golgi packages proteins.","Mitochondria make ATP from glucose.");
SI("BIO.1C.1","Which organelle builds proteins?","Ribosome","Lysosome~Lysosomes break down waste.","Vacuole~Vacuoles store water and materials.","Nucleus~The nucleus stores DNA.","Ribosomes link amino acids into proteins.");
SI("BIO.1C.1","Which organelle modifies, packages, and ships proteins?","Golgi apparatus","Mitochondrion~Mitochondria make ATP.","Centrosome~Centrosomes help in cell division.","Chloroplast~Chloroplasts do photosynthesis.","Proteins go from the ER to the Golgi, which packages and sends them.");
SO("BIO.1C.2","Prokaryotes and eukaryotes","Investigate to compare and contrast prokaryotic cells and eukaryotic cells, and plant, animal, and fungal cells.");
SI("BIO.1C.2","Which is TRUE about prokaryotic cells such as bacteria?","They have no nucleus.","They have a nucleus.~That is a eukaryotic trait.","They have mitochondria.~Prokaryotes lack membrane-bound organelles.","They are larger than eukaryotic cells.~They are usually smaller.","Prokaryotes have DNA floating in the cytoplasm, not in a nucleus.");
SI("BIO.1C.2","Which structure is found in plant cells but NOT animal cells?","Chloroplasts","Ribosomes~Both have ribosomes.","Mitochondria~Both have mitochondria.","Cell membrane~Both have membranes.","Plant cells have chloroplasts, a cell wall, and a large central vacuole.");
SI("BIO.1C.2","Fungal cell walls are made of a material different from plant cell walls. What is it?","Chitin","Cellulose~Plant walls are made of cellulose.","Starch~Starch is stored food.","Cholesterol~Cholesterol is in animal membranes.","Fungi build their walls from chitin.");
SO("BIO.1C.3","Viruses vs. cells","Contrast the structure of viruses with that of cells and explain why viruses must use living cells to reproduce.");
SI("BIO.1C.3","Why must a virus infect a cell to reproduce?","It has no structures to make its own proteins.","It is too large to survive outside cells.~Viruses are tiny.","It needs sunlight from inside the cell.~Cells don’t give sunlight.","It has a nucleus that needs repair.~Viruses have no nucleus.","Viruses lack ribosomes and enzymes.|They use the host cell’s machinery.");
SI("BIO.1C.3","A virus is MAINLY made of —","genetic material inside a protein coat","a nucleus surrounded by cytoplasm~Viruses aren’t cells.","many organelles~Viruses have no organelles.","a cell wall with chloroplasts inside~Those are plant cell parts.","A virus is DNA or RNA surrounded by a protein capsid.");
SO("BIO.1D.1","Membrane transport","Plan and conduct investigations to prove that the cell membrane is semi- permeable, allowing it to maintain homeostasis with its environment through active and passive transport processes.","Students will describe the structure of the cell membrane and analyze how the structure is related to its primary function of regulating transport in and out of cells to maintain homeostasis.");
SI("BIO.1D.1","Which type of transport requires the cell to use energy (ATP)?","Active transport","Diffusion~Diffusion needs no energy.","Osmosis~Osmosis needs no energy.","Facilitated diffusion~It moves with the gradient, no ATP.","Active transport moves substances against the concentration gradient using ATP.");
SI("BIO.1D.1","The cell membrane is called semi-permeable. What does this mean?","It lets only some substances pass.","It lets every substance through.~It controls what passes.","It lets nothing through.~Some things pass.","It is only half finished.~It is complete.","The membrane controls what enters and leaves to keep homeostasis.");
SI("BIO.1D.1","Oxygen moves from an area of high concentration outside a cell to low concentration inside. This is —","diffusion","active transport~Moving down a gradient needs no energy.","endocytosis~That engulfs large particles.","protein synthesis~That builds proteins.","Particles naturally spread from high to low concentration.");
SO("BIO.1D.2","Tonicity and the sodium-potassium pump","Develop and use models to explain how the cell deals with imbalances of solute concentration across the cell membrane (i.e., hypertonic, hypotonic, and isotonic conditions, sodium/potassium pump).");
SI("BIO.1D.2","A red blood cell is placed in very salty water. What will happen?","Water leaves the cell, and it shrinks.","Water enters the cell, and it swells.~That happens in a hypotonic solution.","Nothing happens.~The solution is hypertonic.","Salt enters and the cell grows.~Water moves out.","Salty water is hypertonic.|Water moves out by osmosis toward higher solute concentration.");
SI("BIO.1D.2","A plant cell in pure water becomes firm. Why?","Water flows in and presses on the wall.","Water flows out of the plant cell.~Pure water is hypotonic, so water enters.","The cell wall dissolves.~The wall holds firm.","Salt flows into the cell quickly.~There is no salt.","Water enters the cell by osmosis.|The wall keeps it from bursting.");
SI("BIO.1D.2","What does the sodium-potassium pump do?","Uses ATP to pump Na⁺ out and K⁺ in","Lets ions diffuse freely across~It moves them against gradients.","Makes proteins at ribosomes~It is a transport protein.","Turns sunlight into sugar~That is photosynthesis.","It pumps 3 Na⁺ out and 2 K⁺ in, using ATP.");
SO("BIO.1E.1","Cell division and differentiation","Construct models to explain how the processes of cell division and cell differentiation produce and maintain complex multicellular organisms.","Students will develop and use models to explain the role of the cell cycle during growth, development, and maintenance in multicellular organisms.");
SI("BIO.1E.1","Muscle cells and nerve cells in your body have the same DNA. Why are they so different?","Different genes are turned on in each.","They have different DNA.~They have the same DNA.","One type has no nucleus.~Both have nuclei.","They come from different people.~They come from the same zygote.","Cell differentiation: each cell type expresses different genes.");
SI("BIO.1E.1","How does a single fertilized egg become a body with trillions of cells?","Mitosis many times, then differentiation","Meiosis many times, then growth~Meiosis makes sex cells.","Binary fission~That is bacterial reproduction.","Absorbing new cells from the food it eats~Cells come from cell division.","The zygote divides by mitosis.|Cells specialize as the body develops.");
SO("BIO.1E.2","The cell cycle and cancer","Identify and describe the changes that occur in a cell during the cell cycle. Explore problems that might occur if the cell does not progress through the cycle correctly (cancer).");
SI("BIO.1E.2","During which part of the cell cycle is DNA copied?","S phase of interphase","Prophase~DNA is already copied by then.","Anaphase~Chromatids separate in anaphase.","Cytokinesis~That splits the cytoplasm.","DNA replicates during the S (synthesis) phase.");
SI("BIO.1E.2","Cancer happens when —","cells divide without normal controls","cells stop dividing completely~Cancer is uncontrolled division.","cells take in too much water~That isn’t cancer.","cells lose their membranes~That isn’t the cause.","Mutations can disable cell cycle checkpoints.|Cells then divide uncontrollably.");
SO("BIO.1E.3","Asexual reproduction","Relate the processes of cellular reproduction to asexual reproduction in simple organisms (i.e., budding, vegetative propagation, regeneration, binary fission). Explain why the DNA of the daughter cells is the same as the parent cell.");
SI("BIO.1E.3","A yeast cell grows a small bump that breaks off as a new cell. This is —","budding","binary fission~Fission splits the cell in two equal halves.","meiosis~Meiosis makes sex cells.","fertilization~No sex cells join.","Budding forms a new organism from an outgrowth.");
SI("BIO.1E.3","Why is a bacterium’s offspring genetically identical to the parent?","Its DNA is copied exactly before it splits.","It receives DNA from two different parents.~There is one parent.","Its DNA is mixed during meiosis.~Bacteria don’t do meiosis.","It makes all-new DNA for each cell.~The DNA is copied.","Binary fission copies the DNA, then divides it equally.");
SO("BIO.1E.4","Stem cells (enrichment)","Enrichment: Use scientific literature to investigate the role of stem cells in regeneration and asexual reproduction, and research applications of stem cells used to solve human medical conditions.");
SI("BIO.1E.4","What makes stem cells useful in medicine?","They can develop into many cell types.","They never divide or grow.~Stem cells divide.","They are found only in plant roots.~Humans have stem cells.","They have no DNA.~They have DNA.","Stem cells can differentiate, so they may replace damaged cells.");
SI("BIO.1E.4","A salamander regrows a lost leg. Which cells make this possible?","Unspecialized cells that form new tissue","Red blood cells from the leg~Red blood cells can’t form a leg.","Cells borrowed from another salamander~The cells are its own.","Viruses~Viruses don’t build tissue.","Regeneration uses cells that can become different tissues.");
SO("BIO.2.1","ATP and ADP","Use models to demonstrate that ATP and ADP are cycled within a cell as a means to transfer energy.","Students will explain that cells transform energy through the processes of photosynthesis and cellular respiration to drive cellular functions.");
SI("BIO.2.1","How does ATP release energy for the cell?","By breaking off a phosphate group","By adding another phosphate group~Adding phosphate stores energy.","By turning back into glucose~ATP doesn’t become glucose.","By leaving the cell~Energy is used inside.","ATP → ADP + phosphate + energy.");
SI("BIO.2.1","ADP becomes ATP again by —","adding a phosphate, using food energy","losing two phosphates at once~That makes AMP.","absorbing water only~Energy is needed.","splitting apart into amino acids~ATP isn’t made of amino acids.","Cellular respiration supplies energy to rebuild ATP from ADP.");
SO("BIO.2.2","Photosynthesis","Develop models of the major reactants and products of photosynthesis to demonstrate the transformation of light energy into stored chemical energy in cells. Emphasize the chemical processes in which bonds are broken, and energy is released, and new bonds are formed, and energy is stored.");
SI("BIO.2.2","Which equation shows photosynthesis?","6CO₂ + 6H₂O + light → C₆H₁₂O₆ + 6O₂","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O~That is cellular respiration.","6O₂ + light → 6CO₂~Sugar must form.","C₆H₁₂O₆ → 2C₂H₆O + 2CO₂~That is fermentation.","Photosynthesis uses CO₂, water, and light to make glucose and oxygen.");
SI("BIO.2.2","Where in the cell does photosynthesis take place?","Chloroplast","Mitochondrion~Respiration happens there.","Nucleus~DNA is stored there.","Ribosome~Proteins are made there.","Chlorophyll in chloroplasts captures light energy.");
SI("BIO.2.2","The oxygen released during photosynthesis comes from —","water molecules","carbon dioxide~The oxygen comes from splitting water.","glucose~Glucose is a product.","the soil~Oxygen comes from water.","Light reactions split water, releasing O₂.");
SO("BIO.2.3","Cellular respiration","Develop models of the major reactants and products of cellular respiration (aerobic and anaerobic) to demonstrate the transformation of the chemical energy stored in food to the available energy of ATP. Emphasize the chemical processes in which bonds are broken, and energy is released, and new bonds are formed, and energy is stored.");
SI("BIO.2.3","What are the reactants of aerobic cellular respiration?","Glucose and oxygen","Carbon dioxide and water~Those are products.","Light and water~Those go into photosynthesis.","ATP and ADP~ATP is a product.","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ATP.");
SI("BIO.2.3","Which produces MORE ATP per glucose molecule?","Aerobic respiration","Anaerobic respiration~It makes only 2 ATP per glucose.","Aerobic and anaerobic make the same amount~Aerobic makes far more.","Neither makes ATP~Both make some ATP.","With oxygen, cells make about 36 ATP per glucose.|Without it, only about 2.");
SO("BIO.2.4","Aerobic vs. anaerobic respiration","Conduct scientific investigations or computer simulations to compare aerobic and anaerobic cellular respiration in plants and animals, using real world examples.");
SI("BIO.2.4","During a hard sprint, your muscles burn. What process causes this?","Lactic acid fermentation","Photosynthesis~Muscles don’t photosynthesize.","Alcoholic fermentation~That happens in yeast.","Aerobic respiration only~Burning comes from lack of oxygen.","Without enough oxygen, muscle cells make lactic acid.");
SI("BIO.2.4","Bread rises because yeast makes which gas during fermentation?","Carbon dioxide","Oxygen~Fermentation doesn’t release oxygen.","Nitrogen~Yeast doesn’t make nitrogen.","Hydrogen~The gas is carbon dioxide.","Alcoholic fermentation makes ethanol and CO₂.");
SO("BIO.2.5","Fermentation in the real world (enrichment)","Enrichment: Investigate variables (e.g., nutrient availability, temperature) that affect anaerobic respiration and current real-world applications of fermentation.");
SI("BIO.2.5","Which food is made using fermentation by bacteria?","Yogurt","Fresh orange juice~No fermentation is needed.","Boiled eggs~Cooking isn’t fermentation.","Raw carrots~They aren’t fermented.","Bacteria ferment milk sugar into lactic acid, making yogurt.");
SI("BIO.2.5","Yeast is mixed with sugar water at 5 °C and at 35 °C. Which will MOST likely produce gas faster?","The 35 °C mixture","The 5 °C mixture~Cold slows yeast.","They will be the same~Temperature affects the rate.","Neither will make gas~Yeast ferments sugar.","Warmth speeds up enzyme activity in yeast, up to a point.");
SO("BIO.3A.1","Meiosis and fertilization","Model sex cell formation (meiosis) and combination (fertilization) to demonstrate the maintenance of chromosome number through each generation in sexually reproducing populations. Explain why the DNA of the daughter cells is different from the DNA of the parent cell.","Students will develop and use models to explain the role of meiosis in the production of haploid gametes required for sexual reproduction.");
SI("BIO.3A.1","A dog’s body cells have 78 chromosomes. How many are in its sperm cells?","39","78~Gametes are haploid.","156~That would be double.","20~Haploid is half: 39.","Meiosis halves the chromosome number: 78 ÷ 2 = 39.");
SI("BIO.3A.1","Why are gametes called haploid?","They have one set of chromosomes.","They have two sets of chromosomes.~That is diploid.","They have no chromosomes.~They have one set.","They are identical to body cells.~They have half the chromosomes.","Haploid (n) = one set.|Fertilization restores the diploid (2n) number.");
SO("BIO.3A.2","Mitosis vs. meiosis","Compare and contrast mitosis and meiosis in terms of reproduction.");
SI("BIO.3A.2","Which describes the products of MEIOSIS?","Four genetically different haploid cells","Two identical diploid body cells~That is mitosis.","Four identical diploid cells~Meiosis makes haploid cells.","One large cell with double the DNA~That isn’t meiosis.","Meiosis: two divisions, four different haploid gametes.");
SI("BIO.3A.2","Crossing over happens during —","prophase I of meiosis","mitosis~Crossing over doesn’t happen in mitosis.","cytokinesis~That divides the cytoplasm.","the S phase~DNA copies then, but doesn’t cross over.","Homologous chromosomes pair up and swap segments in prophase I.");
SO("BIO.3A.3","Chromosomal abnormalities","Investigate chromosomal abnormalities (e.g., Down syndrome, Turner’s syndrome, and Klinefelter syndrome) that might arise from errors in meiosis (nondisjunction) and how these abnormalities are identified (karyotypes).");
SI("BIO.3A.3","When chromosomes fail to separate properly during meiosis, it is called —","nondisjunction","crossing over~That is a normal exchange.","independent assortment~That is normal sorting.","fertilization~That joins gametes.","Nondisjunction can give a gamete an extra or missing chromosome.");
SI("BIO.3A.3","Down syndrome is usually caused by —","an extra copy of chromosome 21","a missing X chromosome in a female~That is Turner syndrome.","an extra X in a male~That is Klinefelter syndrome.","a single base change in one gene~Down syndrome is a chromosome number change.","Trisomy 21 means three copies of chromosome 21.");
SI("BIO.3A.3","What is a karyotype used for?","Looking at an organism’s chromosomes","Measuring a person’s blood sugar~That uses a glucose test.","Counting red blood cells~That is a blood count.","Viewing the proteins in muscle cells~That isn’t a karyotype.","A karyotype arranges chromosomes by size so extra or missing ones can be seen.");
SO("BIO.3B.1","Monohybrid crosses","Demonstrate Mendel’s law of dominance and segregation using mathematics to predict phenotypic and genotypic ratios by constructing Punnett squares with both homozygous and heterozygous allele pairs.","Students will analyze and interpret data collected from probability calculations to explain the variation of expressed traits within a population.");
SI("BIO.3B.1","What is the genotypic ratio of offspring from an Aa × Aa cross?","1 AA : 2 Aa : 1 aa","3 AA : 1 aa~That mixes genotype and phenotype.","1 AA : 1 aa~Heterozygotes also appear.","4 Aa : 0 aa~That would be AA × aa.","The Punnett square gives AA, Aa, Aa, aa.");
SI("BIO.3B.1","Mendel’s law of segregation says that —","each gamete gets just one allele","alleles always blend~Mendel showed they stay separate.","all traits are dominant~Some are recessive.","genes are on the same chromosome~That isn’t segregation.","The two alleles separate when gametes form.");
SO("BIO.3B.2","Dihybrid crosses","Apply Mendel’s law of independent assortment to interpret dihybrid crosses.");
SI("BIO.3B.2","What is the expected phenotypic ratio from an RrYy × RrYy dihybrid cross?","9 : 3 : 3 : 1","3 : 1~That is a monohybrid ratio.","1 : 2 : 1~That is a monohybrid genotype ratio.","1 : 1 : 1 : 1~That comes from RrYy × rryy.","Two traits sorting independently give 9 : 3 : 3 : 1.");
SI("BIO.3B.2","How many different gametes can an RrYy parent make?","4","2~Each gene contributes 2 options: 2 × 2.","8~There are only two genes.","1~The alleles assort independently.","RY, Ry, rY, ry: 4 combinations.");
SO("BIO.3B.3","Non-Mendelian inheritance","Investigate traits that follow non-Mendelian inheritance patterns (e.g., incomplete dominance, codominance, multiple alleles in human blood types, and sex- linkage).");
SI("BIO.3B.3","A red flower and a white flower produce pink offspring. This is —","incomplete dominance","codominance~Codominance shows both colors, like spots.","sex-linkage~This isn’t on a sex chromosome.","complete dominance~Then offspring would be red or white.","In incomplete dominance, the heterozygote is a blend.");
SI("BIO.3B.3","A person with blood type AB has both A and B markers. This is an example of —","codominance","incomplete dominance~The traits don’t blend.","recessive inheritance~Neither is recessive.","nondisjunction~That is a chromosome error.","Both alleles are fully expressed: codominance.");
SI("BIO.3B.3","Why is red-green color blindness more common in males?","It is X-linked, and males have one X.","Males have two X chromosomes.~Males have XY.","The gene is on the Y chromosome.~It is X-linked.","Females can’t inherit it.~Females can, but less often.","A male with one recessive X allele shows the trait.");
SO("BIO.3B.4","Pedigrees and genetic disorders","Analyze and interpret data (e.g., pedigrees, family, and population studies) regarding Mendelian and complex genetic traits (e.g., sickle-cell anemia, cystic fibrosis, muscular dystrophy, color-blindness, and hemophilia) to determine patterns of inheritance and disease within a family.");
SI("BIO.3B.4","In a pedigree, two unaffected parents have an affected child. The trait is MOST likely —","recessive, with both parents carriers","dominant~A dominant trait would show in a parent.","caused by the environment only, not genes~Pedigrees track inherited traits.","impossible to inherit from parents~It was inherited.","Each parent carried one recessive allele and passed it on.");
SI("BIO.3B.4","In a pedigree chart, what does a half-shaded circle usually show?","A female carrier","An affected male~Males are squares.","An unaffected male~Males are squares.","A deceased person~That uses a slash.","Circles = females, squares = males; half-shaded = carrier.");
SO("BIO.3C.1","DNA, genes, and chromosomes","Develop and use models to explain the relationship between DNA, genes, and chromosomes in coding the instructions for the traits transferred from parent to offspring.","Students will construct an explanation based on evidence to describe how the structure and nucleotide base sequence of DNA determines the structure of proteins or RNA that carry out essential functions of life.");
SI("BIO.3C.1","In DNA, adenine (A) always pairs with —","thymine (T)","guanine (G)~G pairs with C.","cytosine (C)~C pairs with G.","uracil (U)~U is in RNA, not DNA.","Base pairing in DNA: A–T and C–G.");
SI("BIO.3C.1","What is the shape of a DNA molecule?","A double helix","A single straight line~DNA has two strands.","A flat circle~Most DNA in our cells is a double helix.","A cube~DNA is a twisted ladder.","Two strands twist around each other like a spiral ladder.");
SO("BIO.3C.2","Transcription and translation","Evaluate the mechanisms of transcription and translation in protein synthesis.");
SI("BIO.3C.2","During transcription, what is made from a DNA template?","mRNA","Protein~Protein is made during translation.","A new DNA strand~That is replication.","Lipid~Lipids aren’t coded this way.","Transcription copies a gene into messenger RNA.");
SI("BIO.3C.2","Where does translation take place?","At a ribosome","In the nucleus~Transcription happens there.","In the mitochondrion~That makes ATP.","In the Golgi apparatus~That packages proteins.","Ribosomes read mRNA codons and link amino acids.");
SO("BIO.3C.3","Mutations and proteins","Use models to predict how various changes in the nucleotide sequence (e.g., point mutations, and frameshift mutations) will affect the resulting protein product and the subsequent inherited trait.");
SI("BIO.3C.3","Which mutation usually causes the MOST change to a protein?","A frameshift from inserting one base","Changing one base to another that codes for the same amino acid~That is a silent mutation.","A change in a non-coding region~Non-coding changes often have no effect.","A substitution near the end of the gene~That changes at most a little.","Adding or removing a base shifts every codon after it.");
SI("BIO.3C.3","Sickle-cell anemia is caused by a single base substitution. What type of mutation is this?","A point mutation","A frameshift mutation~No bases were added or removed.","Nondisjunction~That affects whole chromosomes.","A deletion of a chromosome~Only one base changed.","One base changes, changing one amino acid in hemoglobin.");
SO("BIO.3C.4","DNA technology and ethics","Research and identify how DNA technology benefits society. Engage in scientific argument from evidence over the ethical issues surrounding the use of DNA technology (e.g., cloning, transgenic organisms, stem cell research, the Human Genome Project, and gel electrophoresis).");
SI("BIO.3C.4","Gel electrophoresis separates DNA fragments by —","size","color~DNA fragments aren’t sorted by color.","temperature~Fragments move by size.","the organism’s age~That doesn’t affect separation.","Smaller fragments move farther through the gel.");
SI("BIO.3C.4","Bacteria given the human insulin gene make insulin for people with diabetes. These bacteria are —","transgenic organisms","clones of humans~They are bacteria.","natural mutants~The gene was inserted.","viruses~They are bacteria.","Transgenic organisms carry genes from another species.");
SI("BIO.3C.4","What was the main goal of the Human Genome Project?","To map the full sequence of human DNA","To clone a human being in a lab~That wasn’t its goal.","To cure every disease~It provided data, not cures.","To count every cell in a human~It sequenced DNA.","Scientists sequenced about 3 billion base pairs of human DNA.");
SO("BIO.3C.5","Genome applications (enrichment)","Enrichment: Investigate current biotechnological applications in the study of the genome (e.g., transcriptome, proteome, individualized sequencing, and individualized gene therapy).");
SI("BIO.3C.5","What is the goal of gene therapy?","To treat a disease by changing a person’s genes","To change a person’s blood type just for fun~Gene therapy treats disease.","To remove all mutations from everyone~That isn’t possible.","To make clones of a person~That is a different technology.","Gene therapy adds, fixes, or switches off genes to treat disease.");
SI("BIO.3C.5","A doctor reads a patient’s DNA to choose the medicine that will work best. This is —","personalized medicine","natural selection~That happens in populations.","fermentation~That is a metabolic process.","photosynthesis~That happens in plants.","Individualized sequencing helps match treatments to a person’s genes.");
SO("BIO.4.1","Origin of life and early cells","Use models to differentiate between organic and chemical evolution, illustrating the steps leading to aerobic heterotrophs and photosynthetic autotrophs.","Students will analyze and interpret evidence to explain the unity and diversity of life.");
SI("BIO.4.1","Early Earth’s atmosphere had almost no oxygen. Which organisms added oxygen to it?","Photosynthetic bacteria","Aerobic animals~Animals use oxygen.","Fungi~Fungi don’t make oxygen.","Viruses~Viruses don’t photosynthesize.","Cyanobacteria released oxygen through photosynthesis.");
SI("BIO.4.1","The Miller-Urey experiment showed that —","organic molecules can form from gases","life forms quickly from rotting meat~That idea was disproven.","cells can form instantly from water~It made molecules, not cells.","oxygen was common on early Earth~It modeled an oxygen-poor atmosphere.","Sparks in a mix of gases produced amino acids.");
SO("BIO.4.2","Evidence for evolution","Evaluate empirical evidence of common ancestry and biological evolution, including comparative anatomy (e.g., homologous structures and embryological similarities), fossil record, molecular/biochemical similarities (e.g., gene and protein homology), and biogeography.");
SI("BIO.4.2","Humans and chimpanzees share about 98% of their DNA. This is an example of —","molecular evidence of ancestry","fossil evidence of ancestry~Fossils are preserved remains.","analogous structures~That compares body parts.","biogeography~That studies where species live.","Similar DNA sequences suggest a recent common ancestor.");
SI("BIO.4.2","Which is an example of a vestigial structure?","The human tailbone","The human heart~It is fully functional.","A bird’s wing~Wings are used.","A fish’s gills~Gills are used.","Vestigial structures are reduced and have little function now.");
SO("BIO.4.3","Cladograms","Analyze cladograms/phylogenetic trees to illustrate relatedness between species.");
SI("BIO.4.3","On a cladogram, two species that share the MOST recent branch point are —","the most closely related","the least related~Recent branching means close relationship.","the same species~They are separate species.","not related~They share an ancestor.","The closer the branch point, the more recent the common ancestor.");
SI("BIO.4.3","What do the branch points (nodes) on a phylogenetic tree represent?","Common ancestors","Extinct planets~They show ancestors.","Each organism’s age~They show splits from ancestors.","Food sources~Trees show relationships.","Each node is a common ancestor where lineages split.");
SO("BIO.4.4","Changing environments and adaptation","Design models and/or use simulations to investigate the interaction between changing environments and genetic variation in natural selection leading to adaptations in populations and differential success of populations.");
SI("BIO.4.4","A pesticide is sprayed on crops for years and becomes less effective. Why?","Resistant insects survived and reproduced.","The insects learned to avoid it.~Resistance is genetic.","The pesticide created resistance genes.~The genes were already present.","All insects died out.~The survivors were resistant.","Variation + selection pressure → resistant insects become common.");
SI("BIO.4.4","Why is genetic variation important for a population facing a new disease?","Some individuals may survive and reproduce.","It guarantees every individual survives.~Not all will survive.","It prevents any change.~Variation enables change.","It stops natural selection.~Selection acts on variation.","Variation gives a population a better chance that some are resistant.");
SO("BIO.4.5","Darwin’s theory","Use Darwin's Theory to explain how genetic variation, competition, overproduction, and unequal reproductive success acts as driving forces of natural selection and evolution.");
SI("BIO.4.5","A fish lays 1,000 eggs, but only a few survive. Which part of natural selection is this?","Overproduction","Speciation~That is forming new species.","Homeostasis~That is internal balance.","Mutation~A mutation is a DNA change.","Organisms produce more offspring than can survive.");
SI("BIO.4.5","In natural selection, “fitness” means —","reproductive success","physical strength~Strength matters only if it helps reproduction.","running speed~Speed isn’t always the measure.","size~Larger isn’t always fitter.","Fitness is how many surviving offspring an organism leaves.");
SO("BIO.4.6","Speciation mechanisms","Construct explanations for the mechanisms of speciation (e.g., geographic, and reproductive isolation).");
SI("BIO.4.6","Two populations of birds live in the same forest but sing different songs and no longer mate. This is —","reproductive isolation","geographic isolation~They live in the same place.","convergent evolution~That is about similar traits.","homeostasis~That is internal balance.","Behavioral differences stop interbreeding: reproductive isolation.");
SI("BIO.4.6","A mountain range rises and separates one population into two. This is —","geographic isolation","behavioral isolation~A physical barrier separates them.","temporal isolation~That involves different breeding times.","genetic drift only~The barrier is geographic.","A physical barrier keeps groups apart.");
SO("BIO.4.7","Disease agents and selection (enrichment)","Enrichment: Construct explanations for how various disease agents (bacteria, viruses, chemicals) can influence natural selection.");
SI("BIO.4.7","Why does overusing antibiotics lead to resistant bacteria?","It leaves resistant bacteria to multiply.","It makes bacteria stronger by feeding them.~Antibiotics don’t feed bacteria.","It turns viruses into bacteria.~That can’t happen.","It stops all mutations.~Mutations still occur.","The antibiotic is a selection pressure.");
SI("BIO.4.7","In regions where malaria is common, the sickle-cell allele is more frequent. Why?","Carriers have some resistance to malaria.","The allele causes malaria.~It protects carriers.","Malaria creates the allele.~The allele already existed.","People there have no genetic variation.~They have variation.","Heterozygotes are more likely to survive malaria, so the allele persists.");
SO("BIO.5.1","Ecological hierarchy","Illustrate levels of ecological hierarchy, including organism, population, community, ecosystem, biome, and biosphere.","Students will Investigate and evaluate the interdependence of living organisms and their environment.");
SI("BIO.5.1","All the white-tailed deer in a forest make up a —","population","community~A community includes all species.","ecosystem~An ecosystem includes nonliving parts.","biome~A biome is a large region.","A population is one species in one area.");
SI("BIO.5.1","Which level includes both living things and the nonliving environment?","Ecosystem","Population~Only one species.","Community~Only living things.","Organism~Only one individual.","An ecosystem = community + abiotic factors.");
SO("BIO.5.2","Matter cycles","Analyze models of the cycling of matter (e.g., carbon, nitrogen, phosphorus, and water) between abiotic and biotic factors in an ecosystem and evaluate the ability of these cycles to maintain the health and sustainability of the ecosystem.");
SI("BIO.5.2","Which organisms convert nitrogen gas into a form plants can use?","Nitrogen-fixing bacteria","Mushrooms and other fungi~Fungi decompose.","Earthworms in the soil~They mix soil.","Algae only~Bacteria do most nitrogen fixing.","Bacteria in soil and root nodules fix nitrogen.");
SI("BIO.5.2","Which cycle has NO major gas phase in the atmosphere?","The phosphorus cycle","The carbon cycle~CO₂ is a gas.","The nitrogen cycle~N₂ is a gas.","The water cycle~Water vapor is a gas.","Phosphorus cycles through rocks, soil, water, and living things.");
SO("BIO.5.3","Greenhouse gases and climate","Analyze and interpret quantitative data to construct an explanation for the effects of greenhouse gases on the carbon dioxide cycle and global climate.");
SI("BIO.5.3","The table shows atmospheric CO₂ and average global temperature change.\nWhat do the data suggest?","Rising CO₂ is linked to rising temperatures.","CO₂ and temperature are not related at all.~They rise together.","Temperatures fell as CO₂ levels rose.~Temperatures rose.","CO₂ levels fell over time.~CO₂ rose.","Both columns increase together, showing a positive correlation.",{h:["Year","CO₂ (ppm)","Temperature change (°C)"],t:[["1980","339","+0.3"],["2000","369","+0.4"],["2020","414","+1.0"]]});
SI("BIO.5.3","Which gas is the MOST important greenhouse gas released by burning fossil fuels?","Carbon dioxide","Oxygen~Oxygen isn’t a greenhouse gas.","Nitrogen~Nitrogen isn’t a greenhouse gas.","Helium~Helium isn’t produced by burning fuel.","Burning coal, oil, and gas releases CO₂, which traps heat.");
SO("BIO.5.4","Energy flow and pyramids","Develop and use models to describe the flow of energy and amount of biomass through food chains, food webs, and food pyramids.");
SI("BIO.5.4","Why are there usually fewer top predators than producers in an ecosystem?","About 90% of energy is lost at each level.","Predators make their own energy from sunlight.~They get energy from prey.","Producers eat predators.~Energy flows upward.","Top predators don’t need much energy.~All organisms need energy.","Only about 10% of energy passes to the next level.");
SO("BIO.5.5","Symbiosis and interactions","Evaluate symbiotic relationships (e.g., mutualism, parasitism, and commensalism) and other co-evolutionary (e.g., predator-prey, cooperation, competition, and mimicry) relationships within specific environments.");
SI("BIO.5.5","Bees get nectar from flowers, and flowers get pollinated. This relationship is —","mutualism","parasitism~Neither is harmed.","commensalism~Both benefit.","competition~They aren’t competing.","Both organisms benefit: mutualism.");
SI("BIO.5.5","A tick feeds on a dog’s blood. This relationship is —","parasitism","mutualism~The dog is harmed.","commensalism~The dog is harmed.","predation~The tick doesn’t kill the dog right away.","One benefits and the other is harmed: parasitism.");
SI("BIO.5.5","A harmless king snake has colors similar to a venomous coral snake. This is —","mimicry","mutualism~The snakes don’t help each other.","competition~This is about looking alike.","parasitism~Neither feeds on the other.","Copying warning colors helps the harmless snake avoid predators.");
SO("BIO.5.6","Population growth and limits","Analyze and interpret population data to define limiting factors, both density- dependent and density-independent. Use graphical representations (growth curves) to illustrate the carrying capacity within ecosystems.");
SI("BIO.5.6","A population grows quickly, then levels off. The level where it stays is called the —","carrying capacity","birth rate~Birth rate is how fast offspring are born.","limiting factor~Limiting factors cause the leveling.","growth rate~Growth slows to zero there.","Carrying capacity is the largest population an environment can support.");
SI("BIO.5.6","Which is a DENSITY-INDEPENDENT limiting factor?","A hurricane","Disease spreading in a crowd~Disease spreads more in dense groups.","Competition for food~Competition rises with density.","Predation~Predation often depends on density.","Natural disasters affect populations regardless of size.");
SO("BIO.5.7","Ecological succession","Investigate and evaluate factors involved in primary and secondary ecological succession using local, real-world examples.");
SI("BIO.5.7","A forest grows back on a farm field that was abandoned. This is —","secondary succession","primary succession~Soil already exists.","nondisjunction~That is a genetic error.","eutrophication~That involves extra nutrients in water.","Secondary succession happens where soil remains after a disturbance.");
SI("BIO.5.7","Which organisms are usually the FIRST to grow on bare rock in primary succession?","Lichens and mosses","Tall oak trees~Trees come much later.","Grasses only~Soil must form first.","Large mammals~Animals come later.","Pioneer species like lichens help break rock into soil.");
SO("BIO.5.8","Solving ecological problems (enrichment)","Enrichment: Use an engineering design process to create a solution that addresses changing ecological conditions (e.g., climate change, invasive species, loss of biodiversity, human population growth, habitat destruction, biomagnification, or natural phenomena).");
SI("BIO.5.8","A pesticide builds up in a lake’s fish and eagles. Which solution BEST addresses this biomagnification?","Stop using the pesticide near the lake","Add more fish to the lake~More fish won’t remove the pesticide.","Feed the eagles more fish~That increases their dose.","Use the pesticide only in winter~It would still build up.","Removing the source stops the buildup through the food chain.");
SI("BIO.5.8","Which design MOST helps wildlife cross a busy highway safely?","A wildlife overpass with plants on it","A taller speed limit sign by the road~Signs don’t stop animals.","Brighter road lights~Lights may confuse animals.","Removing all of the nearby trees~That destroys habitat.","Overpasses connect habitats and reduce collisions.");
SO("BIO.5.9","Biomimicry (enrichment)","Enrichment: Use an engineering design process to investigate and model current technological uses of biomimicry to address solutions to real-world problems.");
SI("BIO.5.9","Velcro was inspired by burrs that stuck to a dog’s fur. This is an example of —","biomimicry","genetic engineering~No genes were changed.","natural selection~This is a human design.","cloning~Nothing was copied genetically.","Biomimicry copies designs from nature to solve human problems.");
SI("BIO.5.9","Engineers studied the shape of a kingfisher’s beak to redesign a high-speed train’s nose. What problem were they solving?","Loud noise when entering tunnels","Too many passengers in each car~Shape doesn’t change seating.","Bad food on the train~That isn’t engineering.","Slow ticket sales at the station~Design solved a noise problem.","The beak’s shape lets the bird dive with little splash, inspiring a quieter train nose.");
/* generated: Punnett crosses, base pairing, and the 10% rule */
