SG("P.7.5B.2",(r,o)=>{const k=o.pick(r,["heatV","coolV","squeezeP","heatP","expandP"]);const st={heatV:"A balloon is warmed in the sun. The pressure stays about the same. What happens to its volume?",coolV:"A balloon is put in a freezer. What happens to its volume?",squeezeP:"A gas is pushed into half the space at the same temperature. What happens to its pressure?",heatP:"A sealed, rigid can of gas is heated. What happens to the pressure inside?",expandP:"A gas is given twice as much space at the same temperature. What happens to its pressure?"}[k];
 const right={heatV:"It increases.",coolV:"It decreases.",squeezeP:"It increases.",heatP:"It increases.",expandP:"It decreases."}[k];
 return o.fromItem({stem:st,right,w:[[right==="It increases."?"It decreases.":"It increases.","Think about how fast the gas particles move and how much room they have."],["It stays exactly the same.","Changing temperature or space changes a gas."],["It drops to zero.","The gas is still there and still pushing."]],steps:/heat/.test(k)?"Heating makes gas particles move faster.|Faster particles push harder and spread out.":/cool/.test(k)?"Cooling slows gas particles, so they take up less space.":k==="squeezeP"?"Less space means particles hit the walls more often: higher pressure.":"More space means particles hit the walls less often: lower pressure.",x:{}},r)});
SG("P.7.5B.1",(r,o)=>{const [s,pl]=o.pick(r,[["A metal jar lid",0],["Railroad tracks",1],["The air in a balloon",0],["The liquid in a thermometer",0],["A sidewalk’s concrete",0]]),hot=o.pick(r,[1,0]);
 return o.fromItem({stem:`${s} ${pl?"are":"is"} ${hot?"heated":"cooled"}. What happens to ${pl?"their":"its"} particles?`,right:hot?"They move faster and spread apart.":"They slow down and move closer together.",w:[[hot?"They slow down and move closer together.":"They move faster and spread apart.",hot?"Adding heat speeds particles up.":"Removing heat slows particles down."],["They stop moving completely.","Particles keep moving at any normal temperature."],["The particles get bigger.","The particles stay the same size; the space between them changes."]],steps:hot?"Heat adds energy, so particles move faster and need more room (expansion).":"Cooling removes energy, so particles slow and pack closer (contraction).",x:{}},r)});
SG("P.7.5B.3",(r,o)=>{const k=o.pick(r,["heat","cool","squeeze"]),m=o.pick(r,k==="squeeze"?["air in a balloon","gas in a cylinder","air in a bike pump"]:["air in a balloon","gas in a cylinder","water in a pot"]);
 const right={heat:"Its density decreases.",cool:"Its density increases.",squeeze:"Its density increases."}[k];
 return o.fromItem({stem:`The ${m} is ${k==="heat"?"heated so it expands":k==="cool"?"cooled so it contracts":"squeezed into a smaller space"}, with no matter added or removed. What happens to its density?`,right,w:[[right==="Its density increases."?"Its density decreases.":"Its density increases.","Density = mass ÷ volume. The mass stays the same."],["Its mass increases.","No matter was added, so the mass doesn’t change."],["Its density stays the same.","The volume changed, so the density changed."]],steps:`Density = mass ÷ volume.|Same mass, ${k==="heat"?"bigger":"smaller"} volume → ${k==="heat"?"lower":"higher"} density.`,x:{k:"density"}},r)});
const ELS=[[1,"Hydrogen","H",1],[2,"Helium","He",4],[3,"Lithium","Li",7],[4,"Beryllium","Be",9],[5,"Boron","B",11],[6,"Carbon","C",12],[7,"Nitrogen","N",14],[8,"Oxygen","O",16],[9,"Fluorine","F",19],[10,"Neon","Ne",20],[11,"Sodium","Na",23],[12,"Magnesium","Mg",24],[13,"Aluminum","Al",27],[14,"Silicon","Si",28],[15,"Phosphorus","P",31],[16,"Sulfur","S",32],[17,"Chlorine","Cl",35],[18,"Argon","Ar",40],[19,"Potassium","K",39],[20,"Calcium","Ca",40]];
SG("P.7.5C.1",(r,o)=>{const [z,nm,sym,m]=o.pick(r,ELS),k=o.pick(r,["el","e","n"]);const ans=k==="el"?nm:k==="e"?String(z):String(m-z);
 const pool=k==="el"?ELS.filter(e=>e[1]!==nm&&Math.abs(e[0]-z)<=3).map(e=>e[1]):[...new Set([z,m,m-z,z+1,m+z].filter(v=>String(v)!==ans).map(String))];
 return o.fromItem({stem:k==="el"?`An atom has ${z} proton${z>1?"s":""}. Which element is it?`:k==="e"?`A neutral atom of ${nm.toLowerCase()} has ${z} protons. How many electrons does it have?`:`An atom of ${nm.toLowerCase()} has ${z} protons and a mass number of ${m}. How many neutrons does it have?`,right:ans,w:o.shuf(r,pool).slice(0,3).map(v=>[v,k==="el"?"The number of protons (atomic number) identifies the element.":k==="e"?"In a neutral atom, electrons equal protons.":"Neutrons = mass number − protons."]),
  steps:k==="el"?`Atomic number ${z} = ${nm} (${sym}).`:k==="e"?`Neutral atom: electrons = protons = ${z}.`:`Neutrons = ${m} − ${z} = ${m-z}.`,x:{k:"protons atom"}},r)});
